export const QUESTION_BANK: BankSection[] = [
  {
    id: "html", label: "HTML", icon: "ti-code", color: "#e34c26",
    questions: [
      { q: "ما الفرق بين العناصر الدلالية والعرضية في HTML5؟", a: "العناصر الدلالية تحمل معنى يصف محتواها: header وnav وmain وarticle وaside وfooter.\nالعرضية كـdiv وspan لا تحمل معنى وتُستخدم للتجميع فقط.\nالدلالية تحسّن SEO وتبني Accessibility Tree صحيحاً تلقائياً.\nقارئات الشاشة تتيح القفز بين landmark regions مباشرة.", senior: "ابنِ الهيكل الدلالي أولاً ثم أضف التصميم — accessibility tree سليم من البداية." },
      { q: "ما وظيفة header وكيف يختلف عن h1؟", a: "header عنصر بنيوي يمثل مقدمة الصفحة أو القسم وقد يضم شعاراً وقائمة تنقل.\nيمكن أن تضم الصفحة headers متعددة: واحد للصفحة وآخر لكل article.\nh1 عنصر نصي يمثل العنوان الرئيسي وهو جزء من تسلسل headings.\nheader لا يعني title — قد يحتوي روابط تنقل فقط دون عنوان.", senior: "header الصفحة = شعار + nav؛ header داخل article = عنوان المقال + بيانات النشر." },
      { q: "ما الفرق بين section وarticle؟", a: "article يمثل محتوى مستقلاً قابلاً للتوزيع بمفرده كمقال أو منشور أو تغريدة.\nsection يجمع محتوى ذا صلة تحت عنوان مشترك ضمن سياق أكبر.\nاختبر article: هل المحتوى منطقي لو نُشر في RSS Feed وحده؟ إن نعم فهو article.\nsection يحتاج heading لتحديد موضوعه وبدونه يُفضَّل div.", senior: "article = محتوى مستقل قابل للنشر منفرداً؛ section = تجميع دلالي ضمن سياق." },
      { q: "ما دور nav وكم مرة يُستخدم في الصفحة؟", a: "nav يمثل مجموعة روابط تنقل رئيسية ويُنشئ navigation landmark.\nيمكن استخدامه أكثر من مرة: nav رئيسي وآخر للتنقل الثانوي أو breadcrumbs.\nلا تُغلف كل مجموعة روابط بـnav بل فقط مجموعات التنقل المهمة.\nأضف aria-label لكل nav إضافي لتمييزها عند وجود أكثر من nav.", senior: "استخدم aria-label='التنقل الرئيسي' على أول nav وaria-label='التنقل الثانوي' على الثاني." },
      { q: "ما وظيفة aside وعلاقتها بالمحتوى الرئيسي؟", a: "aside يمثل محتوى مكملاً مرتبطاً بشكل غير مباشر بالمحتوى المحيط.\nيستخدم للشريط الجانبي والإعلانات وروابط ذات الصلة.\nخارج article هو complementary landmark كاملة، وداخله ملاحظة جانبية.\nلا تضع المحتوى الأساسي داخل aside — فهذا يعني أنه ثانوي غير ضروري.", senior: "aside خارج article = complementary landmark؛ aside داخل article = ملاحظة جانبية." },
      { q: "ما وظيفة figure وfigcaption؟", a: "figure يغلف محتوى مستقلاً مرتبطاً بمحتوى رئيسي كصورة أو رسم أو كتلة كود.\nfigcaption يوفر وصفاً أو عنواناً لمحتوى figure ويكون أول أو آخر عنصر فيه.\nربطهما معاً يعطي قارئات الشاشة معلومات وصفية للصورة تلقائياً.\nيمكن وضع صور متعددة في figure واحد مع figcaption مشترك.", senior: "figure + figcaption يحل محل aria-describedby في كثير من حالات الصور المُعلَّقة." },
      { q: "كيف تبني تسلسل heading صحيح؟", a: "ابدأ بـh1 واحد فقط للصفحة يمثل موضوعها الرئيسي.\nتدرّج من h1 لـh6 دون تخطي أي مستوى: بعد h2 يأتي h3 لا h4.\nيمكن الصعود بأي عدد: بعد h4 يمكن أن يأتي h2 عند دخول قسم جديد.\nلا تختر مستوى heading بناءً على الحجم البصري بل على الترتيب المنطقي.", senior: "اختبر headings بـHeadingsMap extension أو Lighthouse لاكتشاف القفزات." },
      { q: "ما landmark regions وما دورها مع قارئات الشاشة؟", a: "Landmarks مناطق رئيسية في الصفحة تُعرَّف بعناصر HTML الدلالية أو ARIA roles.\nheader=banner، nav=navigation، main=main، footer=contentinfo، aside=complementary.\nقارئات الشاشة توفر اختصارات للقفز المباشر بينها دون قراءة كل الصفحة.\nصفحة بدون landmarks كافية تُجبر المستخدم على قراءة كل المحتوى سطراً بسطر.", senior: "صفحة بدون main landmark تُعقّد التنقل — NVDA وVoiceOver يعتمدان عليها أساساً." },
      { q: "ما أنواع input المدعومة في HTML5؟", a: "النصية: text وpassword وemail وurl وtel وsearch.\nالرقمية والنطاق: number وrange.\nالتاريخ والوقت: date وtime وdatetime-local وmonth وweek.\nالاختيار والخاصة: checkbox وradio وfile وcolor وhidden وsubmit وreset.", senior: "استخدم inputmode='decimal' لإظهار لوحة أرقام دون قيود type=number." },
      { q: "ما الفرق بين input type=email وtype=url في التحقق؟", a: "type=email يتحقق من وجود @ وجزء نطاق لكنه يقبل أشكالاً غير صالحة فعلياً.\ntype=url يتحقق من وجود بروتوكول http/https/ftp لكنه متساهل نسبياً.\nكلاهما يمنع إرسال النموذج بقيمة خاطئة مع رسالة خطأ تلقائية.\nالتحقق الحقيقي يجب أن يكون دائماً في الخادم.", senior: "لا تعتمد على type=email وحده — استخدم regex أو خدمة تحقق بجانب إرسال النموذج." },
      { q: "كيف تعمل required وpattern وminlength وmaxlength؟", a: "required يمنع الإرسال عند الفراغ ويضيف دلالة aria-required تلقائياً.\npattern يقبل Regex بدون / ويتحقق من القيمة الكاملة للحقل.\nminlength الحد الأدنى للأحرف ويُقيّم فقط إذا الحقل غير فارغ.\nmaxlength يوقف الإدخال عند الحد دون إظهار خطأ.\nترتيب التحقق: required ثم minlength ثم pattern.", senior: "أضف title='...' مع pattern لشرح الصيغة المطلوبة — يظهر في رسالة الخطأ التلقائية." },
      { q: "ما وظيفة novalidate في form؟", a: "novalidate يعطل التحقق المدمج في المتصفح عند إرسال النموذج.\nيُستخدم عند تنفيذ منطق تحقق مخصص بالكامل بـJavaScript.\nلا يؤثر على input.checkValidity() من JavaScript.\nيمكن إضافة formnovalidate على زر submit محدد بدلاً من النموذج كله.", senior: "في React استخدم novalidate دائماً مع React Hook Form لتجنب تعارض التحقق." },
      { q: "ما دور fieldset وlegend في النماذج؟", a: "fieldset يجمع عناصر النموذج ذات الصلة في إطار منطقي ومرئي.\nlegend يوفر عنواناً وصفياً للمجموعة ويُقرأ مع كل حقل بقارئات الشاشة.\nيُستخدم أساساً مع radio buttons وcheckboxes المرتبطة بسؤال واحد.\nيمكن تعطيله بـdisabled على fieldset مما يعطل جميع عناصره دفعة.", senior: "fieldset+legend الوحيد الذي يربط مجموعة radio ببيانها الوصفي بشكل semantic صحيح." },
      { q: "ما الطريقتان لربط label بـinput؟", a: "الأولى: for attribute في label يساوي id الـinput ويعمل حتى لو كانا في أماكن مختلفة.\nالثانية: تغليف الـinput داخل label مباشرة دون الحاجة لـid.\nكلتاهما تزيد مساحة النقر: النقر على نص label يُفعّل الـinput.\nتجنب placeholder كبديل عن label لأنه يختفي عند الكتابة.", senior: "اختبر accessibility بإخفاء label بصرياً مع الإبقاء عليها في DOM بـsr-only." },
      { q: "ما الفرق بين select وdatalist؟", a: "select قائمة منسدلة مغلقة لا يمكن للمستخدم الخروج عن خياراتها.\ndatalist يقدم اقتراحات بينما يسمح بكتابة قيمة حرة غير موجودة في القائمة.\ndatalist مرتبط بـinput عبر list attribute مما يجمع مرونة النص وراحة الاقتراحات.\nselect أفضل للقوائم المغلقة كالدول؛ datalist أفضل للبحث التكميلي.", senior: "datalist مثالي لحقول المدن والعناوين: يقترح لكن لا يُقيّد." },
      { q: "ما أنواع button وما وظيفة كل نوع؟", a: "type=submit يرسل النموذج وهو السلوك الافتراضي عند عدم تحديد النوع.\ntype=reset يعيد جميع حقول النموذج لقيمها الافتراضية.\ntype=button لا يفعل شيئاً تلقائياً ويُستخدم مع JavaScript handlers.\nأبداً لا تترك button بدون type داخل form — قد يتصرف كـsubmit.", senior: "الخطأ الشائع: button بدون type داخل form يُفعّل submit — دائماً حدد النوع." },
      { q: "ما ARIA وما الفرق بين role وstate وproperty؟", a: "ARIA هي Accessible Rich Internet Applications لإضافة دلالة إمكانية الوصول.\nroles تعرّف نوع العنصر: role=button وrole=dialog وrole=tabpanel.\nstates تعبّر عن حالة متغيرة: aria-checked وaria-expanded وaria-selected.\nproperties خصائص ثابتة: aria-label وaria-required وaria-haspopup.", senior: "ARIA لا يغير السلوك البصري ولا keyboard behavior — JavaScript مسؤول عن ذلك." },
      { q: "ما الفرق بين aria-label وaria-labelledby وaria-describedby؟", a: "aria-label يوفر نصاً وصفياً مباشراً حين لا يوجد نص مرئي.\naria-labelledby يشير لـid عنصر آخر ليكون عنواناً وله أولوية أعلى من aria-label.\naria-describedby يوفر وصفاً إضافياً أطول يُقرأ بعد الاسم والدور.\nالأولوية: aria-labelledby ثم aria-label ثم label ثم النص الداخلي.", senior: "aria-labelledby يجمع نصوصاً من عدة IDs: aria-labelledby='id1 id2'." },
      { q: "ما aria-hidden وما أضراره عند إساءة الاستخدام؟", a: "aria-hidden=true يخفي العنصر عن شجرة إمكانية الوصول مع أبنائه كلهم.\nيُستخدم لإخفاء العناصر الزخرفية كالأيقونات والـseparators.\nالخطأ الكارثي: إخفاء محتوى مرئي مهم يخلق تجربتين مختلفتين تماماً.\nلا تضعه على عنصر قابل للتركيز بالـTab — يصل إليه المستخدم لكن القارئ يتجاهله.", senior: "ما يُرى بالعين يجب أن يُقرأ بالشاشة ما لم يكن زخرفياً بحتاً." },
      { q: "ما aria-live وما قيمه الثلاث؟", a: "aria-live يخبر قارئات الشاشة بمراقبة منطقة وإعلان تغييراتها تلقائياً.\npolite ينتظر انتهاء ما يُقرأ ثم يُعلن التغيير — مناسب لمعظم الحالات.\nasserive يقاطع ما يُقرأ ويُعلن فوراً — للأخطاء الحرجة والتنبيهات العاجلة.\noff القيمة الافتراضية — لا تُعلن عن التغييرات تلقائياً.", senior: "أنشئ aria-live region عند تهيئة الصفحة — بعض القراء يتجاهل الإضافة اللاحقة." },
      { q: "ما aria-expanded وكيف تستخدمه مع القوائم المنسدلة؟", a: "aria-expanded يُعلم قارئات الشاشة بحالة عنصر قابل للتوسيع: true عند الفتح وfalse عند الإغلاق.\nيُضاف على الزر الذي يتحكم في التوسيع لا على المحتوى المنسدل نفسه.\nيجب تحديثه بـJavaScript عند كل تغيير في الحالة.\nاقرنه بـaria-controls='id-of-panel' للربط بين الزر والمحتوى.", senior: "button[aria-expanded=false] + div[hidden] = نمط accordion صحيح دلالياً وكاملاً." },
      { q: "ما الفرق بين tabindex=0 وtabindex=-1؟", a: "tabindex=0 يُضيف العنصر لترتيب Tab الطبيعي بناءً على موضعه في DOM.\ntabindex=-1 يُبعد العنصر من ترتيب Tab لكن يبقى قابلاً للتركيز برمجياً بـ.focus().\ntabindex > 0 يغير ترتيب Tab الطبيعي وهو مكروه لأنه يُربك المستخدمين.\nالعناصر التفاعلية الأصلية كـbutton وa وinput لها tabindex=0 افتراضياً.", senior: "استخدم tabindex=-1 لـfocus trap المؤقت في modal ثم أعد التركيز للزر المُفتِح." },
      { q: "متى تستخدم tabindex موجباً وما مشاكله؟", a: "tabindex موجب يُحدد ترتيباً مخصصاً للتنقل بـTab بين العناصر.\nيخلق مشكلة حين يُحدث ترتيباً مختلفاً عن الترتيب البصري المتوقع.\nيُفضي لتجربة محيرة: المستخدم يضغط Tab لكن التركيز يقفز بشكل غير متوقع.\nالتوصية: أعد ترتيب DOM نفسه ليعكس الترتيب المنطقي بدلاً من tabindex موجب.", senior: "tabindex موجب = code smell — إذا احتجته فغالباً ترتيب DOM الأساسي خاطئ." },
      { q: "كيف تنفذ focus trap في modal؟", a: "احصل على جميع العناصر القابلة للتركيز داخل الـmodal عند فتحه.\nاستمع لـkeydown: Tab على آخر عنصر → أعد للأول، Shift+Tab على الأول → أعد للأخير.\nانقل التركيز تلقائياً لأول عنصر قابل للتركيز فور فتح الـmodal.\nعند إغلاق الـmodal أعد التركيز للعنصر الذي فتحه.", senior: "focus-trap-react أو عنصر dialog الأصلي مع showModal() يتولى هذا تلقائياً." },
      { q: "ما skip link وكيف تنفذها؟", a: "Skip link رابط خفي في أعلى الصفحة يسمح بتخطي التنقل للمحتوى الرئيسي مباشرة.\nتنفيذها: a[href='#main-content'] في بداية body مع main[id='main-content'].\nتكون مخفية بصرياً لكن تظهر عند التركيز بـCSS position مطلق.\nWCAG 2.4.1 تتطلبها لتجنب إعادة التنقل المتكرر في كل صفحة.", senior: "أضف skip links لكل landmark رئيسي: تخطي التنقل، تخطي السايدبار، الذهاب للبحث." },
      { q: "ما meta charset=UTF-8 ولماذا تأتي أولاً؟", a: "UTF-8 ترميز موصى به لجميع صفحات الويب لدعمه جميع لغات العالم.\nmeta charset يجب أن يكون في أول 1024 byte لضمان تفسير صحيح للترميز.\nبدونه يخمن المتصفح الترميز وقد يفشل مع الأحرف غير اللاتينية.\nيجب أن يتطابق charset في HTTP Content-Type header مع charset في HTML.", senior: "meta charset يجب أن يسبق meta viewport وأي عنوان في head — متطلب أمني أيضاً." },
      { q: "ما المحتوى الصحيح لـmeta viewport؟", a: "القيمة الموصى بها: name='viewport' content='width=device-width, initial-scale=1'.\nwidth=device-width يجعل الـviewport يساوي عرض الجهاز الفعلي.\ninitial-scale=1 يضع zoom الابتدائي على 100%.\nتجنب user-scalable=no لأنه يمنع التكبير وهو مشكلة إمكانية وصول وSafari يتجاهله.", senior: "لا تضف maximum-scale أو user-scalable=no — المستخدمون الذين يحتاجون التكبير يعتمدون عليه." },
      { q: "ما meta description وتأثيرها على SEO؟", a: "meta description نص وصفي يظهر تحت عنوان الصفحة في نتائج البحث.\nلا تؤثر مباشرة على تصنيف البحث لكنها تؤثر على نسبة النقر CTR.\nيُنصح بطول 150-160 حرفاً — ما يزيد يُقصَّر بنقاط.\nيجب أن تكون فريدة لكل صفحة وتعكس محتواها بشكل مُغرٍ.", senior: "اكتب description للمستخدم لا لمحرك البحث — CTR أعلى يعني تصنيفاً أفضل مع الوقت." },
      { q: "ما meta name=robots وما قيمها الشائعة؟", a: "robots يتحكم في سلوك زاحف محرك البحث فيما يخص الفهرسة وتتبع الروابط.\nindex/noindex تسمح أو تمنع الفهرسة في نتائج البحث.\nfollow/nofollow تسمح أو تمنع تتبع الروابط الموجودة في الصفحة.\nnoarchive تمنع عرض نسخة مؤرشفة في نتائج البحث.", senior: "للصفحات الخاصة: noindex,nofollow؛ لإخفاء صفحة مع السماح بتتبع روابطها: noindex,follow." },
      { q: "ما Open Graph وما وسومه الأساسية؟", a: "Open Graph بروتوكول يحدد كيف تُعرض صفحاتك عند مشاركتها على الشبكات الاجتماعية.\nog:title العنوان، og:description الوصف، og:image الصورة، og:url الرابط الكنسي.\nog:type يحدد نوع المحتوى: website أو article أو product.\nصورة og:image يجب أن تكون 1200×630 بكسل على الأقل.", senior: "اختبر بـFacebook Sharing Debugger وLinkedIn Post Inspector قبل الإطلاق." },
      { q: "ما الفرق بين og:title وعنصر title؟", a: "title عنوان الصفحة في تبويب المتصفح ونتائج SEO.\nog:title العنوان الذي يظهر عند مشاركة الرابط اجتماعياً.\nالأفضل تحديدهما منفصلين: title للـSEO أطول، og:title للمشاركة أكثر جذباً.\nبدون og:title بعض المنصات تعود لعنصر title تلقائياً.", senior: "title='منتج - الشركة' مقابل og:title='منتج سيغير طريقة عملك!' — استراتيجية تسويقية." },
      { q: "ما Twitter Card meta وما أنواعها؟", a: "Twitter Card تحدد كيفية عرض الصفحة عند مشاركتها على Twitter/X.\nsummary يعرض صورة صغيرة وعنواناً ووصفاً.\nsummary_large_image يعرض صورة كبيرة فوق العنوان والوصف.\napp يعرض بطاقة تطبيق مع روابط التحميل من المتاجر.", senior: "Twitter تستخدم og:title كاحتياط إذا twitter:title غير موجود — لا تكرر نفس القيمة." },
      { q: "ما canonical link وكيف تحل مشكلة المحتوى المكرر؟", a: "canonical يخبر محركات البحث بالرابط الأصلي المفضل للصفحة.\nيحل تكرار المحتوى عبر URLs مختلفة: https/http، www/بدون www.\nيُستخدم للصفحات المرشحة كـ?sort=price و?sort=name التي تعرض نفس المحتوى.\nيجب أن يكون self-referential على الصفحة الأصلية نفسها.", senior: "دائماً أضف self-canonical على جميع الصفحات حتى بدون تكرار — يمنع مشاكل مستقبلية." },
      { q: "ما hreflang وكيف تستخدمه للمحتوى متعدد اللغات؟", a: "hreflang يخبر محركات البحث بوجود نسخ من الصفحة بلغات أو مناطق مختلفة.\nيُضاف كـlink rel=alternate hreflang='ar' href='...' في head كل نسخة.\nكل صفحة تشير لنفسها وللصفحات الأخرى البديلة بشكل متبادل.\nاستخدم x-default للصفحة الافتراضية عند عدم تطابق أي لغة.", senior: "hreflang='ar' للعربية الكاملة؛ hreflang='ar-SA' للعربية السعودية تحديداً." },
      { q: "ما Structured Data JSON-LD وما فوائده؟", a: "JSON-LD بيانات schema.org مضمنة في script type=application/ld+json.\nيساعد محركات البحث على فهم المحتوى وعرض Rich Results كنجوم التقييم.\nله أولوية على Microdata وRDFa لأنه منفصل عن HTML.\nيدعم أنواعاً متعددة: Article وProduct وEvent وFAQ وBreadcrumbList.", senior: "اختبر بـGoogle Rich Results Test قبل الإطلاق للتأكد من الصيغة الصحيحة." },
      { q: "ما الفرق بين rel=preload وprefetch وpreconnect؟", a: "preload يحمّل المورد بأولوية عالية في نفس الصفحة — ضروري للـLCP image والخطوط.\nprefetch يحمّل موارد للصفحة التالية بأولوية منخفضة في وقت الفراغ.\npreconnect يفتح اتصالاً مسبقاً بنطاق خارجي لتقليل تأخير DNS وTLS.\ndns-prefetch أسرع لكن أقل شمولاً — يحل DNS فقط.", senior: "preload مع as=font وcrossorigin يُحمّل الخطوط قبل اكتشافها في CSS — يقضي على FOIT." },
      { q: "ما الفرق بين script defer وscript async؟", a: "defer يحمّل السكريبت موازياً ثم ينفذه بعد اكتمال HTML بترتيب الظهور.\nasync يحمّل موازياً وينفذ فور الانتهاء مقاطعاً الـparsing بترتيب عشوائي.\ndefer مثالي للسكريبتات التي تعتمد على DOM أو على بعضها.\nasync مثالي للسكريبتات المستقلة مثل analytics.", senior: "سكريبتات نهاية body تُحمَّل بعد DOM تلقائياً لكن defer مع head أوضح وأسرع." },
      { q: "ما type=module في script؟", a: "type=module يجعل السكريبت ES Module يعمل في strict mode تلقائياً ويدعم import/export.\nيتصرف كـdefer تلقائياً: يحمّل موازياً وينفذ بعد parsing.\nله scope منفصل — المتغيرات ليست global تلقائياً.\nيسمح باستخدام import() الديناميكي داخله.", senior: "type=module + nomodule = differential serving: حديث للحديثة، legacy للقديمة." },
      { q: "ما importmap في HTML؟", a: "importmap يعرّف تعيينات لأسماء modules تتيح كتابة import 'react' بدلاً من URL كامل.\nيُعرَّف كـscript type=importmap قبل أي script type=module.\nيحل مشكلة bare import specifiers في المتصفح دون bundler.\nمدعوم في جميع المتصفحات الحديثة منذ 2023.", senior: "importmap خطوة نحو تشغيل ES Modules في المتصفح دون bundler في التطوير." },
      { q: "ما وظيفة عنصر base؟", a: "base يحدد الـURL الأساسي لجميع الروابط النسبية وtarget الافتراضي للروابط.\nيجب أن يكون أول عنصر في head قبل أي مرجع لـURLs أخرى.\nيؤثر على href في link وsrc في img حتى form action.\nمخاطره: يغير سلوك جميع الروابط النسبية مما يُربك SPA routing.", senior: "في React/Vue/Next.js تجنب base — routing frameworks تدير الـURLs بشكل أفضل." },
      { q: "ما DOCTYPE وما يحدث بدونه؟", a: "DOCTYPE تعليمة للمتصفح تحدد معيار تفسير المستند.\nHTML5 يستخدم: <!DOCTYPE html> — أبسط DOCTYPE تاريخياً.\nبدونه يدخل المتصفح quirks mode ويُطبّق قواعد تفسير قديمة ومتضاربة.\nفي quirks mode: box model مختلف وCSS يتصرف بشكل غير متوقع.", senior: "سطر واحد يمنع مشاكل ضخمة — لا سبب لعدم كتابة DOCTYPE في عصر HTML5." },
      { q: "ما وظيفة خاصية lang على html؟", a: "lang تحدد اللغة الأساسية للصفحة وتؤثر على نطق قارئات الشاشة وسلوك المتصفح.\ntُمكّن المتصفح من اختيار قواعد نقل الأسطر والاقتباسات الصحيحة للغة.\nمحركات البحث تستخدمها لفهم لغة المحتوى بشكل أدق.\nيمكن تجاوزها على عناصر فردية: lang='en' على مقطع إنجليزي في صفحة عربية.", senior: "lang='ar' مع dir='rtl' على html دائماً معاً — للنطق الصحيح والتخطيط الصحيح." },
      { q: "ما خاصية dir ومتى تستخدم كل قيمة؟", a: "dir=ltr للغات اليسار-لليمين كالإنجليزية وهو الافتراضي.\ndir=rtl للغات اليمين-لليسار كالعربية والعبرية والفارسية.\ndir=auto يكتشف المتصفح الاتجاه تلقائياً من أول حرف غير محايد.\nيُورَّث من الأب لكن يمكن تجاوزه على أي عنصر.", senior: "استخدم dir=auto مع user-generated content حيث اتجاه النص غير معروف مسبقاً." },
      { q: "لماذا يُفضَّل UTF-8 على encodings أخرى؟", a: "UTF-8 يدعم جميع أحرف Unicode العالمية في ملف واحد دون تبديل encoding.\nهو متوافق مع ASCII مما يعني الملفات الإنجليزية لا تتغير حجماً.\nجميع المتصفحات والخوادم والأدوات الحديثة تدعمه افتراضياً.\nيمنع مشاكل ترميز الأحرف الغريبة في الصفحات متعددة اللغات.", senior: "تعيين charset في HTTP header أعلى أولوية من meta charset — اضبطهما معاً." },
      { q: "ما عنصر picture وكيف يختلف عن img؟", a: "picture يغلف عدة source تعطي المتصفح خيارات بناءً على شروط media وtype.\nيحتوي على sources مع شروط وعنصر img احتياطي إلزامي.\nيسمح بتنسيقات مختلفة: AVIF وWebP للمتصفحات الداعمة وJPEG للبقية.\nيسمح بـArt Direction: صورة مختلفة للموبايل وأخرى للديسكتوب.", senior: "استخدم picture لـArt Direction وimg+srcset لـresolution switching — فرق أساسي." },
      { q: "كيف تعمل srcset وsizes معاً في الصور المستجيبة؟", a: "srcset قائمة بصور بعروض مختلفة مع وصف عرض كل منها: img.jpg 800w, img-lg.jpg 1600w.\nsizes يخبر المتصفح بعرض الصورة في كل حالة: (max-width:600px) 100vw, 50vw.\nالمتصفح يجمع sizes مع srcset ودقة الشاشة ليختار الصورة الأنسب.\nbدون sizes يفترض المتصفح 100vw مما يُحمّل صوراً أكبر من اللازم.", senior: "أداة RespImageLint تكتشف أخطاء srcset وsizes وتقترح قيماً أمثل." },
      { q: "ما الفرق بين w descriptor وx descriptor في srcset؟", a: "w descriptor يصف عرض الصورة الفعلي بالبكسل: 800w تعني الصورة عرضها 800px.\nx descriptor يصف كثافة البكسل: 2x للشاشات عالية الكثافة Retina.\nw+sizes يمنح المتصفح حرية الاختيار الأمثل بناءً على العرض ودقة الشاشة.\nx descriptor أبسط لكن أقل مرونة لأنه لا يراعي عرض العنصر الفعلي.", senior: "w+sizes دائماً أفضل من x — المتصفح يتخذ قرار أذكى بناءً على السياق الكامل." },
      { q: "لماذا يجب تحديد width وheight على img؟", a: "يسمح للمتصفح بحجز المساحة قبل تحميل الصورة منعاً لـCumulative Layout Shift.\nCLS أحد Core Web Vitals الرئيسية التي تؤثر على تصنيف الصفحة في Google.\nالمتصفح الحديث يستخدمهما لحساب aspect-ratio التلقائي حتى مع CSS.\nيمنع القفز المزعج في الصفحة عند التحميل التدريجي للصور.", senior: "CSS aspect-ratio مع width+height في HTML = CLS=0 من أول تحميل — مجاني تماماً." },
      { q: "ما خاصيتا loading وdecoding في img؟", a: "loading=lazy يؤخر تحميل الصورة حتى تقترب من الـviewport — مدعوم أصلياً.\nloading=eager التحميل الفوري وهو الافتراضي.\nلا تضع loading=lazy على صورة LCP — هذا يُعطّل أهم مقياس أداء.\ndecoding=async يسمح للمتصفح بفك ترميز الصورة بشكل غير متزامن.", senior: "LCP image تحتاج loading=eager وpreload — العكس يُعطّل أداء الصفحة كلياً." },
      { q: "ما خصائص video الأساسية؟", a: "controls يُظهر شريط تشغيل مدمج بزر play وصوت وشريط تقدم.\nautoplay يشترط muted لسياسة المتصفحات الحديثة.\nmuted يكتم الصوت وهو ضرورة للـautoplay والفيديوهات الزخرفية.\nposter صورة تظهر قبل التشغيل؛ preload=none يمنع التحميل المسبق.", senior: "فيديوهات الخلفية: autoplay muted loop playsinline — بلا controls وبلا صوت." },
      { q: "ما قيم preload في audio؟", a: "preload=none لا تُحمَّل أي بيانات صوتية مسبقاً — توفر bandwidth.\npreload=metadata يحمّل بيانات الـmetadata فقط: المدة والنوع.\npreload=auto يترك للمتصفح حرية تحميل الملف الصوتي بالكامل.\nالقيمة الافتراضية تختلف بين المتصفحات.", senior: "للـpodcast pages: preload=metadata كافٍ — يحمّل المدة ويتيح للمستخدم القرار." },
      { q: "ما خاصية sandbox في iframe وما قيمها؟", a: "sandbox يُطبّق قيوداً أمنية على محتوى iframe لمنع الأنشطة الضارة.\nbدون قيمة: لا JS ولا نماذج ولا popup ولا same-origin access.\nallow-scripts لتشغيل JavaScript داخل الـiframe.\nالجمع بين allow-scripts وallow-same-origin يُلغي فائدة sandbox فعلياً.", senior: "قاعدة: أضف sandbox على كل iframe خارجي ثم ارفع القيود المطلوبة فقط." },
      { q: "ما الفرق بين SVG inline وSVG في img؟", a: "SVG inline مضمن في HTML يمكن التحكم فيه بالـCSS وJavaScript بالكامل.\nSVG في img يُعامل كصورة عادية: لا وصول للـCSS variables ولا JS.\nSVG inline أفضل للأيقونات التفاعلية والرسوم المتحركة.\nSVG في img أخف في الـHTML وأفضل للـcaching عبر المتصفح.", senior: "SVG sprite مع use href='#icon-id' يجمع ميزة inline مع سهولة الإدارة." },
      { q: "ما canvas وما محدودياته لإمكانية الوصول؟", a: "canvas يوفر سطح رسم bitmap بالـJavaScript — مناسب للألعاب والرسوم التفاعلية.\nيرسم بـAPI رسومية قوية: أشكال ونصوص وصور وتأثيرات.\nمحتواه غير قابل للقراءة بقارئات الشاشة إذ هو مجرد bitmap لا نص دلالي.\nأضف aria-label وصفياً وfallback text داخل عنصر canvas لتحسين accessibility.", senior: "للـdata visualization: SVG أفضل من canvas لإمكانية الوصول والتفاعل والـSEO." },
      { q: "ما عنصر template وما استخداماته؟", a: "template عنصر يحمل HTML لا يُعرض ولا يُنفَّذ عند تحميل الصفحة.\nمحتواه في DocumentFragment غير مرتبط بالـDOM حتى تُدرجه بـJavaScript.\nلا تُحمَّل موارده: الصور والسكريبتات لا تُطلب حتى تُستنسخ.\ncloneNode(true) يُنشئ نسخة منه جاهزة للإدراج في DOM.", senior: "template المكان الصحيح لتعريف هيكل Web Component — غير معالج حتى الاستخدام." },
      { q: "ما عنصر slot في Web Components؟", a: "slot مكان محجوز داخل Shadow DOM يسمح بإدراج محتوى من Light DOM خارجياً.\nالـslot الافتراضي بدون اسم يستقبل أي محتوى لم يُعيَّن لـslot محدد.\nالـslots المسماة: slot name='header' تستقبل العناصر التي لها slot='header'.\nالمحتوى المدرج يبقى في Light DOM لكن يُعرض في مكان الـslot.", senior: "Slots في Web Components = children في React = slot في Vue — composition موحّد." },
      { q: "ما customElements.define وكيف ينشئ عنصراً مخصصاً؟", a: "customElements.define('my-element', MyClass) يسجّل class كعنصر HTML مخصص.\nاسم العنصر يجب أن يحتوي شرطة: my-button — قاعدة منع التعارض مع HTML المستقبلي.\nالـclass يرث HTMLElement أو أي عنصر HTML موجود.\nبعد التسجيل يُستخدم في HTML: <my-button></my-button>.", senior: "Web Components تعمل مع React: React يُدرجها كأي HTML element عادي." },
      { q: "ما الفرق بين Shadow DOM open وclosed؟", a: "attachShadow({mode:'open'}) يسمح للـJS الخارجي بالوصول لـshadowRoot.\nattachShadow({mode:'closed'}) يُعيد null عند محاولة الوصول لـelement.shadowRoot.\nopen يُفيد التطوير والتفاعل مع DevTools وأدوات testing.\nclosed يُوهم بالعزل لكن يمكن تجاوزه بإعادة تعريف attachShadow.", senior: "Shadow DOM لا يوفر أماناً حقيقياً حتى في closed mode — لا تخزن بيانات حساسة فيه." },
      { q: "ما lifecycle callbacks للعناصر المخصصة؟", a: "connectedCallback يُستدعى عند إضافة العنصر للـDOM — تبدأ العمليات وتُضاف event listeners.\ndisconnectedCallback عند الإزالة — تُنظَّف الموارد وتُزال الـlisteners.\nattributeChangedCallback(name, old, new) عند تغيير أي attribute مراقَب.\nstatic get observedAttributes() يحدد الـattributes التي تُفعّل الـcallback.", senior: "connectedCallback ≈ componentDidMount؛ disconnectedCallback ≈ cleanup في useEffect." },
      { q: "ما connectedCallback وdisconnectedCallback؟", a: "connectedCallback يُستدعى عند إدراج العنصر في DOM — الوقت المناسب لبدء العمل.\ndisconnectedCallback عند إزالته — الوقت المناسب لإلغاء timers وإزالة listeners.\nيمكن استدعاء connectedCallback أكثر من مرة إذا أُعيد إدراج العنصر.\nيجب تنظيف جميع الموارد في disconnectedCallback لتجنب memory leaks.", senior: "العنصر يمكن أن يُنقل بين أجزاء DOM — connectedCallback يُستدعى في كل مرة." },
      { q: "ما History API وما الفرق بين pushState وreplaceState؟", a: "History API يسمح بتعديل URL في شريط العنوان دون إعادة تحميل الصفحة.\npushState يُضيف إدخالاً جديداً في التاريخ — زر Back يعود للـURL السابق.\nreplaceState يُحدِّث الإدخال الحالي دون إضافة — Back يتجاوز الصفحة الحالية.\nكلاهما يأخذ: state object وtitle مُهمَل وURL الجديد.", senior: "SPA routing: pushState للتنقل + popstate للاستجابة لزر الرجوع." },
      { q: "كيف يعمل حدث popstate؟", a: "popstate يُطلَق عند ضغط Back/Forward في المتصفح أو استدعاء history.back().\nلا يُطلَق عند استدعاء pushState أو replaceState مباشرة — فقط عند التنقل.\nevent.state يحمل الـstate object الذي مُرّر لـpushState أو replaceState.\nيُستخدم في SPA routing للاستجابة لتنقل المستخدم في التاريخ.", senior: "في React Router: popstate مُدار داخلياً — لا تضف listener يدوي إلا لحالات خاصة." },
      { q: "ما Drag and Drop API وما أحداثها الأساسية؟", a: "draggable=true على العنصر يجعله قابلاً للسحب.\ndragstart يُطلَق عند بدء السحب — هنا تضع البيانات في dataTransfer.\ndragover على الهدف يجب أن يستدعي preventDefault() للسماح بالإفلات.\ndrop يُطلَق عند الإفلات — هنا تقرأ البيانات من dataTransfer.", senior: "Drag and Drop API له قيود على الموبايل — استخدم Pointer Events لدعم اللمس." },
      { q: "ما contenteditable وما مشاكله؟", a: "contenteditable=true يجعل أي عنصر HTML قابلاً للتحرير المباشر.\nيدعم الصيغ الأساسية: Bold وItalic والنسخ واللصق.\nمشاكله: إدراج HTML غير متوقع عند اللصق مما يُنشئ ثغرات XSS.\nتنسيق الـpaste مختلف بين المتصفحات مما يُعقّد توحيد السلوك.", senior: "للمحررات المتقدمة استخدم ProseMirror أو Tiptap بدلاً من contenteditable مباشرة." },
      { q: "ما data attributes وكيف تصل إليها بـJavaScript؟", a: "data attributes خصائص مخصصة تبدأ بـdata- يمكن إضافتها لأي عنصر HTML.\nتُخزن بيانات مخصصة مرتبطة بالعنصر: data-user-id='123'.\nالوصول من JS: element.dataset.userId (الشرطة تتحول لـcamelCase تلقائياً).\nيمكن قراءتها من CSS: content: attr(data-tooltip).", senior: "data attributes للبيانات المرتبطة بالعنصر لا للتنسيق — استخدم CSS classes للتصميم." },
      { q: "ما dialog وما الفرق بين show وshowModal؟", a: "dialog عنصر HTML أصلي للنوافذ الحوارية يوفر behavior مدمج لإمكانية الوصول.\nshow() يُظهر الـdialog بدون overlay وبدون focus trap.\nshowModal() يُظهره مع backdrop ويُقيّد Tab للعناصر الداخلية ويُغلق بـEscape.\nform داخله مع method=dialog يُغلقه عند الإرسال دون Server request.", senior: "dialog.showModal() هو الخيار الأمثل — focus trap وclose-on-Escape مجاني من المتصفح." },
      { q: "ما عنصرا details وsummary؟", a: "details ينشئ accordion يمكن فتحه وإغلاقه بدون JavaScript.\nsummary العنوان الظاهر دائماً وعند النقر عليه يفتح أو يغلق details.\nbدون summary يستخدم المتصفح نصاً افتراضياً مثل 'Details'.\nخاصية open على details تحدد الحالة الابتدائية.", senior: "details+summary = accordion أصلي سريع للـFAQ — لا JavaScript مطلوب على الإطلاق." },
      { q: "ما الفرق بين meter وprogress؟", a: "progress يمثل تقدماً نحو إتمام مهمة: تحميل ملف أو خطوات نموذج.\nprogress بدون value يظهر كـindeterminate spinner/bar.\nmeter يمثل قيمة ضمن نطاق معروف: مستوى بطارية أو حجم تخزين.\nmeter يدعم min وmax وlow وhigh وoptimum لتحديد النطاقات.", senior: "meter مع low وhigh وoptimum يُلوّن تلقائياً في Firefox: أخضر/أصفر/أحمر." },
      { q: "ما وظيفة time وaddress؟", a: "time يمثل تاريخاً أو وقتاً بشكل دلالي مع datetime للآلات: <time datetime='2024-01-01'>.\ndatetime يجب أن يكون بصيغة ISO 8601 ليفهمه المتصفح ومحركات البحث.\naddress يمثل معلومات الاتصال للمقال أو الصفحة — ليس لأي عنوان بريدي.\ntime+datetime يساعد محركات البحث على عرض تاريخ النشر الصحيح في Rich Results.", senior: "time مع datetime = Rich Results مجانية لتاريخ النشر في Google." },
      { q: "ما scope وcolspan وrowspan في جداول HTML؟", a: "scope على th يحدد ما إذا كان heading للصف row أو العمود col أو مجموعة.\ncolspan يجعل خلية تمتد على عدة أعمدة أفقياً.\nrowspan يجعل خلية تمتد على عدة صفوف رأسياً.\ncaption يُضيف وصفاً للجدول يُقرأ أولاً بقارئات الشاشة.", senior: "الجداول للبيانات الجدولية فقط — لا تستخدمها للتخطيط منذ HTML5." },
      { q: "ما أنواع favicon الموصى بها حالياً؟", a: "favicon.ico 32x32 للـlegacy support في المتصفحات القديمة.\nPNG 32x32 مع link rel=icon type=image/png للمتصفحات الحديثة.\nApple Touch Icon PNG 180x180 لأيقونة الصفحة الرئيسية على iOS.\nSVG favicon مع prefers-color-scheme للدعم الديناميكي لـLight/Dark mode.", senior: "SVG favicon هو المستقبل: link rel='icon' type='image/svg+xml' href='icon.svg'" },
      { q: "ما manifest.json وصلته بالـPWA؟", a: "manifest.json يصف التطبيق للمتصفح: الاسم والأيقونات والألوان وطريقة العرض.\nيُعلَن عنه بـlink rel=manifest href='/manifest.json' في head.\nstart_url يحدد الصفحة التي تُفتح عند تشغيل الـPWA.\ndisplay: standalone يُخفي شريط المتصفح لتجربة تشبه التطبيق.", senior: "manifest صحيح شرط أساسي قبل تسجيل Service Worker لقبول الـInstallability." },
      { q: "ما Service Worker وكيف يُسجَّل من HTML؟", a: "Service Worker سكريبت يعمل في خلفية المتصفح منفصلاً عن الصفحة.\nيُسجَّل من JavaScript: navigator.serviceWorker.register('/sw.js').\nيُتيح التخزين المؤقت للموارد والعمل دون اتصال بالإنترنت.\nيجب تقديمه من HTTPS — localhost استثناء للتطوير.", senior: "Service Worker ليس HTML — يُسجَّل من JS بعد DOMContentLoaded." },
      { q: "ما Web Worker وكيف يختلف عن Service Worker؟", a: "Web Worker يعمل في thread منفصل دون وصول للـDOM — للعمليات الثقيلة.\nيتواصل مع الصفحة عبر postMessage وonmessage.\nكل صفحة لها worker خاص بها ولا يُشارك بين Tabs.\nService Worker مُشترك بين جميع Tabs ويستمر حتى بعد إغلاق الصفحة.", senior: "Web Worker مثالي لـAST parsing وImage processing وEncryption دون تجميد الـUI." },
      { q: "ما تأثير HTML minification على الأداء؟", a: "HTML minification يحذف المسافات والتعليقات والأحرف الزائدة من HTML.\nيُقلل حجم الملف بين 10-30% مما يُسرّع التحميل.\nفائدته محدودة مقارنة بـGzip/Brotli compression التي تحقق 70-80% تقليصاً.\nيُطبَّق تلقائياً في معظم Build tools: Vite وNext.js وWebpack.", senior: "Brotli compression يُقلص HTML بنسبة 80%+ — Minification مفيد لكن Compression أهم." },
      { q: "ما critical path HTML وكيف تُحسّنه؟", a: "Critical Path المسار الذي يجب اكتماله قبل أن يتمكن المتصفح من عرض الصفحة.\nيشمل: HTML الأساسي وCSS blocking وJS blocking وكل موارد تعتمد عليها.\nتقليل البيانات في head يُسرّع بدء عرض الصفحة الأول FCP.\nإدراج Critical CSS مضمناً داخل HTML يُسرّع عرض المحتوى فوق الطية.", senior: "PageSpeed Insights يُظهر تحليل Critical Path وما يعيق FCP تحديداً." },
      { q: "ما الترتيب الأمثل لعناصر head؟", a: "أولاً: meta charset لأنه يجب أن يكون في أول 1024 byte.\nثانياً: meta viewport لأثره على التخطيط المبكر.\nثالثاً: preconnect وdns-prefetch لبدء الاتصالات المبكرة.\nرابعاً: preload للموارد الحرجة كـLCP image والخطوط.\nخامساً: CSS blocking، ثم scripts مع defer، أخيراً meta tags أخرى كـOG.", senior: "أداة capo.js تُحلّل head وتقترح الترتيب الأمثل لتحسين أداء التحميل تلقائياً." }
    ]
  },
  {
    id: "css", label: "CSS", icon: "ti-brush", color: "#264de4",
    questions: [
      { q: "ما box model في CSS وما مكوناته؟", a: "box model هو المستطيل الذي يُمثّل كل عنصر HTML في الصفحة.\nيتكون من: content المحتوى الفعلي، padding المسافة الداخلية، border الإطار، margin المسافة الخارجية.\nالعرض الكلي = content + padding × 2 + border × 2 + margin × 2.\nالـmargin لا تُحتسب ضمن عرض العنصر نفسه بل تُبعده عن الجيران.", senior: "تذكّر: outline لا يؤثر على box model ولا يأخذ مساحة — مختلف عن border." },
      { q: "ما الفرق بين content-box وborder-box؟", a: "content-box القيمة الافتراضية: width يمثل المحتوى فقط، يُضاف إليه padding وborder.\nborder-box: width يشمل المحتوى والـpadding والـborder معاً — أسهل للتصميم.\nمع border-box: إذا حددت width:200px وpadding:20px فالمحتوى يصبح 160px.\nالتوصية: * { box-sizing: border-box } في أعلى كل مشروع — يُجمع عليها المجتمع.", senior: "box-sizing: border-box في * يحل 90% من مشاكل تجاوز العرض في التخطيطات." },
      { q: "ما Block Formatting Context وكيف يُنشأ؟", a: "BFC حاوية تُعزل عناصرها عن التدفق الخارجي وتتحكم في كيفية تفاعلها.\nيُنشأ بـ: overflow غير visible، display: flow-root، float، position: absolute/fixed.\ndisplay: flow-root أفضل طريقة لإنشاء BFC دون آثار جانبية.\nالفائدة: يمنع تسرّب float ويمنع margin collapsing مع الأب.", senior: "display: flow-root = BFC نظيف دون الحاجة لـhack قديم مثل overflow: hidden." },
      { q: "ما Inline Formatting Context؟", a: "IFC السياق الذي يتدفق فيه المحتوى الـinline من اليسار لليمين ضمن line boxes.\nكل عنصر inline يُوضع على السطر حتى يمتلئ ثم ينتقل للسطر التالي.\nالمحاذاة العمودية بـvertical-align تعمل فقط ضمن IFC.\nline-height يحدد ارتفاع كل line box ضمن IFC.", senior: "فهم IFC ضروري لمعرفة لماذا vertical-align تعمل على inline لكن لا على block." },
      { q: "ما margin collapsing ومتى يحدث؟", a: "margin collapsing دمج margins المتجاورة من عنصرين بدلاً من جمعها.\nيحدث بين: siblings متجاورة، أب أول وابن أول، أب أخير وابن أخير.\nالناتج دائماً القيمة الأكبر، لا مجموع القيمتين.\nيحدث فقط للـmargins العمودية في normal flow ولا يحدث للـfloat أو grid أو flex.", senior: "margin collapsing لا يحدث في flex containers أو grid containers — استخدمهما لتفاديه." },
      { q: "كيف تُحسب specificity في CSS؟", a: "Specificity تُحسب بأربعة أعداد: [inline, ID, class/attr/pseudo-class, element/pseudo-element].\nInline style = 1,0,0,0؛ ID selector = 0,1,0,0؛ class = 0,0,1,0؛ element = 0,0,0,1.\n!important يتجاوز كل specificity عادية لكنه نفسه يتأثر بالـspecificity.\nالتحديد الأعلى في نفس الرتبة يفوز بغض النظر عن الكمية.", senior: "استخدم specificity calculator في browser DevTools لفهم لماذا rule معين لا يُطبَّق." },
      { q: "ما cascade order في CSS؟", a: "Cascade هو الخوارزمية التي تحدد أي CSS rule تُطبَّق عند التعارض.\nالأولويات بالترتيب: المصدر (UA > author > user)، ثم !important، ثم specificity، ثم order.\nالقاعدة المكتوبة آخراً في نفس الـspecificity تفوز — source order.\nCSS Layers @layer تسمح بالتحكم في الـcascade بشكل صريح.", senior: "@layer تسمح بكتابة utilities بـspecificity منخفضة تتغلب على component styles دون !important." },
      { q: "ما الخصائص التي تُورَّث في CSS وما التي لا تُورَّث؟", a: "الخصائص التي تُورَّث: color وfont-family وfont-size وline-height وtext-align وdirection.\nالخصائص التي لا تُورَّث: background وborder وmargin وpadding وwidth وheight وdisplay.\nيمكن إجبار الوراثة بـinherit: background: inherit على عنصر ابن.\ninitial يعيد الخاصية لقيمتها الأولية الافتراضية غير الموروثة.", senior: "unset = inherit للخصائص الموروثة + initial للخصائص غير الموروثة — مفيد للـreset." },
      { q: "ما الفرق بين initial وinherit وunset وrevert؟", a: "initial يُعيّن الخاصية لقيمتها الافتراضية كما تُحددها مواصفة CSS.\ninherit يجبر الخاصية على وراثة قيمة الأب حتى لو لم تكن موروثة عادة.\nunset = inherit إذا كانت الخاصية موروثة + initial إذا لم تكن.\nrevert يُعيّد الخاصية لقيمة User Agent stylesheet.", senior: "all: unset سلاح قوي لإعادة تعيين كل خصائص عنصر دفعة واحدة." },
      { q: "ما جميع خصائص Flexbox؟", a: "على الحاوية: display:flex، flex-direction، flex-wrap، justify-content، align-items، align-content، gap.\nعلى العناصر: flex-grow، flex-shrink، flex-basis، align-self، order.\nflex: 1 اختصار لـflex: 1 1 0% أي ينمو ويتقلص بالتساوي.\njustify-content للمحور الرئيسي؛ align-items للمحور المتعامد.", senior: "flex: 1 على كل الأبناء يوزع المساحة المتاحة بالتساوي — نمط شائع وقوي." },
      { q: "ما جميع خصائص CSS Grid؟", a: "على الحاوية: grid-template-columns/rows، fr unit، repeat()، auto-fill/auto-fit، minmax().\ngrid-template-areas، grid-column-gap، grid-row-gap، gap.\nعلى العناصر: grid-column، grid-row، span، grid-area.\ngrid-auto-rows/columns للصفوف/الأعمدة الضمنية؛ grid-auto-flow لاتجاه التدفق.", senior: "grid-template-areas مع أسماء دلالية تجعل التخطيط مقروءاً بصرياً في الكود." },
      { q: "ما fr unit في CSS Grid ومتى يُستخدم؟", a: "fr وحدة تمثل كسراً من المساحة المتاحة بعد حسم المسافات الثابتة.\n1fr 1fr 1fr يقسم المساحة إلى ثلاثة أجزاء متساوية.\nrepeat(3, 1fr) اختصار لـ1fr 1fr 1fr.\nminmax(200px, 1fr) يضمن حداً أدنى 200px وينمو لملء المساحة.", senior: "repeat(auto-fill, minmax(250px, 1fr)) = responsive grid بدون media queries." },
      { q: "ما auto-fill وauto-fit في Grid؟", a: "auto-fill يُنشئ أكبر عدد ممكن من الأعمدة بالحجم المحدد حتى لو بقيت فارغة.\nauto-fit يُنشئ الأعمدة ثم يُوسّع الموجودة لملء المساحة المتبقية.\nالفرق يظهر حين عدد العناصر أقل من عدد الأعمدة الممكنة.\nauto-fill مناسب للشبكات الثابتة العرض؛ auto-fit للشبكات التي تتمدد.", senior: "auto-fit + minmax = الأسلوب الأمثل لشبكات المنتجات الداستجيبة دون JS." },
      { q: "ما CSS custom properties وكيف تستخدمها؟", a: "CSS custom properties متغيرات CSS تُعرَّف بـ--اسم: قيمة وتُستخدم بـvar(--اسم).\nتُعرَّف عادة على :root لتكون متاحة لكل الصفحة.\nلها قيمة احتياطية: var(--color, #000) تستخدم #000 إذا لم تكن --color معرّفة.\nيمكن تغييرها من JavaScript: element.style.setProperty('--color', 'red').", senior: "Custom properties موروثة كـcolor — استخدمها لبناء theme system قوي وقابل للتغيير." },
      { q: "ما calc وclamp وmin وmax في CSS؟", a: "calc() تتيح حسابات رياضية بوحدات مختلطة: calc(100% - 2rem).\nmin() تختار القيمة الأصغر: min(50%, 300px) = 50% أو 300px أيهما أصغر.\nmax() تختار القيمة الأكبر: max(200px, 20vw) لضمان حد أدنى للعرض.\nclamp(min, preferred, max) تُحدد قيمة ضمن نطاق: clamp(16px, 4vw, 32px).", senior: "clamp(1rem, 2.5vw, 2rem) للـfluid typography بدون media queries — تقنية رائعة." },
      { q: "ما الفرق بين :is و:where و:not و:has؟", a: ":is() pseudo-class يأخذ قائمة selectors ويورث specificity العنصر الأعلى فيها.\n:where() مثل :is() لكن specificity = 0 دائماً — مناسب للـreset والـbase styles.\n:not() يختار العناصر التي لا تطابق المحدد المعطى.\n:has() يختار الأب بناءً على ابن: div:has(img) أي div يحتوي img.", senior: ":has() = parent selector الذي انتظره المجتمع سنوات — مدعوم في جميع المتصفحات الحديثة." },
      { q: "ما pseudo-elements الرئيسية في CSS؟", a: "::before و::after يُنشئان محتوى مزيفاً قبل وبعد محتوى العنصر — يحتاجان content.\n::first-line و::first-letter يستهدفان أول سطر وأول حرف في block.\n::placeholder يُنسّق النص التوضيحي في inputs.\n::selection يُنسّق النص المُحدد من قِبل المستخدم.\n::marker يُنسّق نقاط قائمة list items.", senior: "::before و::after مع position:absolute على الأب المُحدَّد = تأثيرات بصرية قوية بدون JS." },
      { q: "ما الفرق بين position values الخمس؟", a: "static القيمة الافتراضية — العنصر في التدفق الطبيعي دون top/left تأثير.\nrelative يُحرَّك نسبة لموضعه الطبيعي مع الاحتفاظ بمساحته الأصلية.\nabsolute يُزال من التدفق الطبيعي ويُوضع نسبة لأقرب ancestor positioned.\nfixed يُوضع نسبة للـviewport ويثبت عند التمرير.\nsticky يتصرف كـrelative حتى يصل لحد scroll معين ثم يتصرف كـfixed.", senior: "sticky يحتاج overflow: visible على الـancestors — أكثر مشكلة شائعة مع sticky positioning." },
      { q: "ما z-index وكيف يعمل stacking context؟", a: "z-index يتحكم في ترتيب العناصر على محور Z (أمام/خلف).\nيعمل فقط على العناصر positioned (relative/absolute/fixed/sticky).\nstacking context ينشأ بـ: z-index غير auto على positioned، opacity < 1، transform، filter.\nداخل stacking context: العناصر تتنافس فيما بينها ويُقارن الـstacking context ككل مع غيره.", senior: "ابحث عن stacking context الأب إذا لم يعمل z-index كما تتوقع — الخطأ الأكثر شيوعاً." },
      { q: "ما الفرق بين visibility:hidden وdisplay:none وopacity:0؟", a: "display:none يُزيل العنصر من التدفق — لا يأخذ مساحة ولا يُقرأ بقارئات الشاشة.\nvisibility:hidden يُخفي العنصر لكنه يحتفظ بمساحته في التدفق.\nopacity:0 يجعل العنصر شفافاً لكنه يبقى تفاعلياً ويحتل مساحته.\nopacity:0 يمكن تحريكه smooth بخلاف display:none الذي لا يمكن تحريكه مباشرة.", senior: "لـfade animation: opacity:0 + visibility:hidden معاً، ثم تحريكهما بـtransition." },
      { q: "ما جميع خصائص transform في CSS؟", a: "translate(x,y) / translateX/Y/Z لنقل العنصر مكانياً دون التأثير على التدفق.\nscale(x,y) لتكبير/تصغير العنصر نسبةً للأصل.\nrotate(angle) لتدوير العنصر حول نقطة التحويل.\nskew(x,y) لإمالة العنصر أفقياً أو عمودياً.\nmatrix() تجمع جميع التحويلات في مصفوفة واحدة.", senior: "الـtransforms لا تُسبب reflow — الأداء أفضل من تغيير top/left/width للأنيميشن." },
      { q: "ما transform-origin وما قيمته الافتراضية؟", a: "transform-origin يحدد نقطة الأصل للتحويلات (rotate وscale وskew).\nالقيمة الافتراضية: 50% 50% أي مركز العنصر.\nيقبل قيماً متعددة: transform-origin: top left يجعل التحويل من الزاوية العلوية اليسرى.\nللـ3D transforms يمكن تحديد قيمة z أيضاً: transform-origin: 50% 50% 0.", senior: "transform-origin مهم جداً لـrotate في الأنيميشن — المركز الخاطئ يُخرب التأثير." },
      { q: "ما perspective في CSS 3D وكيف تستخدمه؟", a: "perspective تُحدد مسافة المشاهد من مستوى Z=0 مما يُعطي تأثير العمق.\nتُضاف على الـparent: perspective: 500px ثم الأبناء يحصلون على تأثير 3D.\nكلما كانت القيمة أصغر كان تأثير العمق أكبر وأكثر درامية.\nبديلاً: perspective() دالة تُضاف مباشرة في transform.", senior: "perspective على الأب يُوحّد تأثير العمق لجميع الأبناء — أكثر اتساقاً." },
      { q: "ما خصائص transitions في CSS؟", a: "transition-property تحدد الخاصية التي تُؤثر: all أو property محددة.\ntransition-duration مدة الانتقال بالثانية أو المللي ثانية.\ntransition-timing-function: ease وlinear وease-in وease-out وcubic-bezier().\ntransition-delay تأخير بدء الانتقال.\nاختصار: transition: property duration timing delay.", senior: "حرّك فقط transform وopacity للأداء الأفضل — avoid animating layout properties." },
      { q: "ما CSS animations وما خصائصها؟", a: "@keyframes تُعرّف نقاط التحرك: from/to أو نسب مئوية 0% 50% 100%.\nanimation-name اسم الـkeyframes، animation-duration المدة.\nanimation-timing-function منحنى التسريع.\nanimation-fill-mode: forwards يحتفظ بالحالة النهائية.\nanimation-iteration-count عدد التكرارات، animation-direction للاتجاه.", senior: "animation-fill-mode: both = forwards + backwards — احتفظ بالنهاية وابدأ من الـfrom." },
      { q: "ما animation-play-state وما استخداماته؟", a: "animation-play-state يتحكم في إيقاف الأنيميشن مؤقتاً أو تشغيله.\nالقيمتان: running (الافتراضية) وpaused.\nيُستخدم لإيقاف الأنيميشن عند hover أو بناءً على حالة JavaScript.\nالأنيميشن يتجمد عند موضعه الحالي ويُستأنف من نفس الموضع.\nيُستخدم مع prefers-reduced-motion لتعطيل الأنيميشن للمستخدمين الذين يفضلون ذلك.", senior: "paused مع CSS variable لإيقاف الأنيميشن بـdata-paused attribute من JS." },
      { q: "ما will-change وما مخاطر استخدامه الزائد؟", a: "will-change يُخبر المتصفح مسبقاً بالخاصية التي ستتغير لتحسين الأداء.\nيجعل المتصفح يرفع العنصر لطبقة composite منفصلة على GPU.\nالمخاطر: استهلاك زائد للذاكرة إذا طُبّق على كثير من العناصر.\nاستخدمه فقط حين تواجه مشكلة أداء حقيقية لا كـpre-optimization.\nأزله بعد انتهاء الأنيميشن: will-change: auto.", senior: "will-change سلاح ذو حدين — الإفراط فيه يُبطئ التصيير بدلاً من تسريعه." },
      { q: "ما contain وcontent-visibility في CSS؟", a: "contain يُحدد العنصر كحاوية معزولة لتحسين أداء الـrendering.\ncontain: layout يمنع تأثير عناصر الداخل على التخطيط الخارجي.\ncontain: paint يمنع رسم ما هو خارج حدود العنصر.\ncontent-visibility: auto يُسرّع التحميل بتخطي rendering العناصر خارج الـviewport.\ncontent-visibility يمكن تحقيق تسريع 5-10x في الصفحات الطويلة.", senior: "content-visibility: auto + contain-intrinsic-size = lazy rendering مجاني من المتصفح." },
      { q: "ما BEM methodology في CSS؟", a: "BEM اختصار Block Element Modifier — طريقة تسمية CSS منهجية ومنتشرة.\nBlock: مكوّن مستقل: .card أو .button.\nElement: جزء من Block: .card__title أو .card__image بفاصل __.\nModifier: حالة مختلفة: .button--primary أو .card--featured بفاصل --.", senior: "BEM يحل مشكلة التضارب بين الأسماء لكنه ثرثار — CSS Modules تحل نفس المشكلة أقل ضجيجاً." },
      { q: "ما CSS Modules وكيف تعمل؟", a: "CSS Modules تجعل أسماء الـclasses محلية ومعزولة افتراضياً لكل ملف.\nعند البناء تُحوَّل .button إلى اسم فريد كـ.button_a1b2c3__ منعاً للتعارض.\nتُستخدم في React: import styles from './Button.module.css' ثم className={styles.button}.\n:global لجعل style عالمي حين تحتاج ذلك.", senior: "CSS Modules في Next.js مدعومة افتراضياً — لا حاجة لإعداد إضافي." },
      { q: "ما CSS-in-JS وما مقارنته بـTailwind؟", a: "CSS-in-JS يكتب CSS مباشرة في JavaScript: styled-components وEmotion وستيتش.\nميزته: scoping تلقائي، props-driven styles، dynamic themes.\nعيوبه: runtime cost، bundle أكبر، مشاكل مع SSR hydration.\nTailwind utility-first: كلاسات جاهزة كـflex pt-4 text-gray-700.\nTailwind: bundle أصغر، لا runtime cost، لكن HTML verbose.", senior: "Tailwind + CSS custom properties = أفضل من CSS-in-JS في معظم مشاريع 2024-2025." },
      { q: "ما media queries وما الفرق بين min-width وmax-width؟", a: "media queries تُطبّق CSS بناءً على خصائص الجهاز أو الـviewport.\nmin-width يعني 'من هذا العرض فما أكبر' — مناسب لـmobile-first approach.\nmax-width يعني 'حتى هذا العرض' — مناسب لـdesktop-first approach.\nالتوصية: ابدأ mobile-first وأضف @media (min-width: ...) للشاشات الأكبر.", senior: "Mobile-first CSS = أقل code override، أداء أفضل على الموبايل — المعيار الصناعي." },
      { q: "ما container queries وكيف تختلف عن media queries؟", a: "container queries تستجيب لحجم الـcontainer الأب لا حجم الـviewport.\nتُعرَّف الحاوية: container-type: inline-size ثم @container (min-width: 400px).\ntُتيح components تتكيف مع سياقها: نفس الـcard يبدو مختلفاً في sidebar وفي main.\nmedia queries تستجيب للـviewport مما لا يُتيح reuse للـcomponents.", senior: "container queries = component-level responsiveness — المستقبل في مقابل viewport-based media queries." },
      { q: "ما prefers-color-scheme وprefers-reduced-motion؟", a: "prefers-color-scheme: dark يكتشف أن المستخدم يفضل الوضع المظلم.\nيُستخدم: @media (prefers-color-scheme: dark) لتطبيق dark theme تلقائياً.\nprefers-reduced-motion: reduce يكتشف أن المستخدم يفضل تقليل الحركة.\nيُستخدم: @media (prefers-reduced-motion: reduce) لتعطيل الأنيميشن.", senior: "دعم prefers-reduced-motion WCAG requirement — تجاهله يؤثر على من يعانون دوار الحركة." },
      { q: "ما CSS logical properties؟", a: "Logical properties تصف المكان بناءً على اتجاه الكتابة لا الجهة المطلقة.\nmargin-inline-start بدلاً من margin-left — يعمل صحيحاً في RTL وLTR.\nmargin-block بدلاً من margin-top و margin-bottom.\nborder-inline يُطبّق border على البداية والنهاية حسب الاتجاه.\ntext-align: start بدلاً من left — يتكيف تلقائياً مع dir.", senior: "في مشاريع RTL: الـlogical properties تُوفّر تعريف RTL styles منفصلة — توفير ضخم." },
      { q: "ما text-overflow وwhite-space وword-break وoverflow-wrap؟", a: "white-space: nowrap يمنع التفاف النص مما يُسبب overflow.\ntext-overflow: ellipsis يُضيف ... عند قطع النص — يحتاج overflow:hidden ونص في سطر واحد.\nword-break: break-all يكسر الكلمات عند أي حرف دون مراعاة الكلمات.\noverflow-wrap: break-word يكسر الكلمات فقط عند الضرورة لمنع overflow.", senior: "text-overflow: ellipsis مع -webkit-line-clamp يُقطع النص بعد عدة أسطر." },
      { q: "ما clip-path في CSS وما استخداماته؟", a: "clip-path يُقصّ شكل العنصر المرئي على شكل محدد.\nقيم: inset() للمستطيلات، circle() للدوائر، polygon() للأشكال المخصصة.\nيمكن تحريكه بـtransition وanimation للتأثيرات الإبداعية.\nلا يؤثر على مساحة العنصر في التدفق — العنصر يحتل نفس المساحة.", senior: "clip-path: polygon() يصنع أشكالاً هندسية معقدة لـhero sections بدون صور." },
      { q: "ما backdrop-filter في CSS؟", a: "backdrop-filter يُطبّق تأثيرات على ما وراء العنصر: blur وbrightness وcontrast.\nيُستخدم لتأثير الزجاج المضبب (frosted glass) الشائع في المواقع الحديثة.\nyحتاج العنصر أن يكون شفافاً جزئياً: background: rgba(0,0,0,0.5).\nيحتاج دعم المتصفح — لا يزال يحتاج -webkit- prefix في بعض الحالات.", senior: "backdrop-filter: blur(10px) مع rgba background = Glass morphism effect بسطر واحد." },
      { q: "ما object-fit وobject-position؟", a: "object-fit يتحكم في كيفية ملاء صورة أو فيديو للمساحة المحددة.\ncover يُحتفظ بنسبة الأبعاد ويملأ كامل المساحة مع قطع ما يزيد.\ncontain يُظهر الصورة بالكامل مع وجود مساحة فارغة.\nfill يمتد لملء المساحة مع تشويه نسبة الأبعاد.\nobject-position تُحدد نقطة محاذاة الصورة: top center left إلخ.", senior: "img { object-fit: cover; aspect-ratio: 16/9; } = بطاقات صور متسقة بدون JS." },
      { q: "ما aspect-ratio في CSS؟", a: "aspect-ratio يُحدد نسبة عرض العنصر لارتفاعه بشكل صريح.\naspect-ratio: 16/9 يجعل العنصر يحافظ على نسبة 16:9 عند تغيير العرض.\nيحل مشكلة padding-top hack القديمة للحفاظ على نسبة الأبعاد.\nمدعوم في جميع المتصفحات الحديثة منذ 2021.", senior: "aspect-ratio: 1 = مربع مثالي بسطر واحد — بديل أنظف لـpadding-top: 100%." },
      { q: "ما scroll-snap في CSS؟", a: "scroll-snap يُتيح تثبيت موضع التمرير عند نقاط محددة تلقائياً.\nscroll-snap-type: x mandatory على الحاوية يُفعّل snap أفقياً إلزامياً.\nscroll-snap-align: center على العناصر يُحدد نقطة التثبيت.\nيُنشئ تجربة carousel و slideshow ناعمة بدون JavaScript.\nmandatory يُجبر على snap؛ proximity يُفعّله فقط إذا كان قريباً.", senior: "scroll-snap = carousel بـCSS فقط — لكن للـaccess events لا تزال تحتاج JS." },
      { q: "ما overscroll-behavior؟", a: "overscroll-behavior يتحكم في ما يحدث حين يصل التمرير لحد الحاوية.\nالقيمة الافتراضية auto: عند الوصول للحد يُنقل التمرير للأب (scroll chaining).\ncontain يمنع نقل التمرير للأب — مفيد في modals والـdrawers.\nnone يمنع التمرير للأب ويمنع pull-to-refresh على الموبايل.", senior: "overscroll-behavior: contain على modal يمنع تمرير الـpage خلف الـmodal." },
      { q: "ما scroll-driven animations في CSS؟", a: "scroll-driven animations تُحرّك العناصر بناءً على موضع التمرير دون JavaScript.\nanimation-timeline: scroll() تربط الأنيميشن بتمرير الصفحة أو حاوية محددة.\nanimation-timeline: view() تُحرّك الأنيميشن عند ظهور العنصر في الـviewport.\nيحل محل مكتبات كـGSAP ScrollTrigger في حالات بسيطة.\nلا يزال في مرحلة دعم متفاوتة — تحقق من caniuse.", senior: "scroll-driven animations = IntersectionObserver + requestAnimationFrame بـCSS فقط." },
      { q: "ما @layer في CSS وكيف يُحسّن الـcascade؟", a: "@layer يُنشئ طبقات في الـcascade تحكم أولوية الـrules بشكل صريح.\n@layer reset, base, components, utilities تُعرّف الطبقات بالترتيب.\nالطبقة المُعرَّفة لاحقاً لها أولوية أعلى بغض النظر عن الـspecificity.\nyُتيح استخدام utilities بـspecificity منخفضة تتغلب على component styles.", senior: "@layer = الحل النهائي لمشاكل specificity wars — ابدأ باستخدامه مع Tailwind." },
      { q: "ما CSS nesting native؟", a: "CSS nesting native يسمح بتعشيش selectors داخل بعضها مثل Sass/LESS.\n.card { color: blue; & .title { font-size: 1.5rem; } } بدون preprocessor.\nالـ& يمثل الـparent selector داخل الـnesting.\nmدعوم في جميع المتصفحات الحديثة منذ 2023.\nيُلغي الحاجة لـSass في كثير من المشاريع التي تستخدمه فقط للـnesting.", senior: "CSS nesting native = Sass lite مجاني — لا يزال Sass مفيداً للـmixins والـfunctions." },
      { q: "ما font-display وما قيمه؟", a: "font-display يتحكم في كيفية عرض النص أثناء تحميل الخط.\nswap: يُظهر الخط البديل فوراً ثم يستبدله بالخط الحقيقي عند تحميله — Flash of Unstyled Text.\noptional: يُعطي وقتاً قصيراً جداً للتحميل وإلا يُكمل بالخط البديل.\nblock: يُخفي النص لفترة ثم يُظهره — Flash of Invisible Text.\nauto: يترك المتصفح يقرر.", senior: "font-display: swap مع preload للخط = تجربة تحميل خطوط متوازنة وسريعة." },
      { q: "ما variable fonts وما فوائدها؟", a: "Variable fonts ملف واحد يحتوي كل أوزان الخط وأنماطه بدلاً من ملفات منفصلة.\nيُقلّل عدد طلبات الشبكة وحجم البيانات المُحمَّلة.\nتُتيح التحكم المرن: font-weight: 350 أو أي قيمة لا ملفات خط تدعمها فقط.\nFont axes: wght للوزن، wdth للعرض، slnt للميل وغيرها.", senior: "Variable font واحد يستبدل 6-8 ملفات خط عادية — اختر variable font كلما أمكن." },
      { q: "ما CSS counters؟", a: "CSS counters تُنشئ عدادات تتزايد تلقائياً بناءً على العناصر.\ncounter-reset: my-counter 0 يُهيئ العداد على الأب.\ncounter-increment: my-counter يُزيده بواحد على كل عنصر مستهدف.\ncounter(my-counter) يستخدم قيمته في content لـ::before أو ::after.\nمفيد لتعداد الأقسام والجداول والقوائم بدون JavaScript.", senior: "CSS counters تُرقّم الأقسام تلقائياً: h2::before { content: counter(h2) '. ' }" },
      { q: "ما الفرق بين reflow وrepaint وما يُسببهما؟", a: "Reflow إعادة حساب geometry كل العناصر المتأثرة — ثقيل جداً على الأداء.\nيُسببه: تغيير width وheight وmargin وpadding وfont-size وposition.\nRepaint إعادة رسم بكسلات بدون تغيير الـlayout — أخف من reflow.\nيُسببه: تغيير color وbackground وborder-radius وbox-shadow.\ncomposite-only: transform وopacity تتجنب كليهما — الأسرع.", senior: "حرّك transform وopacity فقط للأنيميشن — هذا السر الذي يجعل 60fps ممكناً." },
      { q: "ما print styles في CSS؟", a: "@media print يُطبّق CSS خاصاً بالطباعة.\nيمكن إخفاء عناصر لا تفيد الطباعة: nav وheader وbuttons.\nيمكن تعيين عرض الصفحة وهوامشها بـ@page.\npage-break-inside: avoid يمنع تقسيم العنصر بين صفحتين.\nيمكن إظهار URLs للروابط عند الطباعة: a::after { content: ' (' attr(href) ')' }", senior: "مشاريع Dashboard وReports تحتاج print styles — من أكثر المتطلبات المنسية." },
      { q: "ما critical CSS ولماذا يهمك؟", a: "Critical CSS هو الـCSS الضروري لعرض المحتوى فوق الطية (above the fold).\nإدراجه inline في HTML يُسرّع FCP لأن المتصفح لا ينتظر تحميل CSS خارجي.\nالـCSS الخارجي blocking للـrender — أي تأخير في تحميله يُؤخّر كل الصفحة.\nأدوات مثل critical وPenthouse تستخرج الـCritical CSS تلقائياً.\nNext.js وAstro يفعلان هذا تلقائياً.", senior: "Critical CSS inline + async load for rest = FCP أسرع بدون تغيير المحتوى." },
      { q: "ما الفرق بين gap وmargin في Flex وGrid؟", a: "gap في flex/grid يُضيف مسافة بين العناصر فقط دون مسافة خارجية للحاوية.\nmargin يضيف مسافة حول العنصر بما فيها الأول والأخير مما يُسبب overflow.\ngap: 16px يساوي margin: 8px على كل جانب لكن يتجنب الجوانب الخارجية.\ngap لا يعمل في display: block — للعناصر العادية لا تزال تحتاج margin.", senior: "gap بديل أنظف لـmargin بين عناصر flex/grid — استخدمه افتراضياً." },
      { q: "ما sticky positioning وما edge cases شائعة؟", a: "sticky يتصرف كـrelative حتى يصل الـscroll لـthreshold فيصير كـfixed.\nيحتاج: top/bottom/left/right محدداً وإلا لا يعمل كـsticky.\nيعمل فقط ضمن scroll container الأب المباشر.\nيتوقف عن الـstick عند وصول حافة الأب — يظل في مكانه لا يتجاوز الأب.\nالمشكلة الأكثر: overflow:hidden على أي ancestor يُعطّل sticky.", senior: "overflow:hidden على أي ancestor = sticky لا يعمل — ابحث في devtools عن المشكل." }
    ]
  },
  {
    id: "js", label: "JavaScript", icon: "ti-brand-javascript", color: "#f7df1e",
    questions: [
      { q: "ما الفرق بين var وlet وconst من حيث الـhoisting والـTDZ؟", a: "var يُرفع لأعلى الدالة أو النطاق العالمي بقيمة undefined قبل تنفيذ أي كود.\nlet وconst يُرفعان لكنهما في Temporal Dead Zone حتى سطر التعريف — الوصول يُسبب ReferenceError.\nconst يجب تعيين قيمة له عند التعريف ولا يمكن إعادة التعيين لكن الكائن نفسه يمكن تعديله.\nlet يمكن إعادة تعيينه ويتفادى مشاكل var مع الـhoisting والـfunction scope.", senior: "TDZ يُحمي من استخدام المتغير قبل تعريفه — خطأ يُقصد به تحسين جودة الكود." },
      { q: "ما closure وما أبرز استخداماته؟", a: "Closure دالة تحتفظ بالوصول لمتغيرات النطاق الذي أُنشئت فيه حتى بعد انتهائه.\nيُستخدم لـ: إخفاء البيانات الخاصة (module pattern)، factories، memoization.\nكل دالة في JS تُنشئ closure تلقائياً بمجرد الوصول لمتغير خارج نطاقها.\nمشكلة الـloop: var في loop يُشارك نفس المتغير — استخدم let أو IIFE.", senior: "Closure = ذاكرة الدالة الخاصة — أساس Module Pattern وكثير من أنماط JavaScript." },
      { q: "ما scope chain والـlexical environment؟", a: "Scope chain السلسلة التي يتبعها JavaScript للبحث عن متغير من النطاق الحالي للخارج.\nLexical Environment بنية داخلية تحمل روابط الـrecord ورابطاً لـoutput environment الأب.\nكل استدعاء دالة يُنشئ lexical environment جديداً مرتبطاً بـenvironment الدالة.\nالبحث يتصاعد في السلسلة حتى global scope ثم يُلقي ReferenceError.", senior: "Lexical scope = النطاق يُحدَّد عند الكتابة لا عند التشغيل — أساس فهم closures." },
      { q: "كيف يعمل prototype chain؟", a: "كل كائن JS له خاصية __proto__ تشير لـprototype الكائن الأب.\nعند البحث عن خاصية تُبحث في الكائن أولاً ثم في __proto__ وهكذا حتى null.\nObject.prototype نهاية السلسلة — كل الكائنات ترثه.\nفائدته: مشاركة methods بين instances دون نسخها في كل instance.", senior: "class في ES6 هي sugar فوق prototype chain — لم يتغير الجوهر الداخلي." },
      { q: "ما الفرق بين Object.create وObject.assign وObject.freeze؟", a: "Object.create(proto) ينشئ كائناً جديداً بـprototype محدد — يُستخدم لـprototypal inheritance.\nObject.assign(target, source) ينسخ خصائص المصدر للهدف — نسخة سطحية فقط.\nObject.freeze(obj) يمنع إضافة أو تعديل أو حذف أي خاصية — immutability سطحية.\nالفرق: freeze لا يجمّد الكائنات المتشعبة — Deep freeze يحتاج تكراراً.", senior: "Object.freeze لا يُجمّد كائنات متشعبة — استخدم structuredClone ثم freeze للعمق." },
      { q: "كيف يعمل this في السياقات المختلفة؟", a: "في الدالة العادية: this يعتمد على كيفية الاستدعاء لا مكان التعريف.\nفي method: this هو الكائن الذي استُدعيت عليه.\nفي constructor: this هو الكائن الجديد المُنشأ.\nفي Arrow function: this موروث من النطاق المُعرَّف فيه — لا this خاص بها.\nstrictmode: this في دالة عادية تُستدعى مباشرة = undefined لا window.", senior: "Arrow function في event handler لا تملك this صحيح — استخدم function عادية." },
      { q: "ما الفرق بين call وapply وbind؟", a: "call(thisArg, arg1, arg2) تستدعي الدالة فوراً بـthis محدد وargs منفصلة.\napply(thisArg, [args]) تستدعي فوراً بـthis محدد وargs كـarray.\nbind(thisArg, arg1) تُعيد دالة جديدة مرتبطة بـthis محدد دون استدعاء فوري.\nاستخدام bind: إنشاء partial application أو ربط method بمكون.", senior: "bind في React كان شائعاً في constructor — arrows في class fields تحلها بشكل أنظف." },
      { q: "ما Event Loop وما ترتيب التنفيذ؟", a: "Event Loop يراقب Call Stack وCallback Queue وينقل callbacks حين Call Stack فارغ.\nCall Stack: تنفيذ synchronous code.\nMicrotask Queue: Promises و queueMicrotask — أولوية أعلى من Macrotask.\nMacrotask Queue: setTimeout وsetInterval وI/O events.\nالترتيب: Sync → Microtasks (كلها) → Macrotask واحدة → Microtasks → ...", senior: "Promise.resolve().then() = microtask تُنفَّذ قبل setTimeout(fn,0) حتى مع تأخير 0." },
      { q: "ما حالات Promise الثلاث وما الفرق بين then وcatch وfinally؟", a: "Promise لها ثلاث حالات: pending أثناء الانتظار، fulfilled عند النجاح، rejected عند الفشل.\nthen(onFulfilled, onRejected) يعالج كلا الحالتين في معالج واحد.\ncatch(onRejected) اختصار لـthen(undefined, fn) — الأوضح للأخطاء.\nfinally(fn) ينفذ دائماً بغض النظر عن النتيجة — لتنظيف الموارد.\nكل من then وcatch يُعيد Promise جديد مما يُتيح chaining.", senior: "دائماً أنهِ Promise chain بـcatch — خطأ غير معالَج يُسبب UnhandledRejection في Node." },
      { q: "ما الفرق بين Promise.all وallSettled وrace وany؟", a: "Promise.all([...]) ينجح إذا نجحت جميعها، يرفض عند أول فشل.\nPromise.allSettled([...]) ينتظر جميعها بغض النظر وينجح دائماً مع حالة كل واحدة.\nPromise.race([...]) يحل بنتيجة أول promise تنتهي سواء نجاحاً أو فشلاً.\nPromise.any([...]) ينجح بأول نجاح، يرفض فقط إذا فشلت جميعها.", senior: "allSettled للحالات التي تريد معالجة كل نتيجة بالتفصيل حتى إذا فشل بعضها." },
      { q: "كيف تعمل async/await وما علاقتها بالـPromises؟", a: "async/await هي syntax sugar فوق Promises — لا تُنشئ آلية جديدة.\nasync function تُعيد Promise تلقائياً حتى إذا أعادت قيمة عادية.\nawait يوقف تنفيذ الـasync function حتى تنتهي Promise — لكن لا يُوقف Event Loop.\nأخطاء rejected Promise تتحول لـexceptions تُعالَج بـtry/catch.", senior: "await داخل forEach لا ينتظر — استخدم for...of أو Promise.all للتوازي الصحيح." },
      { q: "ما generators وما استخداماتها؟", a: "Generator دالة تُنتج قيماً بـyield وتتوقف بين كل قيمة وتستأنف عند طلب next().\nfunction* تُعرّفها، iterator protocol: { value, done } في كل next().\ntُستخدم لـ: infinite sequences، lazy evaluation، asynchronous control flow.\nكل generator هو iterator وبعض iterators generators.", senior: "Generators حلّت محل callbacks في async/await — لكن async/await أوضح في أغلب الحالات." },
      { q: "ما WeakMap وWeakSet وWeakRef وما استخداماتهم؟", a: "WeakMap مثل Map لكن المفاتيح يجب أن تكون objects وتُمسك بـweak reference.\nإذا لم يكن هناك reference أخرى للكائن يُزال تلقائياً بـgarbge collection.\nWeakSet كـSet لكن فقط للكائنات وبـweak reference.\nWeakRef يسمح بالإشارة لكائن دون منع GC من جمعه.\nاستخدامها: caching وmetadata للكائنات دون memory leaks.", senior: "WeakMap مثالي لـprivate data: const _private = new WeakMap() — لا memory leak." },
      { q: "ما Proxy وReflect API؟", a: "Proxy يُتيح اعتراض العمليات على كائن: get وset وhas وdeleteProperty وapply.\nيُنشأ بـnew Proxy(target, handler) حيث handler يحتوي traps.\nReflect توفر نظيرات لعمليات object — تُستخدم داخل traps لـdefault behavior.\nاستخدامات: validation، logging، reactive systems مثل Vue 3.", senior: "Vue 3 reactivity system مبنية على Proxy — استيعابها يشرح كيف تعمل الـreactivity." },
      { q: "ما destructuring وما حالاته المتقدمة؟", a: "Array destructuring: const [a, b] = [1, 2] — يستخرج بالترتيب.\nObject destructuring: const { name, age } = obj — يستخرج بالاسم.\nRenaming: const { name: fullName } = obj — قيمة مع اسم مختلف.\nDefault values: const { a = 10 } = {} — قيمة احتياطية.\nNested: const { address: { city } } = user — تعشيش لأي عمق.", senior: "Function param destructuring يجعل الـAPI أوضح: function({name, age, role = 'user'} = {})." },
      { q: "ما optional chaining وnullish coalescing؟", a: "Optional chaining ?. يُوقف التقييم ويُعيد undefined إذا كان اليسار null أو undefined.\nobj?.user?.address?.city بدلاً من سلسلة طويلة من && و typeof checks.\nNullish coalescing ?? يُعيد اليمين فقط إذا كان اليسار null أو undefined تحديداً.\nيختلف عن || الذي يُعيد اليمين لأي قيمة falsy كـ0 وfalse وstring فارغ.", senior: "?? مع ?? أو || مع || واضح لكن خلطهما يُسبب خطأ syntax — اجعل الأولوية واضحة بأقواس." },
      { q: "ما الفرق بين map وfilter وreduce وforEach؟", a: "forEach ينفذ دالة على كل عنصر ولا يُعيد شيئاً — للـside effects فقط.\nmap يُحوّل كل عنصر ويُعيد array جديداً بنفس الطول.\nfilter يُعيد array جديداً بالعناصر التي أعادت الدالة true لها.\nreduce يُجمّع العناصر في قيمة واحدة بدءاً من accumulator.", senior: "reduce يمكنه محاكاة map وfilter لكن الصريح أوضح — لا تُبالغ في استخدام reduce." },
      { q: "ما الفرق بين Set وMap مقارنةً بـArray وObject؟", a: "Set مجموعة من القيم الفريدة — يمنع التكرار تلقائياً وO(1) للبحث.\nMap مثل Object لكن المفاتيح يمكن أن تكون أي قيمة حتى objects.\nObject لا يحافظ على ترتيب الإدراج للمفاتيح الرقمية ومفاتيحه strings/symbols فقط.\nArray للترتيب والوصول بالـindex؛ Set للتفرد؛ Map لقواميس مرنة المفاتيح.", senior: "new Set(arr) ثم [...set] = إزالة التكرار بسطر واحد — O(n) وأسرع من filter." },
      { q: "ما JSON.parse وJSON.stringify وما حالاتهما الحرجة؟", a: "JSON.stringify يُحوّل كائن JS لنص JSON — يتجاهل undefined والـfunctions والـSymbols.\nJSON.parse يُحوّل نص JSON لكائن JS — يُلقي SyntaxError إذا كان النص غير صالح.\nJSON لا يدعم: circular references، undefined، functions، Dates كتواريخ.\nالـDate تتحول لـstring عند stringify ولا تعود Date تلقائياً عند parse.", senior: "JSON.stringify(obj, null, 2) للـpretty print في debugging — null يحافظ على كل الخصائص." },
      { q: "ما debounce وthrottle وما الفرق بينهما؟", a: "Debounce يُؤخّر تنفيذ الدالة حتى يمر فترة صمت بعد آخر استدعاء.\nيُستخدم لـ: البحث التلقائي — ينفّذ فقط حين يتوقف المستخدم عن الكتابة.\nThrottle يُحدّد معدل أقصى لاستدعاء الدالة: مرة كل 100ms مهما كانت الاستدعاءات.\nيُستخدم لـ: scroll events وresize events التي تُطلَق كثيراً.", senior: "Debounce للمدخلات: ننتظر توقف المستخدم؛ Throttle للتمرير: ننفذ بمعدل ثابت." },
      { q: "ما deep clone وما استراتيجياته؟", a: "Spread operator والـObject.assign نسخ سطحي فقط — الكائنات المتشعبة مُشتركة.\nJSON.parse(JSON.stringify(obj)) عميق لكن يفقد functions وundefined وDates.\nstructuredClone(obj) نسخة عميقة أصلية — مدعوم في جميع المتصفحات الحديثة.\nتفقد: functions وDOM references وDates تعود كـDates صحيحة.", senior: "structuredClone الآن الخيار الأفضل للـdeep clone الأصلي — لا حاجة لـlodash.cloneDeep." },
      { q: "ما memoization وكيف تُنفّذها؟", a: "Memoization تخزين نتائج استدعاء دالة لتجنب إعادة الحساب للمدخلات نفسها.\nتنفيذ أساسي: cache Map خارج الدالة، تحقق قبل الحساب، خزّن بعده.\nفوائد: تُسرّع دوال حسابياً ثقيلة بتحويلها من O(n) لـO(1) للاستدعاءات اللاحقة.\nuseMemo في React مثال تطبيقي لـmemoization على مستوى component.", senior: "Memoize فقط الدوال النقية الثقيلة — المشاركة في closure قد تُسبب bugs خفية." },
      { q: "ما currying وpartial application؟", a: "Currying تحويل دالة بعدة arguments لدالة تأخذ argument واحداً وتُعيد دالة.\nf(a,b,c) → curry(f)(a)(b)(c) — يُتيح تطبيقاً جزئياً.\nPartial application تعيين قيمة لبعض arguments دون تطبيقها: bind أو closures.\nيُستخدم في functional composition وcreating specialized functions من عامة.", senior: "currying + compose = functional programming core — شائع في Ramda وFP libraries." },
      { q: "ما pure functions وما أهميتها؟", a: "Pure function دالة: 1) نفس المدخلات = نفس المخرجات دائماً. 2) لا side effects.\nلا تُعدّل حالة خارجية ولا تعتمد على حالة خارجية متغيرة.\nفوائد: سهلة الاختبار، memoizable، predictable، قابلة للتركيب.\nReact component يجب أن تكون pure — لهذا يستدعي StrictMode render مرتين.", senior: "Pure functions = أساس functional programming والـreact rendering model." },
      { q: "ما event bubbling وcapturing وما الفرق؟", a: "Capturing: الحدث ينزل من document للعنصر المستهدف — المرحلة الأولى.\nBubbling: بعد وصوله للهدف يصعد مرة أخرى للأعلى — المرحلة الثانية والافتراضية.\naddEventListener الثالث الـtrue يُسجّل في capturing، false أو بدون = bubbling.\nstopPropagation() يمنع صعود/نزول الحدث.\npreventDefault() يمنع السلوك الافتراضي للمتصفح.", senior: "لا تُوقف bubbling بشكل عشوائي — يُعطّل event delegation ويُسبب bugs خفية." },
      { q: "ما event delegation ولماذا هو مفيد؟", a: "Event delegation إضافة listener واحد على الأب بدلاً من listener على كل ابن.\nيعتمد على bubbling: الحدث يصعد من الابن للأب فنُعالجه هناك.\nفوائد: أداء أفضل، يعمل مع elements مضافة ديناميكياً.\nevent.target يُخبرنا بالعنصر الأصلي الذي أُطلق منه الحدث.\nevent.currentTarget العنصر الذي يملك الـlistener.", senior: "React يستخدم event delegation على document تلقائياً — لهذا الأحداث المصطنعة Synthetic." },
      { q: "ما MutationObserver وResizeObserver وIntersectionObserver؟", a: "MutationObserver يراقب تغييرات DOM: إضافة عناصر وتغيير attributes والـtext.\nResizeObserver يراقب تغييرات حجم عنصر محدد — أفضل من resize event.\nIntersectionObserver يراقب دخول/خروج عنصر من الـviewport أو حاوية محددة.\nالثلاثة أداء أفضل من polling أو scroll event listeners.\nاستخداماتها: lazy loading وanimation عند الظهور وـinfinite scroll.", senior: "IntersectionObserver = lazy loading مجاني من المتصفح — أفضل من scroll event." },
      { q: "ما الفرق بين localStorage وsessionStorage؟", a: "localStorage يحتفظ بالبيانات حتى يمسحها المستخدم أو الكود — يبقى بعد إغلاق المتصفح.\nsessionStorage يحتفظ بالبيانات فقط لمدة session (Tab) — يُمسح عند الإغلاق.\nكلاهما: sync API، 5MB تقريباً، strings فقط، origin-specific.\nJSON.stringify/parse ضروري لتخزين كائنات.\nكلاهما مُزامَن — قراءة كبيرة منهما تُعيق main thread.", senior: "لا تخزن بيانات حساسة في localStorage — قابل للقراءة من أي JS في نفس الـorigin." },
      { q: "ما IndexedDB ومتى تستخدمه؟", a: "IndexedDB قاعدة بيانات مدمجة في المتصفح لتخزين كميات كبيرة من البيانات.\nتدعم: Object stores وIndexes وTransactions وAsync API.\nاستخدمها حين تحتاج: أكثر من 5MB أو بيانات هيكلية معقدة أو offline-first apps.\nواجهتها معقدة — استخدم مكتبة مثل Dexie.js أو idb.\nالـ Service Worker يستخدمها لتخزين cached data.", senior: "IndexedDB + Service Worker = offline-first app حقيقية — المعيار في PWAs الجادة." },
      { q: "ما Fetch API مقارنةً بـXMLHttpRequest؟", a: "Fetch API حديثة، مبنية على Promises، API أنظف وأسهل قراءة.\nXHR قديمة، callback-based، لكن تدعم progress events وcancellation بشكل أسهل.\nFetch لا تُلقي خطأ لـHTTP errors (404, 500) — يجب التحقق من response.ok.\nXHR تدعم timeout مباشرة؛ Fetch تحتاج AbortController مع setTimeout.", senior: "Fetch: response.json() لا تُعيد البيانات مباشرة — تُعيد Promise يجب awaitها." },
      { q: "ما AbortController وكيف تُلغي Fetch request؟", a: "AbortController يوفر abort() method لإلغاء عمليات async.\nconst { signal } = new AbortController() ثم مرّر signal لـfetch options.\nاستدعاء controller.abort() يُلغي الطلب ويُلقي AbortError في الـcatch.\nيُستخدم في useEffect لإلغاء requests عند تدمير الـcomponent.\nيعمل مع fetch وaddEventListener وغيرها من async APIs.", senior: "AbortController في cleanup function لـuseEffect يحل race condition وmemory leak معاً." },
      { q: "ما CORS وكيف يعمل preflight request؟", a: "CORS Cross-Origin Resource Sharing آلية أمان المتصفح لطلبات Cross-origin.\nالطلبات البسيطة: GET وPOST بمحتوى عادي تُرسَل مباشرة مع Origin header.\nالطلبات المعقدة (custom headers, PUT, DELETE): تُرسَل OPTIONS preflight أولاً.\nالخادم يرد بـAccess-Control-Allow-Origin وHeaders وMethods المسموح بها.\nالخطأ CORS خطأ في الخادم لا في JS — المتصفح يُنفّذ السياسة.", senior: "CORS لا يُنفّذه الخادم — الخادم يُعلن ما يسمح به والمتصفح يُنفّذ القرار." },
      { q: "ما الفرق بين ESM وCommonJS؟", a: "ESM (ES Modules): import/export، static analysis، tree-shakable، browser-native.\nCommonJS: require/module.exports، dynamic، Node.js التقليدي.\nESM يُحلَّل statically مما يُتيح tree shaking وlazy loading.\nCommonJS يُحلَّل dynamically — يمكن require داخل if أو loop.\nNode.js يدعم كليهما — .mjs لـESM أو type: module في package.json.", senior: "ESM default في أدوات البناء الحديثة — CJS تبقى في legacy code وبعض Node packages." },
      { q: "ما dynamic imports وما استخداماتها؟", a: "import() تُعيد Promise تحمل module — تحميل ديناميكي عند الحاجة.\nimport('./Module').then(module => ...) أو await import('./Module').\nتُستخدم لـ: code splitting، lazy loading لـroutes أو components ثقيلة.\nVite وWebpack يُنشئان chunk منفصل لكل dynamic import تلقائياً.\nيمكن استخدامها مع React.lazy لتحميل components بشكل كسول.", senior: "كل dynamic import = separate chunk = تحميل أسرع للصفحة الأولى — استخدمها للـroutes." },
      { q: "ما type coercion وقواعد abstract equality؟", a: "Abstract equality == تُطبّق type coercion قبل المقارنة.\n1 == '1' → true لأن '1' تُحوَّل لـ1.\nnull == undefined → true لكن null لا يساوي أي شيء آخر.\n0 == false → true لأن false يُحوَّل لـ0.\nStrictEquality === لا تُطبّق coercion — دائماً استخدمها.", senior: "قاعدة مطلقة: استخدم === دائماً إلا إذا كنت تختبر null/undefined معاً بـ== null." },
      { q: "ما الفرق بين typeof وinstanceof؟", a: "typeof يُعيد نوع القيمة كـstring: 'number' 'string' 'boolean' 'function' 'object' 'undefined'.\nمشكلة typeof: typeof null === 'object' — خطأ تاريخي في JS.\ninstanceof يتحقق من وجود prototype في سلسلة الـprototype للكائن.\n[] instanceof Array → true؛ {} instanceof Object → true.\ninstanceof لا يعمل عبر iframes المختلفة لأن الـprototypes مختلفة.", senior: "لفحص الأنواع الدقيقة: Object.prototype.toString.call(value) يُعيد '[object Array]' إلخ." },
      { q: "ما أنواع Error في JavaScript؟", a: "SyntaxError خطأ في الكتابة يُكتشف أثناء parsing — لا يمكن مسكه بـtry/catch.\nReferenceError الوصول لمتغير غير معرّف.\nTypeError عملية غير صالحة على نوع: null.property أو calling non-function.\nRangeError قيمة خارج النطاق: new Array(-1) أو Maximum call stack exceeded.\nError.cause في ES2022 يُتيح إضافة سبب للخطأ: new Error('msg', {cause: originalError}).", senior: "catch (e) { if (e instanceof NetworkError) ... } — فرّق أنواع الأخطاء دون catch شامل." },
      { q: "ما memory leak patterns في JavaScript؟", a: "Closures تحتفظ بمتغيرات كبيرة غير مستخدمة في ذاكرتها.\nEvent listeners غير مُزالة على عناصر مُحذوفة من DOM — detached DOM.\nsetInterval وsetTimeout غير مُلغاة تُبقي references حية.\nglobal variables تراكم البيانات دون حذف.\nWeakRef وWeakMap تحل مشكلة circular references.", senior: "Chrome DevTools Memory tab + Heap Snapshot تُظهر detached DOM nodes بوضوح." },
      { q: "ما requestAnimationFrame وكيف يختلف عن setTimeout؟", a: "requestAnimationFrame (rAF) يُجدوَل callback قبل الـframe القادم للشاشة — عادة 60fps.\nمتزامن مع refresh rate الشاشة — لا تُحدد interval يدوياً.\nإذا الـTab مخفية يتوقف تلقائياً — توفير في الأداء والبطارية.\nsetTimeout(fn, 16) يُقرّب 60fps لكن غير دقيق ولا يتزامن مع frame cycle.\nrAF يضمن: لا overrendering ولا جزئية frame.", senior: "كل animation بدون rAF تخاطر بـframe drops — rAF ضمان الـ60fps الصحيح." },
      { q: "ما setTimeout(fn, 0) وماذا يعني؟", a: "setTimeout(fn, 0) لا يُشغَّل فوراً — يُضاف للـmacrotask queue وينتظر Call Stack فراغ.\nيُستخدم لإرجاء تنفيذ كود بعد تحديث DOM الحالي.\nتُستخدم كـhack لـbreak up long tasks — لكن rAF أو scheduler.yield أفضل.\nفي المتصفح الحد الأدنى الفعلي حوالي 4ms لا 0ms.\nالـPromise.resolve().then() = microtask أسرع من setTimeout(fn, 0).", senior: "setTimeout(fn, 0) لـdefer لكنه macrotask — الـPromise microtask تُنفَّذ قبله." },
      { q: "ما Symbol في JavaScript وما استخداماته؟", a: "Symbol نوع بيانات primitive يُنتج قيمة فريدة ضامنة عدم التعارض.\nSymbol('name') لا يساوي Symbol('name') — كل استدعاء قيمة جديدة.\nيُستخدم لـ: property keys خاصة لا تظهر في for...in، Well-Known Symbols.\nSymbol.iterator يُعرّف سلوك for...of على الكائنات.\nSymbol.toPrimitive يتحكم في type coercion.", senior: "Symbol.iterator = السر وراء for...of ومعرفته تُوضّح كل JavaScript iteration." },
      { q: "ما BigInt وmetى تستخدمه؟", a: "BigInt يمثل أعداداً صحيحة أكبر من Number.MAX_SAFE_INTEGER (2^53 - 1).\nيُنشأ بإضافة n: 9007199254740993n أو BigInt('9007199254740993').\nلا يمكن خلطه مع Number في العمليات مباشرة — يجب التحويل الصريح.\nيُستخدم في: cryptography وfinancial calculations وIDs من قواعد بيانات.\nلا يدعم عمليات الفاصلة العشرية.", senior: "BigInt لا يعمل مع JSON.stringify — تحتاج replacer function أو .toString()." },
      { q: "ما structuredClone وما ميزاته؟", a: "structuredClone نسخ عميق مدمج في JavaScript — متاح بدون مكتبة خارجية.\nيدعم: Dates وArrayBuffers وMaps وSets وArrays وObjects.\nلا يدعم: functions وDOM nodes وWeakMap.\nيدعم: circular references بعكس JSON.parse/stringify.\nأسرع من JSON roundtrip للـcircular references والـspecial types.", senior: "structuredClone يستبدل lodash.cloneDeep في معظم الحالات — الخيار الأول في 2024+." },
      { q: "ما Promise.withResolvers؟", a: "Promise.withResolvers() API جديدة تُعيد { promise, resolve, reject } في كائن واحد.\nتحل مشكلة الحاجة لتعريف resolve وreject خارج constructor:\nconst { promise, resolve, reject } = Promise.withResolvers()\nمفيد حين تحتاج الـresolve/reject في أماكن مختلفة من الكود.\nمتاحة في V8 117+ وNode.js 22+ وجميع المتصفحات الحديثة.", senior: "Promise.withResolvers بديل للـdeferred pattern القديم بطريقة أنظف وأكثر قابلية للقراءة." },
      { q: "ما Object.hasOwn وكيف يختلف عن hasOwnProperty؟", a: "Object.hasOwn(obj, 'key') يتحقق من ملكية الخاصية المباشرة دون الـprototype chain.\nobj.hasOwnProperty('key') تعمل أيضاً لكن يمكن تجاوزها إذا عُرّفت في الكائن.\nObject.create(null) لا يملك hasOwnProperty — Object.hasOwn يعمل معها.\nObject.hasOwn أكثر أماناً وأوضح نية وهو التوصية الحديثة.\nمتوفرة منذ ES2022 في جميع البيئات الحديثة.", senior: "Object.hasOwn بديل أمان من hasOwnProperty — ESLint prefer-object-has-own تُطبّقها." },
      { q: "ما Array.from وArray.of؟", a: "Array.from يُنشئ array من أي iterable أو array-like: Array.from('abc') → ['a','b','c'].\nيقبل mapping function كمعامل ثانٍ: Array.from({length:5}, (_, i) => i) → [0,1,2,3,4].\nArray.of ينشئ array من arguments: Array.of(3) → [3] لا [empty×3].\nفائدة Array.of: تتجنب سلوك Array(n) الغريب عند تمرير رقم واحد.", senior: "Array.from({length: n}, (_, i) => i) = range بسيط بدون مكتبة مساعدة." },
      { q: "ما logical assignment operators ؟", a: "&&= يُعيّن فقط إذا كانت القيمة اليسرى truthy: a &&= b يساوي a && (a = b).\n||= يُعيّن فقط إذا كانت القيمة اليسرى falsy: a ||= b يساوي a || (a = b).\n??= يُعيّن فقط إذا كانت القيمة اليسرى null أو undefined.\nيُقلّل الكود المتكرر ويجعل النية أوضح.\nمتوفرة منذ ES2021.", senior: "config.timeout ??= 5000 يُعيّن default بأمان دون تجاوز 0 الذي هو valid." },
      { q: "ما globalThis وما فائدته؟", a: "globalThis مرجع موحّد للـglobal object بغض النظر عن البيئة.\nفي المتصفح: globalThis === window.\nفي Node.js: globalThis === global.\nفي Web Workers: globalThis === self.\nقبله كان يجب كتابة code مختلف لكل بيئة.", senior: "globalThis مفيد في shared utilities تعمل في browser وNode وWorker بنفس الكود." },
      { q: "ما findLast وfindLastIndex في Array؟", a: "findLast(fn) يبحث من النهاية ويُعيد أول عنصر مطابق من الـend.\nfindLastIndex(fn) مثله لكن يُعيد الـindex لا العنصر.\nمتوفران منذ ES2023 في جميع البيئات الحديثة.\nقبلهما: arr.slice().reverse().find() — أبطأ وأقل وضوحاً.\nمفيد حين تعلم أن المطابق الأخير هو المطلوب مثل آخر سجل أو آخر خطأ.", senior: "findLast بديل أنظف لـreverse().find() ولا يُغيّر الـarray الأصلي." },
      { q: "ما Error.cause وكيف تستخدمه؟", a: "Error.cause يُتيح ربط سبب الخطأ بالخطأ الأصلي في سلسلة الأخطاء.\nnew Error('فشل العملية', {cause: originalError}) يُنشئ خطأ مع سبب.\nerr.cause للوصول للخطأ المُسبِّب.\nيُستخدم لإضافة سياق للأخطاء دون فقدان الـstack trace الأصلي.\nمتوفر منذ ES2022.", senior: "Error chaining بـcause يجعل debugging أوضح: ترى سبب الخطأ وموضعه الأصلي معاً." },
      { q: "ما getOwnPropertyNames مقارنةً بـObject.keys؟", a: "Object.keys يُعيد خصائص own enumerable فقط كـarray من strings.\nObject.getOwnPropertyNames يُعيد جميع الخصائص own بما فيها non-enumerable.\nfor...in يُعيد enumerable بما في ذلك الموروثة — استخدم hasOwn للتصفية.\nObject.getOwnPropertySymbols للـSymbol properties فقط.\nReflect.ownKeys يجمع strings + symbols.", senior: "Reflect.ownKeys = Object.keys + Symbols + non-enumerable — التحقق الكامل من الخصائص." },
      { q: "ما Array.prototype.flat وflatMap؟", a: "flat(depth) يُسوّي array متشعب لعمق محدد: [1,[2,[3]]].flat() → [1,2,[3]].\nflat(Infinity) يُسوّي إلى أي عمق.\nflatMap(fn) يُطبّق map ثم يُسوّي مستوى واحداً — أكفأ من map().flat().\nمفيد حين map تُنتج arrays: ['a b', 'c d'].flatMap(s => s.split(' ')) → ['a','b','c','d'].", senior: "flatMap أداء أفضل من map().flat(1) لأنها تقوم بعملية واحدة بدلاً من اثنتين." },
      { q: "ما Object.entries وObject.fromEntries وكيف تستخدمهما معاً؟", a: "Object.entries(obj) يُحوّل الكائن لـarray من [key, value] pairs.\nObject.fromEntries(entries) يُحوّل الـentries مرة أخرى لكائن.\nمعاً يُتيحان تحويل الكائن كـarray: filter وmap ثم إعادته كائناً.\nمثال: Object.fromEntries(Object.entries(obj).filter(([k,v]) => v > 0))\nيعمل مع Map أيضاً: Object.fromEntries(myMap)", senior: "entries + fromEntries = transform object كـarray — نمط قوي بدون مكتبات." },
      { q: "ما tagged template literals وما استخداماتها؟", a: "Tagged template هي دالة تعالج template literal بشكل مخصص.\nfn`Hello ${name}` تستدعي fn بـstrings array وvalues منفصلة.\nتُستخدم في: styled-components لـCSS، SQL queries آمنة، i18n، HTML escaping.\nتوفر custom DSL (Domain Specific Language) بدون syntax خاص.\nhtml`<p>${userInput}</p>` يمكن أن تُنظّف الـXSS تلقائياً.", senior: "tagged templates في styled-components تتيح كتابة CSS حقيقي مع JS variables — طاقة حقيقية." },
      { q: "ما WeakRef وما استخداماته؟", a: "WeakRef يمسك مرجعاً لكائن دون منع garbage collector من جمعه.\nconst ref = new WeakRef(target) ثم ref.deref() للوصول للكائن إذا لا يزال موجوداً.\nref.deref() يُعيد undefined إذا جُمع الكائن بـGC.\nيُستخدم مع FinalizationRegistry لتنظيف الموارد عند جمع الكائن.\nنادر الاستخدام — معظم المشاكل تُحل بـWeakMap.", senior: "WeakRef غير متوقع التوقيت — لا تعتمد على deref() في logic حرج." },
      { q: "ما Symbol.iterator وكيف تجعل كائناً iterable؟", a: "Symbol.iterator هو Well-Known Symbol يُعرّف السلوك الافتراضي لـfor...of وspread.\nالكائن يحتاج method بهذا الرمز تُعيد iterator بـnext() يُعيد {value, done}.\nمثال: class Range { [Symbol.iterator]() { ... return { next() { ... } } } }\nبعد ذلك: for (const x of range) أو [...range] يعملان.\nArrays وStrings وMaps لها Symbol.iterator مدمج.", senior: "Symbol.iterator مع generators أسهل: *[Symbol.iterator]() { for...; yield x; }" },
      { q: "ما الفرق بين falsy وnullish values؟", a: "Falsy values: false، 0، ''، null، undefined، NaN — تُقيَّم كـfalse في boolean context.\nNullish values: null وundefined فقط — تعني 'لا توجد قيمة'.\n0 وfalse وstring فارغ هي falsy لكن ليست nullish — قيم صالحة في كثير من الحالات.\n?? يتحقق من nullish فقط بعكس || الذي يتحقق من falsy.\nOptional chaining ?. يتوقف عند nullish فقط.", senior: "?? بدلاً من || يمنع الخطأ الكلاسيكي: opts.timeout ?? 5000 لا يتجاهل timeout=0." },
      { q: "ما WeakMap وكيف يختلف عن Map؟", a: "WeakMap مفاتيحه objects فقط ولا يمكن enumeration — لا size ولا forEach.\nالمفتاح مُمسَك بـweak reference: يُزال تلقائياً عند جمع الكائن بـGC.\nMap مفاتيحه أي قيمة ولها size وforEach وentries.\nWeakMap لا يمنع GC من جمع الكائن المستخدم كمفتاح.\nيُستخدم لـ: private data وmetadata مرتبطة بكائن دون memory leak.", senior: "Private class fields (#name) أفضل من WeakMap للبيانات الخاصة في الغالب." },
      { q: "ما Object.freeze وObjectسطحية vs عميقة؟", a: "Object.freeze يمنع: إضافة خصائص جديدة، تعديل الموجودة، حذف أي خاصية.\nهو سطحي: الكائنات المتشعبة قابلة للتعديل عبر references الخاصة بها.\nللتجميد العميق: دالة تكرارية تُطبّق freeze على كل كائن متشعب.\nconst تمنع إعادة تعيين المتغير لكن لا تُجمّد الكائن.\nيُستخدم في Redux لتأمين initial state.", senior: "Immer library أفضل من Object.freeze للـimmutability المعقدة — أداء أفضل وقابلية أكبر." },
      { q: "ما generator functions وprotocol الـiterator؟", a: "function* تُعرّف generator تُنتج قيماً بـyield وتتوقف حتى next().\nكل generator يتبع iterator protocol: { next(), return(), throw() } methods.\nyield* يُفوَّض لـgenerator أو iterable آخر.\nالـstate يُحفظ بين الـyields — مفيد لـsequences لا نهائية.\nالـcancellation بـgenerator.return(value) يُنهيه في أي نقطة.", senior: "Generators مع Redux-Saga = async flow control أقوى من Promises لـcomplex workflows." },
      { q: "ما tail call optimization في JavaScript؟", a: "Tail call هو استدعاء دالة كآخر عملية في دالة — نتيجته تُعاد مباشرة.\nاللغات التي تدعم TCO لا تُضيف frame جديد للـcall stack لـtail calls.\nES2015 تُحدد TCO لكن معظم المحركات لا تُطبّقها (فقط Safari).\nعملياً: recursion عميقة في JS تُسبب stack overflow حتى لو tail recursive.\nالحل العملي: trampolining أو iteration بدلاً من recursion العميقة.", senior: "لا تعتمد على TCO في JS — استخدم iteration أو trampolining للـrecursion العميقة." },
      { q: "ما Proxy مع set trap وكيف تبني reactive system؟", a: "set trap يُنفَّذ عند تعيين خاصية: handler = { set(target, prop, value) { ...notify... } }\nبعد تنفيذ المنطق: Reflect.set(target, prop, value) لحفظ القيمة فعلياً.\nيُتيح مراقبة تغييرات الكائن تلقائياً دون setters صريحة.\nVue 3 reactivity: كل reactive object مُلفَّف بـProxy يراقب التغييرات.\nيمكن مراقبة التشعب: اجعل كل خاصية object reactive بـProxy أيضاً.", senior: "Vue 3 + Proxy = reactivity بدون الـObject.defineProperty limitations في Vue 2." },
      { q: "ما Reflect API وما علاقتها بـProxy؟", a: "Reflect namespace يجمع عمليات objects كـmethods: Reflect.get وset وhas وdeletePropery.\nتستخدم نفس معاملات الـProxy traps — تسهيل الـdefault behavior.\nداخل Proxy trap: Reflect.set(target, prop, value, receiver) = default set behavior.\nReflect.apply(fn, thisArg, args) نظير Function.prototype.apply لكن كـmethod.\nتُوحّد العمليات في واجهة واحدة بدلاً من مشغلات مختلفة.", senior: "في كل Proxy trap: استدعِ Reflect نظيره للـdefault behavior ثم أضف منطقك." },
      { q: "ما rest parameters وspread operator؟", a: "Rest parameters ...args يجمع باقي arguments في array: function(a, ...rest) { }.\nyجب أن يكون آخر معامل في تعريف الدالة.\nSpread ...arr ينشر iterable في أماكن تقبل قيماً منفصلة.\nفي function call: fn(...args) مثل apply لكن أوضح.\nفي array: [...arr1, ...arr2] لدمج arrays أو clone.", senior: "Spread على Object: {...defaults, ...overrides} = merge immutable بدون Object.assign." },
      { q: "ما الفرق بين throw وthrow new Error؟", a: "throw يمكن استخدامه مع أي قيمة: throw 'string' أو throw {code: 404}.\nthrow new Error('msg') يُنشئ Error object مع stack trace كامل.\nthrow بقيم غير Error يفقد stack trace مما يُصعّب debugging.\nالمُقترح دائماً: throw new Error أو subclass من Error.\nError.cause يربط errors معاً في سلسلة واضحة.", senior: "دائماً throw new Error مع رسالة واضحة — string throw تُضيع stack trace." },
      { q: "ما Promise chaining وكيف تتعامل مع الأخطاء؟", a: "كل .then() يُعيد Promise جديد مما يُتيح chaining: fetch().then().then().catch().\nخطأ في أي then يتخطى باقي thens ويصل لأول catch.\ncatch يُعيد Promise جديد — يمكن الاستمرار بعد معالجة الخطأ.\nfinally ينفذ بغض النظر ولا يُغيّر قيمة promise الموروثة.\nإذا أعاد catch قيمة يُعامَل كـresolve — إذا throw فإنها reject.", senior: "catch في المنتصف = error recovery؛ في النهاية = error logging — كلاهما ضروريان." },
      { q: "ما iterators وما الفرق بين iterable وiterator؟", a: "Iterable كائن يملك Symbol.iterator method تُعيد iterator.\nIterator كائن يملك next() تُعيد { value, done }.\nالفرق: iterable قابل للتكرار، iterator هو حالة التكرار نفسها.\nArrays و Strings و Maps و Sets iterables.\nGenerator يُنشئ iterator مُدمج في iterable — يجمع الاثنين.", senior: "for...of يعمل مع كل iterable — Strings وArrays وMaps وكل ما يملك Symbol.iterator." },
      { q: "ما FinalizationRegistry وكيف يعمل؟", a: "FinalizationRegistry يسمح بتشغيل callback عند جمع كائن بـGC.\nconst registry = new FinalizationRegistry(value => cleanup(value))\nregistry.register(targetObj, 'cleanup-token')\nتوقيت GC غير محدد — لا تعتمد عليه لمنطق حرج.\nمفيد لتنظيف native resources خارج JS: file handles وDB connections.", senior: "FinalizationRegistry توقيتها غير متوقع — لا تستخدمها لـbusiness logic." },
      { q: "كيف يعمل garbage collection في JavaScript؟", a: "JavaScript يستخدم mark-and-sweep: يبدأ من global roots ويُعلّم كل كائن مُصاب.\nكل كائن لا يُصاب يُعدّ مُهمَلاً ويُجمع.\nالـgenerations: Young generation يُجمع بكثرة، Old generation بقل.\nV8 يستخدم Orinoco: incremental marking وconcurrent sweeping لتقليل pause times.\nمرحلة mark-and-compact تُضغط الذاكرة لمنع fragmentation.", senior: "أكبر أسباب GC overhead: نوافذ طويلة من Promises المعلقة والـevent listeners المتراكمة." },
      { q: "ما bitwise operators وما استخداماتهم؟", a: "AND (&): يُعيد 1 في كل bit مشترك — استخدام: فحص flags: (value & FLAG) !== 0.\nOR (|): يُعيد 1 إذا أحدهما 1 — استخدام: تعيين flag.\nXOR (^): يُعيد 1 إذا اختلفا — swap بدون temp: a ^= b; b ^= a; a ^= b.\nLeft shift (<<): يضرب في 2^n.\nRight shift (>>): يقسم على 2^n مع الإشارة.", senior: "bitwise flags: const R=1, W=2, X=4; permissions = R|W; check: (permissions & X) !== 0." },
      { q: "ما Atomics وSharedArrayBuffer؟", a: "SharedArrayBuffer ذاكرة مُشتركة بين Main thread وWeb Workers.\nAtomics توفر عمليات atomic آمنة على SharedArrayBuffer: load وstore وcompareExchange.\nتمنع race conditions عند الوصول المتزامن من threads مختلفة.\nتتطلب Cross-Origin Isolation headers: COOP وCOEP.\nتُستخدم في high-performance WebAssembly وgame engines في المتصفح.", senior: "Atomics + SharedArrayBuffer = multi-threading في JS — نادر لكن ضروري للـWebAssembly intensive." },
      { q: "ما الفرق بين call stack وheap في JavaScript؟", a: "Call Stack ذاكرة stack تُخزّن execution contexts بنظام LIFO.\nكل function call يُضيف frame، كل return يُزيله.\nHeap ذاكرة حرة لتخزين objects وstrings وclosures.\nStack overflow = recursion عميقة جداً لا نهاية لها أو تتجاوز حد المحرك.\nPrimitive values تُخزَّن في Stack؛ Objects تُخزَّن في Heap والـStack يحتفظ بـreference.", senior: "Stack traces في errors تعكس محتوى Call Stack لحظة الخطأ — اقرأها من أسفل لأعلى." },
      { q: "ما currying التلقائي وكيف تبنيه؟", a: "Auto-curry دالة تُحوّل أي function لـcurried version تلقائياً.\nيتحقق من عدد arguments: إذا لم تكتمل يُعيد دالة، إذا اكتملت ينفذ.\nتنفيذ: if (args.length >= fn.length) return fn(...args); return (...more) => curry(fn)(...args, ...more)\nتُستخدم في مكتبات functional: Ramda وlodash/fp.\nتُتيح partial application طبيعي دون تعقيد.", senior: "Auto-curry + compose = functional pipelines قوية وقابلة للاختبار." },
      { q: "ما queueMicrotask وكيف تختلف عن Promise?", a: "queueMicrotask(fn) تُجدوَل callback في Microtask Queue مباشرة.\nأبسط وأكفأ من Promise.resolve().then(fn) لنفس الغرض.\nكلاهما ينفذ قبل المهام (macrotasks) القادمة.\nلا تُنشئ Promise — أقل overhead في الذاكرة.\nتُستخدم في scheduler implementations وreactivity engines.", senior: "queueMicrotask في ReactDOM.flushSync alternatives وscheduler implementations." }
    ]
  },
  {
    id: "react", label: "React", icon: "ti-atom", color: "#61dafb",
    questions: [
      { q: "ما JSX وكيف يُحوَّل لكود JavaScript؟", a: "JSX امتداد syntax يُتيح كتابة HTML-like code في JavaScript.\nيُحوَّل بـBabel أو SWC لاستدعاءات React.createElement(type, props, ...children).\nReact 17+ مع الـnew JSX transform يُولّد _jsx() بدلاً من React.createElement.\nهذا يُلغي الحاجة لـimport React في كل ملف.\nالفائدة: إمكانية تحسين وتحليل الكود أثناء compilation.", senior: "الـnew JSX transform يُنتج bundle أصغر ويُسرّع rendering بتحسينات compile-time." },
      { q: "ما Virtual DOM وما دوره في الأداء؟", a: "Virtual DOM تمثيل خفيف للـDOM الفعلي في الذاكرة كـJavaScript objects.\nReact يُحدّث VDOM أولاً ثم يقارنه بالـVDOM السابق (diffing).\nيُحدّث DOM الفعلي فقط بالتغييرات الضرورية (patching) لتجنب تحديثات DOM المكلفة.\nالـDOM manipulation ثقيل — الـVDOM يُقلل من عدده ويُجمّعه.\nReact 18: Concurrent Mode يُمكّن إلغاء renders قيد التنفيذ للأولوية.", senior: "VDOM ليس السحر الأول — مُحسنات مثل Solid.js تتفوق بالـcompilation بدون VDOM." },
      { q: "ما Reconciliation وما heuristics الخوارزمية؟", a: "Reconciliation خوارزمية React لتحديد ما تغير في VDOM ومطابقته مع DOM.\nHeuristic الأول: عناصر من أنواع مختلفة تُنتج trees مختلفة — تُحذف وتُعاد.\nHeuristic الثاني: key prop تُعرّف العناصر في القوائم لتتبع تغييراتها.\nbدون key: React يفترض أن العنصر في نفس الموضع هو نفسه مما يُسبب أخطاء.\nالخوارزمية O(n) وليست O(n³) بفضل هذه الـheuristics.", senior: "key=index مشكلة: تغيير ترتيب القائمة يُسبب state corruption — استخدم ID فريد." },
      { q: "ما Fiber architecture في React؟", a: "Fiber هو إعادة كتابة كاملة لـreconciliation engine في React 16.\nكل عنصر React له Fiber node — وحدة عمل صغيرة يمكن مقاطعتها.\nيُتيح تقسيم العمل لـunits ومعالجتها بشكل incremental دون تجميد الـUI.\nيُمكّن: Suspense وConcurrent Mode وPriority-based rendering.\nWork loop: React يعمل على Fiber بين frames ويتوقف إذا كان هناك عمل أولوية.", senior: "Fiber = أساس Concurrent Mode — بدونه كان React blocking للـmain thread." },
      { q: "ما مراحل rendering في React؟", a: "Render phase: React يستدعي components ويبني Fiber tree الجديد — pure وinterruptible.\nCommit phase: React يُطبّق التغييرات على DOM الفعلي — non-interruptible.\nLayout effects (useLayoutEffect): تُشغَّل synchronously بعد DOM update قبل paint.\nPassive effects (useEffect): تُشغَّل asynchronously بعد paint.\nCleanup: يُشغَّل قبل re-running effect أو عند unmount.", senior: "Render phase يمكن تشغيله أكثر من مرة — ضع side effects في useEffect لا في render." },
      { q: "كيف يعمل useState batching في React 18؟", a: "قبل React 18: batching يعمل فقط في event handlers — كل setState في async كان re-render مستقل.\nReact 18: Automatic Batching تجمع جميع setState في أي سياق: setTimeout وPromises وasync.\nالفائدة: أقل re-renders وأداء أفضل بدون تغيير في الكود.\nflushSync من react-dom يُجبر على re-render فوري إذا احتجت.", senior: "React 18 batching يعني 3 setState في async callback = render واحد لا 3 renders." },
      { q: "ما lazy initializer في useState؟", a: "useState(initialValue) تُحسب initialValue في كل render — مشكلة للعمليات الثقيلة.\nuseState(() => heavyComputation()) تُشغَّل الدالة مرة واحدة فقط عند الـmount.\nالفرق الأساسي: القيمة مقابل الدالة — الدالة تُستدعى مرة واحدة فقط.\nمثال: useState(() => JSON.parse(localStorage.getItem('data') || '[]'))\nتُحسّن الأداء الأولي للـcomponent.", senior: "كلما رأيت قراءة localStorage أو حسابات ثقيلة في useState استخدم lazy initializer." },
      { q: "كيف تعمل dependency array في useEffect؟", a: "[] array فارغة: يُشغَّل مرة عند mount ويُنظَّف عند unmount — مثل componentDidMount.\n[dep1, dep2]: يُشغَّل عند mount وعند تغيير أي dep — مثل componentDidUpdate لقيم محددة.\nbدون array: يُشغَّل بعد كل render — نادر الاستخدام والصحيح.\nReact يقارن deps بـObject.is (shallow equality) لا deep equality.\nيجب أن تشمل كل القيم المستخدمة داخل effect — ESLint exhaustive-deps يُساعد.", senior: "dep array غير مكتملة = stale closure bug خفي — ثق بـESLint exhaustive-deps دائماً." },
      { q: "ما cleanup function في useEffect وما دورها؟", a: "Cleanup function ما تُعيده useEffect — تُشغَّل قبل re-run الـeffect أو عند unmount.\nتُستخدم لـ: إلغاء subscriptions وابort requests وclearInterval وإزالة event listeners.\nbدون cleanup: memory leaks وraces conditions عند تغيير components سريعاً.\nStrictMode يُشغّل mount → cleanup → mount للكشف عن missing cleanups.\nمثال: return () => controller.abort()", senior: "StrictMode في development يُكشف effects غير نظيفة بتشغيلها مرتين — ثق بها." },
      { q: "ما useRef وما استخداماته المختلفة؟", a: "useRef يُنشئ object { current } يبقى نفس الـreference بين renders دون تسبّب re-render.\nللوصول لـDOM: ref={myRef} ثم myRef.current.focus() — نقيض الـcontrolled approach.\nلتخزين قيمة متغيرة لا تُسبب render: timer IDs وprevious values وflags.\nيُجيب على: 'هل هذا أول render؟' بـconst isFirstRender = useRef(true).\nلا يُعيد قيمة خلال render — تُقرأ .current خارج render أو في effect.", senior: "ref لعناصر DOM ← imperative API؛ ref لقيم مُستمرة ← بديل instance variables." },
      { q: "ما useMemo ومتى تستخدمه؟", a: "useMemo يُعيد قيمة memoized تُحسب مرة ويُعاد حسابها فقط عند تغيير deps.\nيُستخدم للـ: expensive computations يجب تجنب إعادتها في كل render.\nتحذير: memoization لها cost — لا تُطبّقها دون قياس.\nReact قد يُلغي الـcache في المستقبل — لا تعتمد عليه للـside effects.\nالفرق عن useCallback: useMemo للقيم، useCallback للدوال.", senior: "useMemo لا تُصلح مشاكل re-renders الأساسية — ابحث عن سبب الـrender أولاً." },
      { q: "ما useCallback ومتى يكون ضرورياً؟", a: "useCallback يُعيد نفس reference للدالة بين renders ما لم تتغير deps.\nضروري حين: تمرر callback لـmemo component أو dependency لـuseEffect.\nبدونه: كل render يُنشئ دالة جديدة → يُكسر React.memo → re-render غير ضروري.\nله cost مثل useMemo — لا تُطبّقه على كل دالة تلقائياً.\nReact Compiler يُطبّق هذا التحسين تلقائياً في المستقبل.", senior: "useCallback بدون React.memo على consumer = optimizing للـoptimization وليس لمشكلة حقيقية." },
      { q: "ما useReducer ومتى تفضّله على useState؟", a: "useReducer(reducer, initialState) يُدير state معقدة بدالة reducer نقية.\nفضّله حين: state متعددة الحقول مترابطة، transitions معقدة، logic كثير في handlers.\nالـreducer دالة نقية: (state, action) => newState — قابلة للاختبار بمعزل.\nيُشارك نفس state logic مع actions واضحة بعكس setState المتناثر.\nuseReducer مع context يُبني state management بسيط دون مكتبة.", senior: "useState = simple؛ useReducer = complex state machine — اختر بناءً على التعقيد الفعلي." },
      { q: "كيف تعمل useContext وما مشكلة الأداء؟", a: "useContext(MyContext) يقرأ قيمة أقرب Provider في الشجرة.\nكل consumer يُعاد تصييره عند أي تغيير في قيمة الـContext — حتى لو القسم المستهلَك لم يتغير.\nمشكلة: Context كبير يُسبب re-renders واسعة غير ضرورية.\nحل: قسّم Context لأجزاء منفصلة أو استخدم Context Selectors.\nZustand وJotai يحلان هذه المشكلة بـ fine-grained subscriptions.", senior: "Context للـstatic data كـtheme وlocale؛ للـfrequent updates استخدم Zustand أو Jotai." },
      { q: "ما useTransition وuseDeferredValue؟", a: "useTransition يُعلّم updates كغير عاجلة: const [isPending, startTransition] = useTransition()\nstartTransition(() => setSearch(input)) يُؤخّر transition لصالح urgent updates.\nisPending true أثناء انتظار الـtransition — يمكن إظهار loading indicator.\nuseDeferredValue(value) يُؤجّل قيمة حتى يخف ضغط الـrendering.\nكلاهما يُعطي React حرية الـinterruption لتحديثات أعلى أولوية.", senior: "startTransition للـsearch وfiltering الثقيلة: يُبقي الـinput responsive أثناء الحساب." },
      { q: "ما useId وما مشكلة التي يحلها؟", a: "useId يُولّد ID فريد ومستقر بين server وclient rendering.\nيحل hydration mismatch: الـID يتطابق بين SSR وCSR تلقائياً.\nلا تستخدمه لـkeys في lists — useId ليس لهذا الغرض.\nيُستخدم لربط label بـinput: id={`${id}-email`} و htmlFor بنفسه.\nيدعم prefix اختيارياً منذ React 18.", senior: "useId حل أنيق لـaria-labelledby وhtmlFor في Server Components — بدون hydration mismatch." },
      { q: "ما useImperativeHandle مع forwardRef؟", a: "forwardRef يمرر ref من أب لـDOM node أو component داخلي.\nuseImperativeHandle يُحدد ما يُكشف عبر ref للـparent بدلاً من كشف كل الـDOM.\nحالة استخدام: مكتبة UI تكشف focus() و reset() فقط لا كامل الـDOM node.\nيُقلل coupling: الأب يعرف فقط الـAPI المتعمَّد كشفه.\nReact 19: ref كـprop مباشرة بدون forwardRef — أبسط بكثير.", senior: "useImperativeHandle مع forwardRef = public API للـcomponent عبر ref — استخدمه بحذر." },
      { q: "ما الفرق بين useLayoutEffect وuseEffect في التوقيت؟", a: "useLayoutEffect يُشغَّل synchronously بعد DOM mutations وقبل المتصفح يرسم الـframe.\nuseEffect يُشغَّل asynchronously بعد أن يرسم المتصفح.\nuseLayoutEffect لـ: قراءة layout وتعديل DOM قبل العرض لتجنب flash.\nuseLayoutEffect بالمحاكاة على الـServer يُسبب warnings — استخدم useEffect في SSR.\nالقاعدة: ابدأ بـuseEffect وانتقل لـuseLayoutEffect فقط إذا رأيت flicker.", senior: "useLayoutEffect = componentDidMount/DidUpdate في class components من حيث التوقيت." },
      { q: "ما useDebugValue في custom hooks؟", a: "useDebugValue يُظهر label مخصصاً في React DevTools للـcustom hook.\nuseDebugValue(value) أو useDebugValue(value, formatter) لقيمة منسقة.\nيُساعد المطورين على فهم state الـhook في DevTools بدون التعمق في الكود.\nالـformatter function يُشغَّل فقط حين DevTools مفتوحة — لا cost في production.\nمفيد في hooks مشتركة بين مطورين مختلفين في فريق.", senior: "useDebugValue في library hooks مهم — يوفر DX جيدة لمستخدمي المكتبة." },
      { q: "كيف تبني custom hook صحيح؟", a: "Custom hook دالة تبدأ بـuse وقد تستخدم hooks أخرى داخلها.\nتستخرج logic متكرر بين components وتُعيد state وactions.\nلا تُعيد JSX — هذا component لا hook.\nيجب أن يتبع قواعد hooks: لا داخل conditions أو loops.\nمثال: useFetch يُخفي fetch وloading وerror state.", senior: "Custom hook = extraction لا abstraction — استخرجه حين يُعاد نفس اللوجك 3 مرات." },
      { q: "ما React.memo وكيف يعمل shallow comparison؟", a: "React.memo يُلفَّف component لمنع re-render إذا لم تتغير props.\nيُقارن props بـshallow equality: كل قيمة بـObject.is — كافٍ للـprimitives.\nللـobjects والـarrays والـfunctions: مرجع جديد = re-render حتى لو المحتوى نفسه.\nالمقارن المخصص: React.memo(Comp, (prevProps, nextProps) => equal)\nلا يمنع re-renders إذا كان state داخلي أو context تغير.", senior: "React.memo فعال فقط مع useCallback للـfunctions وuseMemo للـobjects في الأب." },
      { q: "ما React.lazy وSuspense لـcode splitting؟", a: "React.lazy(() => import('./Component')) يُحمّل component ديناميكياً.\nيجب تغليفه بـ<Suspense fallback={<Loading/>}> لعرض حالة التحميل.\nيُنشئ chunk منفصل في Webpack/Vite تُحمَّل عند الحاجة.\nيُقلّل initial bundle size ويُحسّن Time to Interactive.\nمع React Router: كل route component يُحمَّل كسولاً تلقائياً.", senior: "كل route = dynamic import = lazy loading تلقائي؛ اجعله default في Next.js/Vite." },
      { q: "ما Error Boundaries ولماذا تحتاج class component؟", a: "Error Boundary يصطاد JS errors في subtree أثناء render وlifecycle.\nيجب أن يكون class component لأن لا hook يُعادل getDerivedStateFromError.\ndidCatch للـlogging، getDerivedStateFromError لتحديث state لإظهار fallback.\nلا يصطاد: errors في event handlers وasync code وSSR.\nمكتبة react-error-boundary تُوفر functional interface أفضل.", senior: "ضع Error Boundary حول كل route وكل section مستقل — لا تترك تطبيقاً بدونها." },
      { q: "ما Portals وما استخداماتها الرئيسية؟", a: "Portal يُدرج children في DOM node مختلف عن الأب المنطقي في React tree.\ncreatePortal(child, domNode) في ReactDOM.\nيُستخدم لـ: modals وtooltips وdropdowns التي تحتاج خروج CSS overflow.\nالـevents تبقى تتصاعد في React tree المنطقية لا DOM tree.\nيُحل مشكلة z-index وstacking context في التخطيطات المعقدة.", senior: "Portal للـmodal = DOM في body لكن React events في component — أفضل من useEffect+DOM manipulation." },
      { q: "ما StrictMode وما Double Invocation؟", a: "StrictMode wrapper يُفعّل فحوصات إضافية في development فقط.\nDouble invocation: يستدعي render وstate initializers وuseEffect مرتين للكشف عن side effects.\nيُكشف: side effects في render phase وmissing cleanups وdeprecated APIs.\nلا تأثير في production — فقط development warning.\nReact 18: double invocation يشمل cleanup → remount لكشف effects غير نظيفة.", senior: "StrictMode يُكشف bugs حقيقية — إذا ظهر خطأ في StrictMode فالكود به مشكلة حقيقية." },
      { q: "ما Concurrent Mode وما تأثيره على React؟", a: "Concurrent Mode يُتيح لـReact العمل على تحديثات متعددة بشكل متزامن دون تجميد UI.\nيُقسّم rendering لـunits صغيرة يمكن مقاطعتها وإعادة استئنافها.\nيُمكّن: Suspense وstartTransition وAutomatic Batching.\nUrgent updates (typing) تتقدم على transition updates (filtering).\nReact 18 يُفعّله بـcreateRoot() بدلاً من ReactDOM.render().", senior: "createRoot() = تفعيل Concurrent Mode — الخطوة الأولى للاستفادة من React 18+ features." },
      { q: "ما Server Components وما نموذجها الذهني؟", a: "Server Components تُشغَّل على الخادم فقط — لا JavaScript يُرسَل للـclient.\nيمكنها: قراءة قواعد البيانات مباشرة، الوصول لـfile system، استخدام secrets.\nلا تستخدم: useState وuseEffect وBrowser APIs — لا state ولا interactivity.\nتُرسل HTML جاهز للـclient مما يُقلل bundle size بشكل كبير.\nالـinteractive parts = Client Components مع 'use client' directive.", senior: "Server Components = zero bundle cost — fetch data على الخادم وأرسل HTML جاهزاً." },
      { q: "ما hydration وما مشاكله الشائعة؟", a: "Hydration: React تأخذ HTML المُعاد من الـServer وتُضيف إليه JavaScript interactivity.\nيجب أن يتطابق الـHTML المُعاد مع ما سيُنتجه React client-side.\nMismatch: يظهر في console وقد يُسبب visual glitch أو behavior غير صحيح.\nأسباب شائعة: Date() تختلف بين Server وClient، browser extensions، wrong useId.\nsuppressHydrationWarning لـ selective mismatch كالـtimestamps.", senior: "Hydration mismatch = React يُعيد render الكل client-side — ضار للأداء والـCLS." },
      { q: "ما React Query وما نموذج stale-while-revalidate؟", a: "React Query مكتبة لإدارة server state: fetching وcaching وsynchronization.\nstale-while-revalidate: يعرض البيانات المخزنة فوراً بينما يُحدّثها في الخلفية.\nيُدير تلقائياً: loading وerror وrefetching وcaching وinvalidation.\nيُلغي الحاجة لـuseEffect+fetch في معظم الحالات.\nغير مناسب لـlocal UI state — استخدمه لـserver state فقط.", senior: "React Query = server state manager؛ Zustand/Context = client state — لا تخلط بينهما." },
      { q: "متى تستخدم Context مقابل Zustand مقابل Redux؟", a: "Context: للـstatic أو نادر التغيير كـtheme وlocale وuser session.\nZustand: للـclient state البسيط والمتوسط — API بسيط ولا boilerplate.\nRedux: للـenterprise apps بتاريخ وdevtools وtime-travel debugging.\nRedux Toolkit يُقلل boilerplate Redux التقليدي.\nلا تستخدم Redux أو Zustand لـserver state — React Query أفضل لذلك.", senior: "Context لشيء واحد؛ Zustand لأكثر؛ Redux Toolkit للـenterprise — ابدأ من الأبسط." },
      { q: "ما compound components pattern؟", a: "Compound Components نمط تصميم يُشارك state ضمنياً بين components ذات صلة.\nمثل: Select.Option وTabs.Tab وAccordion.Item — تتشارك state الأب.\nيُستخدم Context أو cloneElement لمشاركة الـstate.\nيمنح المستخدم تحكماً في الهيكل بينما يُدير الأب المنطق.\nمثال: <Tabs><Tabs.List><Tabs.Tab/></Tabs.List><Tabs.Panel/></Tabs>", senior: "Compound components = API مرن يتحكم المستخدم في الهيكل ويملك المكوّن المنطق." },
      { q: "ما render props pattern وما مشاكله؟", a: "Render props يُمرر دالة كـprop تُعيد JSX — يشارك منطق مع تحكم في الـrendering.\n<DataFetcher render={data => <Component data={data}/>}/>\nمشاكله: callback hell وtextbook للـnesting العميق wrapper hell.\nCustom hooks حلّت 80% من حالات استخدام render props.\nلا تزال مفيدة في حالات: virtualized lists وanimation libraries.", senior: "Custom hooks تجعل render props غير ضرورية في أغلب الحالات الحديثة." },
      { q: "ما HOC pattern ومشكلة wrapper hell؟", a: "HOC دالة تأخذ component وتُعيد component مُحسَّناً: withAuth(Dashboard).\nتُضيف behavior مشترك: authentication وlogging وdata fetching.\nمشاكله: props collision وref loss وwrapper hell في DevTools.\nCustom hooks ومحدد استخدامها أفضل في React الحديث.\nلا تزال تُستخدم في: React Redux connect وmutation HOCs.", senior: "HOC = composition في عصر class components — hooks استبدلت معظم استخداماتها." },
      { q: "ما headless components وما ميزتهم؟", a: "Headless components تُوفر logic وstate بدون أي UI مرتبط — styling حر تماماً.\nأمثلة: Radix UI وHeadlessUI وAriaKit — كل منها يوفر accessible logic.\nيُفرق بين المنطق والعرض البصري تماماً.\nيُتيح تصميم مخصص بالكامل مع accessibility مدمج.\nCustom hooks هي نسخة أبسط من headless components.", senior: "Headless components + custom design system = DX ممتاز وأداء وإمكانية وصول بدون تضحيات." },
      { q: "ما الفرق بين controlled وuncontrolled inputs؟", a: "Controlled: قيمة input مُدارة بـstate: value={state} onChange={setState}.\nUncontrolled: قيمة input مُدارة بـDOM: تُقرأ بـref.current.value عند الحاجة.\nControlled مناسب لـ: validation فورية وقيم مترابطة وtransformation.\nUncontrolled أسرع لـ: نماذج بسيطة وfile inputs.\nReact Hook Form يستخدم uncontrolled افتراضياً لأداء أفضل.", senior: "React Hook Form يُحسّن أداء النماذج الكبيرة بتجنب re-render على كل keystroke." },
      { q: "ما أهمية key prop وما مشاكله الشائعة؟", a: "key تساعد React على تعرف العناصر في list وتتبع changes بكفاءة.\nbدون key: React يفترض أن العنصر في نفس الموضع هو نفسه مما يُسبب bugs.\nkey=index: يُسبب state corruption عند إضافة أو حذف أو إعادة ترتيب.\nkey=id فريد: يُخبر React بالعنصر بدقة بغض النظر عن الموضع.\nأزل key لإجبار إعادة mount component — تقنية reset لـstate.", senior: "key مختلفة = component جديد كلياً — أسلوب قوي لـreset state بدون منطق معقد." },
      { q: "ما synthetic events في React وكيف تختلف عن native events؟", a: "Synthetic Events غلاف فوق native events يوفر واجهة موحدة بين المتصفحات.\nReact 17+: لم تعد events مُسجَّلة في document بل في root container.\nالـSynthetic event مُعاد استخدامه (event pooling تاريخياً — أُلغي في React 17).\nيدعم نفس API: preventDefault وstopPropagation وtarget.\nيمكن الوصول للـnative event عبر event.nativeEvent.", senior: "React 17+ لا event pooling — لا تحتاج event.persist() بعد الآن." },
      { q: "ما React.Children API وما استخداماتها؟", a: "React.Children.map تُطبّق map على children مع handle لـnested arrays وnull.\nReact.Children.forEach مثلها لكن لا تُعيد array.\nReact.Children.count يُعيد عدد الأطفال الحقيقيين.\nReact.Children.only يتحقق من وجود طفل واحد فقط.\nReact.Children.toArray يُحوّل children لـarray عادي مع keys.", senior: "تجنب React.Children قدر الإمكان — استخدم array-based composition بدلاً منها." },
      { q: "ما state colocation وما مبدؤه؟", a: "State Colocation: ضع الـstate أقرب مكان يُستخدم فيه دون رفعه للأعلى بلا سبب.\nرفع state للأعلى دون ضرورة = performance overhead و tight coupling.\nإذا كان state يُستخدم في component واحد فقط — ضعه فيه لا في الأب.\nProblema: رفع state لـglobal عندما لا تحتاج سوى local sharing.\nالحل: رفع فقط ما يُشارَك ثم أعده للأسفل إذا توقف عن المشاركة.", senior: "State colocation = أقل coupling وأداء أفضل — ارفع فقط ما تحتاج مشاركته فعلاً." },
      { q: "ما derived state وما مشاكل getDerivedStateFromProps؟", a: "Derived State حسابات مُشتقة من props أو state بدلاً من تخزين قيم مكررة.\nالمشكلة: تخزين قيمة props في state يُنشئ source of truth مزدوج.\ngetDerivedStateFromProps معقد ومُربك ومصدر bugs خفية في class components.\nالبديل الحديث: احسب القيمة مباشرة في render أو useMemo.\nلا تخزن في state ما يمكن اشتقاقه من props أو state أخرى.", senior: "Derived state في render (أو useMemo) أوضح من تخزينه في useState." },
      { q: "كيف تقرأ React DevTools Profiler Flame Graph؟", a: "Flame Graph يُظهر كل component الذي rendered وكم استغرق من الوقت.\nالعرض العمودي = نطاق الـrender (كم استغرق من وقت الـframe).\nالألوان: رمادي = لم يُعاد تصييره، أصفر = slow، أخضر = fast.\nانقر على bar لتفاصيل: لماذا render الـcomponent (props/state/context تغير).\nWhy Did This Render؟ تُخبرك بالسبب الدقيق لكل re-render.", senior: "Profiler يُظهر 'Why did this render?' — هذا الزر هو أهم شيء في React optimization." },
      { q: "ما list virtualization وmeta تُستخدم فيها؟", a: "Virtualization تُصيّر فقط العناصر المرئية في الـviewport من قائمة كبيرة.\nتحل مشكلة DOM nodes كثيرة تبطئ scroll و memory consumption.\nمكتبات: react-window للبسيطة وreact-virtual لـTanStack Virtual.\nالمفهوم: تُحدد حجم scrollable container وتُصيّر فقط ما يُرى +buffer صغير.\nضرورية لـ: قوائم +100 عنصر وجداول بيانات وfeed لا نهائي.", senior: "TanStack Virtual يدعم variable-size items وdynamic loading — أفضل من react-window للتعقيد." },
      { q: "ما React 19 Actions وuseOptimistic وuse؟", a: "Actions في React 19: دوال async في form action تُدار بـuseActionState.\nuseOptimistic(state, updateFn) يُعيد قيمة optimistic تُحدَّث قبل Server response.\nuse(promise) hook يُعلق الـcomponent حتى تنتهي Promise ويتكامل مع Suspense.\nuseFormStatus يُوفر status و data لـform action في child components.\nServer Actions مع React 19 تُولّد client-server RPC بدون manual API endpoints.", senior: "React 19 Actions = form submission بدون useState/useEffect pattern — أبسط وأكثر أماناً." },
      { q: "ما useOptimistic hook في React 19؟", a: "useOptimistic يُعيد قيمة optimistic تُحدَّث فوراً قبل انتهاء الـserver action.\nconst [optimistic, addOptimistic] = useOptimistic(state, updateFn)\nعند استدعاء addOptimistic تُعرض القيمة الـoptimistic فوراً.\nعند انتهاء الـserver action: إذا نجح يُحدَّث الـstate الحقيقي وإذا فشل يعود للقديم.\nيُحسّن perceived performance بشكل كبير للـchat وlikes وcart actions.", senior: "useOptimistic = instant UI feedback + automatic rollback على فشل الـserver — مجاني تقريباً." },
      { q: "ما Suspense للـdata fetching وكيف يعمل؟", a: "Suspense في React 18+ يُعلّق rendering حتى تنتهي data fetching.\nالـdata source يجب أن يدعم Suspense: React Query أو SWC أو use() hook.\nعند suspend: React يُظهر fallback الـSuspense الأقرب في الشجرة.\nيُتيح: waterfall-free parallel data fetching وStreaming SSR.\nيُحسّن UX: عرض partial content مع Suspense boundaries متعددة.", senior: "Suspense boundaries متعددة = تحميل تدريجي بدون page-level loading spinner." },
      { q: "ما Streaming SSR مع Suspense؟", a: "Streaming SSR يُرسل HTML للـclient بشكل تدريجي بدلاً من انتظار كل الصفحة.\nReact يُولّد HTML للـstatic parts فوراً ويُرسلها.\nللـSuspense boundaries يُرسل fallback أولاً ثم HTML الحقيقي عند اكتمال data fetching.\nيُحسّن TTFB: المستخدم يرى محتوى أسرع حتى قبل اكتمال الصفحة.\nNext.js App Router يستخدم Streaming SSR افتراضياً.", senior: "Streaming SSR = TTFB أسرع + FCP أسرع + تجربة تدريجية — الاتجاه الرئيسي في Next.js." },
      { q: "ما lazy loading routes في React؟", a: "Route-level code splitting يُقسم bundle لـchunk منفصل لكل route.\nمع React Router: const Dashboard = lazy(() => import('./Dashboard'))\nمع Suspense fallback يُعرض spinner أثناء تحميل الـchunk.\nيُقلل initial bundle size بشكل كبير مما يُحسّن TTI.\nNext.js App Router يفعل هذا تلقائياً لكل segment في الـapp directory.", senior: "كل route = lazy import = تحميل فقط ما يُحتاج — مبدأ لا يُناقش في apps كبيرة." },
      { q: "ما optimistic updates pattern في React؟", a: "Optimistic Update يُحدّث UI فوراً قبل انتهاء server request.\nعند نجاح Server: تأكد من التحديث أو merge مع الـserver response.\nعند فشل Server: تراجع للحالة السابقة وأظهر error للمستخدم.\nيُحسّن perceived performance بشكل كبير للـmutations الشائعة.\nReact Query يدعمه بـonMutate وonError callbacks.", senior: "Optimistic updates تحول 500ms latency لـinstant feedback — مهم لـUX تنافسي." },
      { q: "ما context selector pattern؟", a: "Context Selector يُتيح consumer قراءة جزء محدد من Context دون re-render عند تغيير أجزاء أخرى.\nContext الافتراضي: أي تغيير في الـvalue يُعيد تصيير كل consumers.\nمكتبة use-context-selector تحل هذه المشكلة.\nZustand وJotai لديهم fine-grained subscriptions مدمج.\nنمط بديل: قسم Context لـproviders منفصلة بناءً على frequency of change.", senior: "Context Selector = performance optimization لـContext الكبير — Zustand أسهل بدلاً منه." },
      { q: "ما Jotai وما نموذجها الذهني؟", a: "Jotai state management بناءً على atoms — قطع صغيرة من state يمكن جمعها.\natom(initialValue) يُنشئ unit من state، useAtom يقرأه/يُحدّثه.\nاشتراكات fine-grained: تُعاد component فقط إذا الـatom الذي تقرأه تغير.\nيدعم: async atoms وderived atoms وatom families.\nأبسط من Recoil وأقل boilerplate من Redux.", senior: "Jotai atoms من bottom-up بعكس Context من top-down — أنسب للـmodular state." },
      { q: "ما Zustand وما نموذجه الذهني؟", a: "Zustand store بسيط بـcreate(set => ({state, actions}))\nSubscriptions fine-grained: component يقرأ فقط slice تحتاجه.\nلا Provider لازم — store global مباشرة.\nلا boilerplate: لا reducers ولا actions ولا dispatch.\nيدعم: middleware مثل immer وpersist وdevtools.", senior: "Zustand = 100 سطر تحل ما يحتاجه Redux 1000 سطر — الخيار الأول في معظم apps." },
      { q: "ما Recoil وما نموذجه الذهني؟", a: "Recoil من Facebook يستخدم atoms وselectors لـstate management.\natoms وحدات state أساسية، selectors قيم مُشتقة منها.\nكل component يشترك في atoms/selectors يحتاجها فقط.\nيدعم: async selectors وatom effects وsnapshots.\nأثقل من Jotai ولا يزال في مرحلة experimental.", senior: "Jotai ألهمته Recoil لكن أبسط منه — Recoil يُناسب مشاريع Facebook-scale." },
      { q: "ما أنواع rendering في Next.js وcaching layers؟", a: "Request Memoization: ينسق في نفس الـrender pass — إعادة استخدام لطلبات متطابقة.\nData Cache: تخزين طلبات fetch بين requests متعددة — persistent.\nFull Route Cache: HTML + RSC payload مُخزَّن في الـserver.\nRouter Cache: تخزين في client-side memory للـnavigation السريع.\nكل طبقة مختلفة في التوقيت وآلية الـinvalidation.", senior: "Next.js 15 غيّر الـdefault: fetch لم تعد cached افتراضياً — تحتاج next:{revalidate:n} صريحاً." },
      { q: "ما مبدأ composition over configuration في React؟", a: "Composition: بناء behavior معقد بتجميع components بسيطة.\nConfiguration: component واحد يقبل props كثيرة لتحديد سلوكه.\nComposition أفضل: أقل coupling، أسهل اختبار، أكثر مرونة.\nبدلاً من: <Modal type='large' footer='yes'> استخدم <Modal><Modal.Footer/></Modal>.\nReact يُفضّل composition عبر children وcomponent composition.", senior: "component تقبل children + slot props = API قابل للتوسيع دون تعديل المكوّن الأصلي." }
    ]
  },
  {
    id: "ts", label: "TypeScript", icon: "ti-brand-typescript", color: "#3178c6",
    questions: [
      { q: "ما الفرق بين any و unknown و never في TypeScript؟", a: "any: يُعطّل نظام الأنواع كلياً، يمكن تخصيصه لأي متغير وقراءته بدون فحص. unknown: نوع آمن يتطلب type narrowing قبل الاستخدام. never: يمثّل حالات مستحيلة كنهايات الدوال التي ترمي خطأ دائماً أو loops لا تنتهي. القاعدة: استخدم unknown بدل any وnever لاستيفاء exhaustive checks.", senior: "استخدم unknown عند استقبال بيانات خارجية، ونتائج never كـsafety net في switch/if-else المنهك." },
      { q: "اشرح مفهوم Type Narrowing وآلياته المختلفة.", a: "Type Narrowing هو تضييق النوع داخل block معين. الآليات: typeof (للـprimitives)، instanceof (للكلاسات)، in operator (للخصائص)، truthiness check، equality narrowing، discriminated unions، type predicates (is keyword)، assertion functions (asserts). TypeScript يتتبع control flow ليعرف النوع الدقيق في كل مسار.", senior: "Discriminated unions مع exhaustive switch هي أقوى pattern للـnarrowingـ وتضمن لك تغطية كل الحالات." },
      { q: "ما الفرق بين interface و type alias في TypeScript؟", a: "interface: تدعم الـextension بـextends ويمكن دمجها (declaration merging). type alias: أقوى في التعبير—تدعم unions، intersections، mapped types، conditional types، template literals. كلتاهما تصفان شكل الكائن. الفارق الرئيسي: interface قابلة للـmerge تلقائياً (مفيدة لتوسيع تعريفات المكتبات)، type alias لا يمكن دمجها.", senior: "استخدم interface للـpublic API والكلاسات، وtype لكل شيء آخر. تجنب الخلط العشوائي في نفس الـcodebase." },
      { q: "اشرح Generics في TypeScript مع أمثلة عملية.", a: "Generics تتيح كتابة كود مرن وآمن الأنواع في آن واحد. مثال: function identity<T>(arg: T): T. Constraints: <T extends object>. Default type params: <T = string>. Conditional generics: <T extends U ? A : B>. Utility types كلها مبنية على generics (Partial<T>, Required<T>, Pick<T,K>). الـinference يعمل تلقائياً في معظم الحالات.", senior: "ضع constraints ضيّقة على generics (extends بدل any) وسمِّ params بأسماء معبّرة (TItem, TKey) لا T فقط." },
      { q: "ما هي Utility Types الأكثر استخداماً وكيف تعمل؟", a: "Partial<T>: كل خصائص T اختيارية. Required<T>: كل خصائص T إلزامية. Readonly<T>: كل خصائص T للقراءة فقط. Pick<T,K>: يختار مجموعة خصائص. Omit<T,K>: يحذف مجموعة خصائص. Record<K,V>: ينشئ كائن من keys وvalue type. Exclude<T,U>/Extract<T,U>: لعمل set operations على unions. ReturnType<T>/Parameters<T>: لاستخراج أنواع من الدوال.", senior: "اعرف كيف تبني Utility Types بنفسك (mapped types + conditional types) لتفهمها فعلياً لا تحفظها." },
      { q: "اشرح Mapped Types وكيف تُستخدم.", a: "Mapped Types تُنشئ نوعاً جديداً بتحويل خصائص نوع موجود. الصيغة: { [K in keyof T]: NewType }. يمكن إضافة/حذف readonly وsafety modifiers بـ+/- prefix. مثال: type Mutable<T> = { -readonly [K in keyof T]: T[K] }. يمكن إعادة تسمية الـkeys بـas clause. كلا Partial وRequired وReadonly مبنية بهذه الطريقة.", senior: "Mapped Types + as clause + template literals تعطيك قوة تحويل الأنواع بشكل لا نهائي—مفيد لـsdk generation." },
      { q: "ما هي Conditional Types وكيف تعمل؟", a: "Conditional Types: T extends U ? X : Y. تعمل وقت compile كـternary على الأنواع. infer keyword تستخرج نوعاً من سياق الـextends. مثال: type ReturnType<T> = T extends (...args: any[]) => infer R ? R : never. تُوزَّع Conditional Types تلقائياً على union members (Distributive). نواعٌ كـNonNullable وExtract وExclude مبنية عليها.", senior: "infer هو أقوى أداة في TypeScript type-level programming—تعلّمها جيداً لبناء utility types معقدة." },
      { q: "اشرح Template Literal Types في TypeScript.", a: "Template Literal Types تبني أنواع string بدمج types. مثال: type EventName = `on${Capitalize<string>}`. تُستخدم لبناء APIs مرنة وآمنة النوع. تدعم Intrinsic String Manipulation Types: Uppercase, Lowercase, Capitalize, Uncapitalize. يمكن دمجها مع mapped types لتحويل أسماء الخصائص تلقائياً كـgetters وsetters.", senior: "Template literal types ثورة في type safety للـstring-based APIs—استخدمها لـevent systems وproperty accessors." },
      { q: "ما الفرق بين Declaration Merging والـModule Augmentation؟", a: "Declaration Merging: دمج تعريفات interface بنفس الاسم في نفس الـscope تلقائياً. Module Augmentation: توسيع types من مكتبة خارجية بـdeclare module. مثال لتوسيع Express Request: declare module 'express-serve-static-core' { interface Request { user?: User } }. يُستخدم في كتابة @types لمكتبات بدون types أو إضافة خصائص لكائنات مدمجة.", senior: "Module augmentation الطريقة الصحيحة لتوسيع third-party types—لا تعدّل node_modules أبداً." },
      { q: "اشرح مفهوم Discriminated Unions وفوائدها.", a: "Discriminated Unions هي union types يشتركون في خاصية literal تميزهم (discriminant). TypeScript يستخدم هذه الخاصية لـnarrowingـ تلقائياً. مثال: type Shape = { kind: 'circle'; radius: number } | { kind: 'square'; side: number }. في switch(shape.kind) TypeScript يعرف النوع الدقيق في كل case. مع never في default تحصل على exhaustive check.", senior: "الـdiscriminant يجب أن يكون literal type (string/number/boolean)—لا generic string لأنه يُفقد قوة الـnarrowing." },
      { q: "ما هو satisfies operator في TypeScript وما فائدته؟", a: "satisfies (TypeScript 4.9): يتحقق أن القيمة تطابق نوعاً معيناً دون تضييق نوعها. الفرق عن as: as يُسكت الأخطاء، satisfies يكشفها. الفرق عن : annotation: الـannotation تُوسّع النوع إلى الـdeclared type بينما satisfies يحتفظ بالـinferred type الأضيق. مثال: const config = { port: 3000 } satisfies Config—يعرف TypeScript أن port هو number لا number|string.", senior: "satisfies أفضل من as في معظم الحالات—يعطيك type safety دون فقدان الـtype inference الدقيق." },
      { q: "اشرح كيفية كتابة Type Guards المخصصة.", a: "Type Guards: دوال تُعيد predicate من النوع value is Type. مثال: function isString(x: unknown): x is string { return typeof x === 'string' }. Assertion Functions: function assertUser(x: unknown): asserts x is User { if (!isUser(x)) throw Error() }. بعد استدعائها TypeScript يضيّق النوع تلقائياً. يمكن استخدامها مع generics لبناء validators آمنة.", senior: "اجمع type guards مع runtime validation libraries كـzod لتحصل على single source of truth للنوع والـvalidation." },
      { q: "ما هي أنواع الـDecorators في TypeScript؟", a: "Decorators (تجريبية، مستقرة في TS5): Class Decorators، Method Decorators، Property Decorators، Parameter Decorators، Accessor Decorators. كل نوع يستقبل metadata مختلفة. يُستخدم في Angular، NestJS، والـDI frameworks. TS5 أعاد كتابة الـdecorators ليتوافق مع TC39 stage 3 بـAPI مختلف عن الـlegacy experimentalDecorators.", senior: "تجنب decorators في مشاريع جديدة إلا لإطار عمل يطلبها—الـmetaprogramming بـGenerics أكثر type safety." },
      { q: "اشرح الـModule Resolution في TypeScript.", a: "TypeScript يدعم strategies مختلفة: Classic (legacy)، Node (CommonJS-style)، Node16/NodeNext (ESM-aware، يتحقق من exports field في package.json)، Bundler (للـbundlers الحديثة كـVite). الـ`paths` في tsconfig.json للـaliasing. `baseUrl` لـabsolute imports. `moduleResolution: 'bundler'` الأنسب لـNext.js/Vite. الـexports field في package.json تتحكم في ما يمكن استيراده.", senior: "استخدم moduleResolution: 'bundler' مع verbatimModuleSyntax: true للـESM الحديث—يتجنب مشاكل default imports." },
      { q: "ما هو مفهوم Structural Typing في TypeScript؟", a: "TypeScript يستخدم structural typing (duck typing) لا nominal typing: الأنواع متوافقة إذا كانت لها نفس الشكل بغض النظر عن الاسم. مثال: {name: string} و type User = {name: string} متوافقان. الاستثناء: Excess Property Checking عند object literals المباشرة. الـBrand/Tag pattern يُحاكي nominal typing للـIDs والـunits.", senior: "الـBrand pattern (type UserId = string & {readonly _brand: 'UserId'}) يمنع خلط أنواع متشابهة شكلاً مختلفة دلالةً." },
      { q: "اشرح tsconfig.json وأهم خياراته.", a: "strict: يُفعّل مجموعة من الـchecks (noImplicitAny, strictNullChecks, strictFunctionTypes...). target: إصدار JavaScript الناتج. lib: المكتبات المدمجة. module/moduleResolution: نظام الوحدات. paths/baseUrl: للـaliasing. outDir/rootDir: مجلدات الإخراج والمصدر. composite/incremental: للـproject references والـbuild caching. isolatedModules: مطلوب مع esbuild/swc.", senior: "ابدأ بـstrict: true دائماً—الـmigration لاحقاً أصعب بكثير من البداية الصحيحة." },
      { q: "ما هو الفرق بين Enums والـConst Enums وبدائلها؟", a: "Enum: يُنتج JavaScript runtime code (object). Const Enum: يُحذف وقت compile ويُستبدل بالقيم مباشرة (لا يعمل مع isolatedModules). String Enums: أوضح في debugging. البديل المفضل: as const object—type-safe، لا runtime overhead، يعمل مع كل الـtools. مثال: const Direction = {Up: 'UP', Down: 'DOWN'} as const", senior: "تجنب Enums في مشاريع جديدة—استخدم as const objects مع union types المستخرجة بـtypeof و keyof." },
      { q: "اشرح مفهوم Covariance وContravariance في TypeScript.", a: "Covariance: نوع فرعي يُقبل بدل الأصلي (مثل: Array<Dog> يُسند لـArray<Animal> إذا Dog extends Animal). Contravariance: العكس—في parameters الدوال. TypeScript يطبق Strict Function Types—وظيفة تقبل Animal لا يمكن تعيينها لوظيفة تقبل Dog. Bivariance (method syntax) مسموح للـmethods بالـshorthand syntax للتوافق.", senior: "استخدم function property syntax بدل method syntax للـstrict contravariance في parameters—أكثر أماناً." },
      { q: "كيف تعمل Project References في TypeScript؟", a: "Project References تُقسّم monorepo لـtsconfig.json متعددة مترابطة. كل package لها tsconfig.json بـcomposite: true. الـreferences تُحدد الاعتماديات. tsc --build (tsc -b) يبني incrementally—يعيد بناء ما تغير فقط. declarationMap يربط .d.ts بالـsource. يُحسّن أداء الـbuild كثيراً في monorepos كبيرة.", senior: "Project references + incremental + tsBuildInfoFile تحسّن build time بـ80%+ في مشاريع كبيرة." },
      { q: "اشرح كيفية تعريف أنواع للـModule Declarations.", a: "لمكتبات بدون types: declare module 'lib-name' { ... }. في ملف .d.ts منفصل. للـglobal augmentation: declare global { interface Window { analytics: Analytics } }. Wildcard module declarations: declare module '*.svg' { const src: string; export default src }. الـsideEffects الوحيدة يمكن تعريفها بـdeclare module 'side-effects-only' {}", senior: "اكتب @types للمكتبات التي تستخدمها بدون types بدل استخدام any—يحافظ على type safety الكاملة." },
      { q: "ما هو infer في Conditional Types ومتى يُستخدم؟", a: "infer يستخرج نوعاً من سياق الـextends في conditional type. يعمل فقط داخل true branch. مثال: type Awaited<T> = T extends Promise<infer R> ? R : T. يمكن استخدامه لاستخراج: return types، parameter types، element types، this type. يمكن وضع constraints على infer: infer R extends string.", senior: "infer مع distributive conditional types قوة هائلة—استخدمه لبناء deep utility types كـDeepPartial وDeepReadonly." },
      { q: "اشرح مفهوم Excess Property Checking.", a: "عند تعيين object literal مباشرة لـtyped variable يتحقق TypeScript من الخصائص الزائدة ويرفضها. هذا لا يحدث مع التعيين غير المباشر (متغير وسيط). السبب: الخصائص الزائدة في object literal غالباً خطأ مبرمج. للتجاوز المتعمد: استخدم index signature في الـtype أو cast، أو عيّن لمتغير وسيط.", senior: "Excess property checking تحمي من أخطاء التهجئة في options objects—لا تتجاوزها بـas إلا لسبب واضح." },
      { q: "ما هو الفرق بين Type Assertion وType Casting؟", a: "في TypeScript لا يوجد type casting حقيقي وقت runtime—كل شيء يُحذف. Type Assertion (as Type أو <Type>) يُخبر المُترجم بالنوع دون تحويل فعلي. Double assertion (as unknown as T) للتحويل بين أنواع غير متوافقة. Assertion لا تُجري أي تحقق وقت runtime—مخاطرة إذا كانت البيانات الفعلية مختلفة.", senior: "استخدم Assertion فقط حين تعرف أكثر من TypeScript—فضّل type guards التي تُجري فحصاً فعلياً." },
      { q: "اشرح كيفية كتابة Declaration Files (.d.ts).", a: "Declaration files تصف أنواع JavaScript libraries. تحتوي على: declare keyword لكل تعريف (function, class, const, module). لا تحتوي على implementation. تُستخدم مع allowJs أو للـpure JS libraries. الـambient modules لملفات غير JS. تُنشأ تلقائياً بـdeclaration: true في tsconfig. يمكن publishing كـ@types/package أو ضمن package.json types field.", senior: "اكتب declaration files بدقة—types غير صحيحة أسوأ من عدم وجودها لأنها تعطي false confidence." },
      { q: "ما هو الفرق بين abstract class والـinterface؟", a: "Abstract Class: كلاس جزئي التنفيذ، يمكن أن يحتوي implementations، يُستخدم extends، لا يمكن instantiation مباشر. Interface: وصف شكل فقط، لا implementation، يُستخدم implements، يدعم declaration merging. الكلاس يمكنه implements عدة interfaces لكن extends كلاس واحد فقط. Abstract يُنتج JavaScript runtime code بينما interface لا.", senior: "فضّل interfaces + composition على abstract classes—أقل coupling وأسهل في الـtesting والـmocking." },
      { q: "اشرح Variance Annotations في TypeScript 4.7.", a: "Variance Annotations تُحدد صراحة كيف يتصرف generic type parameter. out T: covariant (return position). in T: contravariant (parameter position). in out T: invariant. بدونها TypeScript يحسبها تلقائياً لكن الحساب قد يبطئ type checking في حالات معقدة. تُحسّن أداء type checker وتوضح النية للقارئ.", senior: "Variance annotations مفيدة في libraries الكبيرة—تُسرّع type checking وتوضح الـsemantic المقصود." },
      { q: "ما هي أفضل ممارسات TypeScript في مشاريع كبيرة؟", a: "1) strict: true دائماً. 2) لا any إلا بتعليق توضيحي. 3) أنواع مشتقة بدل manual duplication. 4) Domain types بـbranding. 5) API boundaries موثّقة بـzod أو io-ts. 6) Project references للـmonorepos. 7) tsconfig منفصل للـtests. 8) Type-only imports بـimport type. 9) لا barrel files غير ضرورية. 10) CI تفحص types بشكل منفصل.", senior: "اجعل TypeScript يعمل لصالحك لا ضدك—استثمر وقتاً في إتقان type system لتكتب كوداً أقل وأقوى." },
      { q: "اشرح كيف يعمل TypeScript مع React بشكل صحيح.", a: "ComponentProps<typeof Comp> لاستخراج props نوع. React.FC لا يُنصح (يُخفي children)—استخدم function declarations. Events: React.ChangeEvent<HTMLInputElement>. Refs: useRef<HTMLDivElement>(null). Generic components: function List<T>({items}: {items: T[]}). forwardRef مع generics صعب—استخدم cast. PropsWithChildren لإضافة children.", senior: "تجنب React.FC—استخدم function declarations مع explicit return type. أضف children يدوياً بـPropsWithChildren." },
      { q: "ما هو الفرق بين strictNullChecks والـoptional chaining؟", a: "strictNullChecks: خيار compiler يجعل null وundefined أنواعاً منفصلة، يُجبرك على التعامل معها قبل الاستخدام. Optional chaining (?.): runtime operator يوقف التقييم ويُعيد undefined إذا كانت القيمة null/undefined. كلاهما مكمّل—strictNullChecks يكشف المشكلة وقت compile، ?. يتعامل معها وقت runtime. Non-null assertion (!) يُسكت strictNullChecks ومخاطر.", senior: "استخدم ?. مع استخراج default بـ?? بدل ! كلما أمكن—أكثر أماناً ومعبّراً." },
      { q: "اشرح Opaque Types وBranding في TypeScript.", a: "Branding يُنشئ nominal types فوق structural typing. الطريقة: type UserId = string & { readonly _brand: unique symbol }. لا overhead وقت runtime—الـbrand يُحذف. constructor function مع as للإنشاء. يمنع تمرير string عادي بدل UserId بالخطأ. Opaque من libraries كـnewtype-ts يُوفر abstraction أعلى.", senior: "أضف branding للـIDs والـwrapped primitives في domain models—يمنع أخطاء تمرير userId بدل orderId بثمن صفري." },
      { q: "ما هي أنواع الـtype-safe builders في TypeScript؟", a: "Builder Pattern type-safe: كل method تُعيد نوعاً مختلفاً يعكس الحالة الجديدة. Method chaining بـgenerics متراكمة. Step builders: كل خطوة تُعيد interface بالـmethods التالية المتاحة فقط. مثال: QueryBuilder<T, HasTable>—HasTable تمنع execute() قبل from(). Phantom types لتتبع الحالة وقت compile بدون overhead.", senior: "Type-safe builders تُترجم business rules لـtype constraints—الـcompiler يمنع sequences غير صالحة قبل runtime." },
      { q: "اشرح الفرق بين Extract و Exclude وReturnType.", a: "Extract<T,U>: يحتفظ بالـmembers في T التي تمتد U. Exclude<T,U>: يحذف الـmembers في T التي تمتد U. ReturnType<T>: يستخرج نوع القيمة المُعادة من دالة. كلها مبنية على Conditional Types + Distributiveness. مثال: Exclude<'a'|'b'|'c', 'a'|'b'> = 'c'. Parameters<T> تستخرج tuple نوع الـparameters.", senior: "تعلّم كيف تبني هذه الـutilities بنفسك—فهمها من الداخل يُمكنّك من كتابة utilities أكثر تخصيصاً." },
      { q: "ما هو Variadic Tuple Types في TypeScript؟", a: "Variadic Tuples (TS4+) تتيح spread في tuple types. مثال: type Concat<T extends unknown[], U extends unknown[]> = [...T, ...U]. تُستخدم في: typed function composition، currying، middleware chains. Rest elements يمكن أن تكون في أي موضع (TS4.2+). Optional elements في tuples. Labels على tuple elements للوضوح.", senior: "Variadic tuples مكّنت type-safe function composition وcurrying—أساس libraries كـfp-ts وzod." },
      { q: "اشرح كيف تعمل Index Signature في TypeScript.", a: "Index Signatures: { [key: string]: ValueType }. تتيح الوصول الديناميكي بأنواع محددة. الـstring index يشمل number index تلقائياً. يمكن دمجها مع خصائص محددة (يجب أن تكون قابلة للتعيين للـindex type). Record<string, ValueType> بديل أوضح. Readonly index signature ممكن. تُفقد exactness—استخدم Map<string,T> إذا أردت type safety أقوى.", senior: "فضّل Record<string,T> أو Map<string,T> على index signatures—أوضح نية وأسهل refactoring." },
      { q: "ما هو Template Literal Inference في TypeScript؟", a: "TypeScript يستنتج pattern من template literals: `${string}` يطابق أي string. `${number}` يطابق أي number. يمكن دمجه مع union types لإنشاء مجموعات ضخمة من string literals. مثال: type CSSUnit = `${number}${'px'|'rem'|'em'}`. يُستخدم في typed event systems: `on${Capitalize<EventName>}`. يعمل مع infer في conditional types.", senior: "Template literal inference مع mapped types يُنشئ typed APIs للـevent systems والـproperty accessors بكود قليل جداً." },
      { q: "اشرح مفهوم Type Compatibility في TypeScript.", a: "TypeScript يقارن الأنواع هيكلياً. A متوافق مع B إذا كان A يحتوي على كل خصائص B (وأكثر). الدوال: parameter types contravariant، return types covariant مع strictFunctionTypes. Classes: public interface فقط للمقارنة (private/protected تمنع التوافق إلا بالوراثة). Generics غير المُملوءة غير متوافقة.", senior: "افهم التوافق الهيكلي جيداً لتتجنب الـtype assertions المبالغ فيها—الـcompiler أذكى مما تظن." },
      { q: "ما هو Satisfies مقارنة بـType Annotation؟", a: "const x: Config = value—يُوسّع النوع إلى Config ويفقد الـinferred literal types. const x = value satisfies Config—يتحقق من التوافق مع Config لكن يحتفظ بالنوع الأضيق المُستنتج. مثال: const palette = { red: [255,0,0] } satisfies Record<string,number[]>—TypeScript يعرف أن palette.red هو [number,number,number] لا number[]. satisfies = validation بدون widening.", senior: "satisfies هو الحل الأمثل لـconfig objects—تحصل على validation والـautocompletion الدقيق في نفس الوقت." },
      { q: "اشرح كيفية التعامل مع Recursive Types.", a: "Recursive Types تصف هياكل متشعبة كـJSON والـAST. مثال: type JSONValue = string | number | boolean | null | JSONObject | JSONArray. TypeScript يدعمها بشكل محدود—يجب أن يكون هناك base case. TS4.1+ حسّن دعم الـrecursive conditional types. Deep types كـDeepPartial<T> تتطلب recursion. قد تُبطئ type checking—استخدمها بحذر.", senior: "قيّد عمق الـrecursive types بـdepth counter (type Depth = [never,0,1,2,3,4]) لتتجنب compiler hangs." },
      { q: "ما هو الفرق بين Ambient Modules وRegular Modules؟", a: "Regular Modules: ملفات TypeScript عادية بـimport/export. Ambient Modules: declare module للمكتبات الخارجية أو الملفات غير الـTS. Global Augmentation: declare global. Script files (بدون import/export): تُضاف للـglobal scope. الـambient modules في .d.ts files. Wildcard declarations للملفات غير JS كـ.svg و.css Modules.", senior: "افهم الفرق بين module scope وglobal scope في TypeScript لتتجنب أخطاء التعريف في الـglobal space." },
      { q: "اشرح كيف يعمل TypeScript مع Async/Await.", a: "async function يُعيد Promise<T>. TypeScript يستنتج T من قيمة الـreturn. await يُعيد T من Promise<T>. Promise.all<[T1,T2]> يُعيد [T1,T2] (tuple). Awaited<T> يستخرج نوع من Promise. لا حاجة لتعريف return type يدوياً—الـinference كافٍ. للـerror handling: try/catch مع unknown type (strictNullChecks).", senior: "صرّح عن return type في public APIs فقط—الـinference كافٍ داخلياً ويقلل التكرار." },
      { q: "ما هو Type-only Imports وفائدتها؟", a: "import type { Foo } from './foo': يستورد النوع فقط، يُحذف كلياً وقت runtime. يمنع circular dependencies وقت runtime مع type-only relations. مطلوب مع isolatedModules (esbuild/swc). verbatimModuleSyntax (TS5.0): يُجبر على import type للأنواع ويمنع الغموض. يُوضح للقارئ أن هذا الاستخدام للنوع فقط.", senior: "فعّل verbatimModuleSyntax في مشاريع جديدة—يُوضح الـimports ويُحسن treeshaking." },
      { q: "اشرح كيفية كتابة Generic Constraints المتقدمة.", a: "T extends keyof U: T يجب أن يكون مفتاحاً في U. T extends U[keyof U]: T يجب أن يكون قيمة في U. T extends Record<string, unknown>: T يجب أن يكون object. T extends (...args: any[]) => any: T يجب أن يكون function. Multiple constraints بـintersection: T extends A & B. Conditional constraints بـconditional types في extends clause.", senior: "ضع constraints بدقة—ضيّقة بما يكفي لإعطاء inference مفيد، لكن ليس أضيق مما يتطلب use case الفعلي." },
      { q: "ما هو NoInfer في TypeScript 5.4؟", a: "NoInfer<T>: utility type جديدة تمنع TypeScript من استخدام موضع معين في الـinference. مفيد حين تريد inference من موضع واحد فقط. مثال: function createState<T>(initial: T, fallback: NoInfer<T>): T—inference يأتي من initial فقط، fallback يجب أن يطابق بدون أن يؤثر على الـinference. حل لمشاكل inference الغامضة.", senior: "NoInfer أنيق لـAPIs التي تريد inference من argument محدد فقط—بديل أنظف من overloads معقدة." },
      { q: "اشرح Type-safe Event Emitter بالكامل.", a: "بناء typed event emitter: EventMap = Record<string, unknown>. class TypedEmitter<T extends EventMap>. on<K extends keyof T>(event: K, listener: (data: T[K]) => void). emit<K extends keyof T>(event: K, data: T[K]). تعريف الـevents: type AppEvents = { 'user:login': {userId: string}; 'error': Error }. new TypedEmitter<AppEvents>()—كل emit وon مكتوبان بشكل آمن.", senior: "Typed event emitters مثال ممتاز على قوة generics + mapped types في بناء APIs آمنة." },
      { q: "ما هي أداء TypeScript Type Checker وكيف تُحسّنه؟", a: "أدوات القياس: tsc --diagnostics، --extendedDiagnostics، --generateTrace. أسباب البطء: أنواع متشعبة، conditional types، union كبيرة، barrel imports. الحلول: Project references، incremental builds، تقليل الـunion sizes، تجنب mapped types العميقة. skipLibCheck: true يُسرّع لكن يُخفي مشاكل. TypeScript Language Server يمكن تشخيصه بـtrace.", senior: "قس أولاً (generateTrace + perfetto.dev) ثم حسّن—غالباً البطء في barrel imports أو union types ضخمة." },
      { q: "اشرح Assertion Functions في TypeScript.", a: "Assertion Functions: function assert(condition: boolean): asserts condition { if (!condition) throw Error() }. بعد الاستدعاء TypeScript يعرف أن condition = true. Typed: function assertUser(x: unknown): asserts x is User. يختلف عن type predicates—يرمي خطأ بدل إعادة boolean. مفيد للـprecondition checks والـvalidation في entry points.", senior: "استخدم assertion functions في boundaries الخارجية (API responses, user input) لـvalidation مع type narrowing." },
      { q: "ما هو الفرق بين Intersection Types وExtension؟", a: "Intersection (A & B): دمج نوعين في نوع واحد. لو كان لهما خصائص بنفس الاسم وأنواع مختلفة—النتيجة never. Extension (interface B extends A): B يرث A مع إمكانية override. Intersection أكثر مرونة ولكن يمكن أن تُنتج never للـconflicting properties. Intersection مع functions: overloaded signatures. الـextension أنظف للـhierarchies.", senior: "استخدم Intersection للـmixins والـcomposition، والـextension للـhierarchies الواضحة—لا تخلط الاثنين بشكل عشوائي." },
      { q: "اشرح Recursive Conditional Types في TypeScript.", a: "TS4.1+ يدعم recursive conditional types مباشرة. مثال: type DeepReadonly<T> = T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T. مثال: type Flatten<T> = T extends Array<infer I> ? Flatten<I> : T. يتوقف TypeScript عند عمق معين لمنع infinite recursion. مفيد لـJSON types والـAST manipulation.", senior: "اختبر recursive types مع حالات حافة (empty object, circular references) مبكراً—قد تُنتج unexpected never." },
      { q: "ما هو Declaration Merging وكيف تعمل؟", a: "Declaration Merging: دمج تعريفات interfaces بنفس الاسم تلقائياً. تعمل مع: interfaces، namespaces، enums. لا تعمل مع type aliases وclasses. مفيد لـaugmentation الـthird-party types. Namespace merging مع classes/functions لإضافة static members. ترتيب الدمج يؤثر على الـoverload resolution.", senior: "استخدم module augmentation لتوسيع أنواع المكتبات—نمط نظيف بدل copy-paste أو ts-ignore." },
      { q: "اشرح Type Narrowing بـin operator.", a: "'property' in object: يتحقق من وجود خاصية وقت runtime ويُضيّق النوع. مفيد مع discriminated unions التي لا تشارك discriminant واحداً. TypeScript يُضيّق لـtype الذي له تلك الخاصية. مثال: if ('swim' in animal) { animal is Fish }. يعمل مع أي object type، لكن in يتحقق من prototype chain أيضاً.", senior: "فضّل discriminated union بـkind/type field على in narrowing—أوضح نية وأسهل exhaustive checking." },
      { q: "ما هو Triple-slash Directives في TypeScript؟", a: "Triple-slash: تعليقات XML في أعلى الملف. /// <reference types='node' />: يضيف @types/node للـglobal scope. /// <reference path='...' />: يضيف ملف .d.ts. /// <reference lib='...' />: يضيف مكتبة مدمجة. /// <amd-module name='...' />: للـAMD. مُستخدمة في .d.ts files بشكل رئيسي. في المشاريع الحديثة يُفضّل tsconfig.json بدلها.", senior: "Triple-slash references legacy feature—في مشاريع حديثة أضف types في tsconfig.json compilerOptions.types." },
      { q: "اشرح كيفية بناء Type-safe API Client.", a: "type-safe API client يستخدم generic types للـrequests والـresponses. type ApiRoutes = { 'GET /users': { response: User[] }; 'POST /users': { body: CreateUser; response: User } }. function client<P extends keyof ApiRoutes>(path: P, options?: ApiRoutes[P] extends { body: infer B } ? { body: B } : {}): Promise<ApiRoutes[P]['response']>. Zod للـruntime validation. مع الـbody type مُشتقاً من الـroute definition.", senior: "اجمع tRPC أو api-contract-builder patterns مع zod—single source of truth للـAPI types والـvalidation." },
      { q: "ما هو الفرق بين مشاريع TypeScript ESM وCJS؟", a: "CJS (commonjs): require/module.exports، .js extension اختيارية، يعمل مع Node.js بدون config. ESM: import/export، extensons إلزامية في Node.js، يتطلب type: 'module' في package.json أو .mjs. TypeScript مع ESM: module: 'NodeNext', moduleResolution: 'NodeNext'، import بـ.js extension (حتى لـ.ts files). مشاكل CJS/ESM interop شائعة.", senior: "اختر ESM للـpure libraries الجديدة. للـNode.js apps: CJS أبسط حتى ينضج النظام البيئي للـESM." },
      { q: "اشرح مفهوم TypeScript Language Server Protocol.", a: "Language Server Protocol (LSP): بروتوكول قياسي للـeditor features. TypeScript Language Server (tsserver): يوفر completions، diagnostics، refactoring، go-to-definition، find-references، rename symbol. يعمل مع VS Code وكل editors تدعم LSP. tsconfig.json يؤثر بشكل مباشر على جودة الـLS features. Plugin API لتوسيع الـLS.", senior: "optimize tsconfig لتحسين تجربة الـLS—strict settings تُحسّن الـcompletions وتقلل الـfalse positives." },
      { q: "ما هو تأثير TypeScript على Bundle Size؟", a: "TypeScript لا يُضيف شيئاً لـbundle size—كل types تُحذف وقت compile. لكن: Class fields يمكن أن يختلف تحويلها (useDefineForClassFields). Decorators تُضيف helper code. Enum يُضاف كـobject (بخلاف const enum). Declaration files (.d.ts) لا تُضاف للـbundle. Enums استخدم as const بدلاً لتجنب الـbundle overhead.", senior: "راجع output JS من TypeScript للأجزاء الحساسة—أحياناً TypeScript helpers تُضاف بشكل غير متوقع." },
      { q: "اشرح Covariant و Contravariant Positions.", a: "Covariant positions (safe to widen): return type، read-only properties. Contravariant positions (safe to narrow): parameter types، write-only properties. Bivariant: method shorthand syntax (أقل أماناً). strict function types تُفعّل contravariance للـparameter types. Property positions: readonly—covariant، writable—invariant. فهم هذا يُوضّح لماذا بعض التعيينات مسموحة وبعضها لا.", senior: "تعلّم variance لتفهم أخطاء TypeScript الغريبة في callbacks وevent handlers—أكثر أخطاء type compatibility شائعة." },
      { q: "ما هو الفرق بين unknown[] و Array<unknown>؟", a: "unknown[] وArray<unknown> متطابقان تماماً في TypeScript—مجرد اختلاف في الـsyntax. readonly unknown[] وReadonlyArray<unknown> متطابقان. [unknown, unknown] هو tuple بعنصرين. Array<T> generic—يمكن استخدامه في generic contexts. الفرق الحقيقي: tuple vs array, readonly vs mutable. اختر النمط الذي يناسب الـcodebase conventions.", senior: "استخدم readonly arrays/tuples حيث أمكن—تُمنع الـmutation الغير مقصودة وتُوضح النية." },
      { q: "اشرح Pattern Matching بشكل نوعي في TypeScript.", a: "TypeScript لا يدعم pattern matching (switch expressions) مباشرة. البدائل: discriminated unions + switch، match libraries كـts-pattern، exhaustive switch مع never check. ts-pattern example: match(shape).with({kind: 'circle'}, s => s.radius).with({kind: 'square'}, s => s.side).exhaustive(). يُقدّم TC39 proposal لـpattern matching للـJavaScript.", senior: "ts-pattern مكتبة رائعة لـpattern matching type-safe—استخدمها بدل switch chains للـdiscriminated unions المعقدة." },
      { q: "ما هو Type-level Programming في TypeScript؟", a: "TypeScript type system Turing-complete—يمكن حل مسائل وقت compile. مشاريع كـhot-chocolate وtype-challenges تُثبت ذلك. يمكن: حساب طول tuple، إنشاء range types، تحقق من palindrome. هذا أكاديمي غالباً—في الواقع: validation، transformation، API type generation. type-challenges.github.io للتعلم والتمرين.", senior: "Type-level programming أداة قوية للـlibrary authors—لكن في application code فضّل البساطة على الـclever types." },
      { q: "اشرح كيفية migrate كود JavaScript لـTypeScript.", a: "خطوات آمنة: 1) أضف tsconfig.json بـallowJs: true. 2) غيّر ملفاً واحداً في وقت—الأهم أولاً. 3) أضف JSDoc types للملفات JS المتبقية. 4) فعّل strict تدريجياً. 5) استخدم // @ts-check في JS files. 6) أدوات: ts-migrate، jscodeshift. تجنب any—prefer unknown. اختبر بعد كل ملف. أبقِ CI يمر طوال الـmigration.", senior: "لا تُهاجر كل الـcodebase مرة واحدة—ابدأ بالـcritical paths وارفع الـstrict coverage تدريجياً." },
      { q: "ما هو الفرق بين readonly وconst في TypeScript؟", a: "const: يمنع إعادة التعيين للمتغير نفسه (compile + runtime). readonly: يمنع التعديل على property في كلاس أو interface (compile only). const object ليس immutable—خصائصه قابلة للتعديل. readonly property في object لا تمنع التعيين للـobject نفسه. as const: يُجعل كل values literal types وكل properties readonly recursively.", senior: "as const للـconfiguration constants وenums—يعطيك literal types تلقائياً ويمنع الـmutation." },
      { q: "اشرح كيف تعمل Overloads في TypeScript.", a: "Function Overloads: تعريفات متعددة بـsignatures مختلفة ثم implementation signature. TypeScript يختار الـsignature المناسب بناءً على الـarguments. implementation signature أوسع من كل overloads وغير مرئية للـcallers. Method overloads في classes مشابهة. تُفيد لـpolymorphic functions. بديل: union types في parameters مع narrowing.", senior: "استخدم overloads للـpublic APIs فقط حين union parameters تُعقّد الـreturn type inference." },
      { q: "ما هي أنواع الـES2023+ الجديدة في TypeScript؟", a: "TypeScript يضيف أنواع للـES2023+: Array.toSorted, toReversed, toSpliced, with (immutable array methods). Set.union, intersection, difference, symmetricDifference (ES2025). Object.groupBy, Map.groupBy. Promise.withResolvers. Error.cause. RegExp v flag. تتوفر بتحديد lib أو target المناسب في tsconfig. TypeScript يتتبع TC39 proposals في مراحل متقدمة.", senior: "استخدم lib: ['ES2023', 'DOM'] بدل target لـlib selection—يُعطيك أحدث types بغض النظر عن transpilation target." },
      { q: "اشرح Path Aliasing في TypeScript وأفضل ممارساته.", a: "paths في tsconfig.json: {'@/*': ['./src/*']}. baseUrl مطلوب مع paths. يتطلب إعداد مقابل في bundler (Vite، Webpack alias). Next.js يدعمه تلقائياً من tsconfig. لا يعمل مع tsc alone—الـbundler يتولى التحويل الفعلي. tsconfig-paths لـNode.js بدون bundler. اتفق على conventions للـaliases (@, ~, #)", senior: "اجعل aliases قليلة ومتسقة—@/components، @/utils، @/types. aliases كثيرة تُصعّب refactoring." },
      { q: "ما هي قواعد ESLint المهمة لـTypeScript؟", a: "@typescript-eslint/plugin: no-explicit-any، no-unused-vars، no-floating-promises، await-thenable، no-misused-promises، consistent-type-imports، naming-convention. @typescript-eslint/recommended-type-checked: يتطلب parserOptions.project—أبطأ لكن أقوى. no-unsafe-*: تتجنب any leak. no-redundant-type-constituents: تنظيف unions.", senior: "فعّل TypeChecked rules في CI—قد تبطئ local dev لكن تكشف مشاكل حقيقية لا يراها compiler وحده." },
      { q: "اشرح مفهوم Ambient Declarations في TypeScript.", a: "Ambient Declarations تصف كيانات موجودة في runtime دون كود TypeScript. declare var، declare function، declare class، declare module، declare namespace. تُستخدم في .d.ts files. declare global { } للخصائص الـglobal. تُخبر compiler بوجود هذه القيم دون implementation. شائعة في @types packages.", senior: "اكتب ambient declarations بدل any لـglobal variables وبيئات خاصة (browser extensions، Electron، Worker global)." },
      { q: "ما هو مفهوم Type Widening في TypeScript؟", a: "Type Widening: TypeScript يُوسّع الـliteral types تلقائياً في بعض السياقات. مثال: let x = 'hello'—x هو string لا 'hello'. لكن const x = 'hello'—x هو 'hello'. Object properties مع let تُوسّع. as const يمنع الـwidening. Contextual typing يمنعه أيضاً. Widening يحدث عند تمرير القيمة خارج نطاقها.", senior: "افهم متى يحدث widening لتستخدم as const في المكان الصحيح وتحصل على literal types المطلوبة." },
      { q: "اشرح كيف تعمل Generic Default Types.", a: "Default Type Parameters: <T = DefaultType>. إذا لم يُمرّر T يُستخدم DefaultType. يمكن أن يعتمد على params سابقة: <T, U = T>. مفيد للـoptional generic parameters. الـinference يتجاوز الـdefault—إذا أمكن TypeScript استنتاج T يستخدمه. لا يعمل الـdefault إلا عند عدم وجود inference.", senior: "Generic defaults تُبسّط API—type EventEmitter<T = Record<string, unknown>> تعمل بدون تمرير T وتبقى type-safe." },
      { q: "ما هو Structural vs Nominal Typing في السياق العملي؟", a: "Structural: TypeScript—{name: string} متوافق مع type User = {name: string} حتى لو كانا منفصلين. Nominal: Java/C#—نوعان مختلفان حتى لو كان لهما نفس الشكل. في TypeScript: UserId وOrderId (كلاهما string) متوافقان بدون branding. الـbranding pattern يُحاكي nominal typing. مفيد لـdomain modeling وmoney types.", senior: "structural typing مرن لكن يحتاج branding للـdomain-critical values—UserId لا يجب أن يُقبل حيث OrderId مطلوب." },
      { q: "اشرح Mapped Types مع as Clause.", a: "as clause في mapped types لإعادة تسمية الـkeys: { [K in keyof T as Rename<K>]: T[K] }. يمكن استخدام template literals: { [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K] }. يمكن فلترة الـkeys بإعادة never: { [K in keyof T as T[K] extends string ? K : never]: T[K] }. قوة هائلة لتحويل الـAPI shapes.", senior: "mapped types + as + template literals = طريقة آلية لإنشاء getters وsetters وevent handlers types من model types." },
      { q: "ما هو tsconfig.json composite وmتى يُستخدم؟", a: "composite: true: يُفعّل project references. يتطلب: declaration: true، rootDir مُحدد، جميع الـsource files في rootDir. يُنشئ .d.ts وtsBuildInfoFile. يُتيح tsc --build لبناء متزايد. يمنع import دوائر بين projects. مطلوب لأي project يُستخدم reference في مشروع آخر. يُحسّن build time في monorepos كثيراً.", senior: "composite + project references + incremental بناء الـmonorepo الصحيح—تحسين أداء build بـ70-90%." },
      { q: "اشرح أهمية isolatedModules في TypeScript.", a: "isolatedModules: true: يُجبر كل ملف أن يكون module مستقلاً. يمنع: const enums (لا يمكن حلها بدون معرفة ملفات أخرى)، re-export types كـvalues، triple-slash references في بعض السياقات. مطلوب لـesbuild وswc وBabel—أدوات transpile ملفاً بملف. تُحسّن build speed كثيراً. استخدم verbatimModuleSyntax بدلاً في TS5+.", senior: "فعّل isolatedModules إذا كنت تستخدم esbuild/swc—يضمن التوافق ويكشف مشاكل مبكراً." },
      { q: "ما هو الفرق بين as const و Object.freeze؟", a: "as const: TypeScript compile-time فقط—يُجعل الأنواع literals وreadonly. لا تأثير وقت runtime، الـobject قابل للتعديل فعلياً. Object.freeze: runtime فقط—يمنع التعديل فعلياً (shallow). لا تأثير على TypeScript types بدون إعداد خاص. الجمع: as const Object.freeze({...}) للحالتين. في الممارسة: as const كافٍ لـconfig constants.", senior: "Object.freeze للأمان وقت runtime في boundaries حساسة، as const للـtype inference—اجمعهما في الـconfig الحساس." },
      { q: "اشرح كيفية بناء Type-safe State Machine.", a: "State Machine type-safe: تعريف States كـdiscriminated union. Events كـdiscriminated union. Transitions كـRecord<State['type'], Record<Event['type'], State>>. type Transition<S, E> = S extends any ? E extends any ? { from: S; event: E; to: NextState<S,E> } : never : never. XState مع TypeScript generator للـtype inference التلقائي.", senior: "XState v5 يُنشئ types من machine definition تلقائياً—الأفضل لـstate machines معقدة." },
      { q: "ما هو مفهوم Higher-Kinded Types في TypeScript؟", a: "Higher-Kinded Types (HKT): أنواع تأخذ type constructors (لا types) كـarguments. TypeScript لا يدعمها مباشرة. البديل: encoding بـinterface مع type member. مكتبات كـfp-ts تستخدم هذا الـencoding للـFunctor وMonad abstractions. HKT تُتيح كتابة كود generic فوق type constructors كـArray وOption وEither.", senior: "HKT encoding في TypeScript معقد—استخدمه فقط إذا كنت تبني FP library. في applications فضّل concrete types." },
      { q: "اشرح أهمية strict Property Initialization.", a: "strictPropertyInitialization: true: يُجبر على تهيئة class properties في constructor أو بـinitializer. يمنع runtime errors من الوصول لـundefined properties. ! operator يتجاوزه (definite assignment assertion). يتفاعل مع DI frameworks (Angular) التي تُهيئ خارج constructor. الحل: حدد القيم الافتراضية أو استخدم ! بتعليق توضيحي.", senior: "تجنب ! في class properties—بدلاً اجعل types optional أو أضف initializers حقيقية أو استخدم factory methods." },
      { q: "ما هو Type-safe Dependency Injection في TypeScript؟", a: "DI type-safe بدون decorators: Container<{logger: Logger; db: Database}>. type Get<T, K extends keyof T> = T[K]. resolve<K>(key: K): Get<Services, K>. مع tsyringe أو InversifyJS: decorators مع reflect-metadata. NestJS: DI كامل بـdecorators. typedi: سهل الاستخدام مع TypeScript. الـinterface-based injection أفضل من class-based.", senior: "DI بدون decorators ممكن بـcontainer typed بـgenerics—أوضح وأكثر type safety من reflect-metadata approach." },
      { q: "اشرح Template Method Pattern بـTypescript.", a: "Template Method بـTypeScript: abstract class بـabstract methods وconcretes. abstract يُجبر subclasses على implementation. أو بـgenerics: function template<T>(steps: {init: () => T; process: (t: T) => T; cleanup: (t: T) => void}) { const t = steps.init(); const result = steps.process(t); steps.cleanup(result) }. الـfunctional approach أكثر flexibility وتجنب الـclass hierarchy.", senior: "فضّل composition على inheritance—function-based template method أقل coupling وأسهل تركيب." },
      { q: "ما هو Exhaustive Type Checking وكيف يُطبّق؟", a: "Exhaustive checking يتأكد من تغطية جميع حالات union. الطريقة: function assertNever(x: never): never { throw new Error('Unexpected: ' + x) }. في switch default: return assertNever(shape). TypeScript يُبلّغ عن خطأ إذا وصلنا لـdefault مع حالة غير مُغطاة. مع ts-pattern: .exhaustive() يُجبر تغطية كل الحالات.", senior: "Exhaustive checking ضروري لـdiscriminated unions—كل إضافة لـunion تُنبّه كل مكان يحتاج تحديثاً." },
      { q: "اشرح كيف يعمل TypeScript مع Decorators الجديدة (TC39).", a: "TC39 Decorators (Stage 3، TS5+): syntax مختلف عن experimentalDecorators. Class Decorator: (target, context) => { context.name }. Method Decorator: (target, context) => wrapper. Field Decorator: (target, context) => initializer. لا reflect-metadata. context object يحتوي metadata مفيدة. لا يزال هناك تبايُن بين TS decorators والـTC39 spec.", senior: "انتظر استقرار TC39 decorators قبل الاعتماد عليها في production—الـspec لا يزال في تطور." },
      { q: "ما هو الفرق بين type-safe وtype-correct في TypeScript؟", a: "Type-correct: الكود يمر الـtype checker. Type-safe: الكود صحيح semantically ولا يُخفي أخطاء محتملة. مثال type-correct لكن غير type-safe: as any، as Type، !. الكود يمر بدون أخطاء لكن يمكن أن يفشل وقت runtime. Type safety الحقيقية: لا assertions، runtime validation عند الـboundaries، narrowing صحيح.", senior: "Type-correct ≠ Type-safe—الـtype assertions والـany يُعطيان false confidence. اسعَ لـtype safety الحقيقية." },
      { q: "اشرح كيفية استخدام TypeScript مع WebSockets.", a: "تعريف message types: type WSMessage = { type: 'chat'; data: string } | { type: 'error'; code: number }. Type-safe message parsing: استخدم zod لـparse وnarrow. Generic WebSocket wrapper: class TypedWS<Send, Receive>. Event handlers typed: ws.on('message', (msg: WSMessage) => { }. تعريف protocol في shared types بين frontend وbackend للـfull-stack type safety.", senior: "shared types بين client وserver للـWebSocket protocol—يمنع inconsistency ويوفر autocompletion على الجانبين." },
      { q: "ما هي أنماط TypeScript للـError Handling؟", a: "Result type: type Result<T,E> = { ok: true; value: T } | { ok: false; error: E }. Option type: T | null. Never throw—return errors. Typed exceptions: class AppError extends Error { constructor(public readonly code: ErrorCode, message: string)}. Error boundaries بـdiscriminated unions. neverthrow وtrue-myth مكتبات جاهزة للـResult pattern.", senior: "Result pattern أوضح من exceptions في TypeScript—يُجبر caller على التعامل مع الأخطاء بشكل explicit." },
      { q: "اشرح كيف تعمل infer مع Tuple Types.", a: "infer مع tuples تستخرج أجزاء من tuple types. مثال: type First<T extends unknown[]> = T extends [infer F, ...unknown[]] ? F : never. type Last<T extends unknown[]> = T extends [...unknown[], infer L] ? L : never. type Head<T extends unknown[]> = T extends [infer H, ...infer R] ? R : never. مفيد لبناء type-safe function pipelines.", senior: "Tuple infer أساس function composition types—يُتيح بناء Pipe<[A,B,C]> يتحقق من توافق الـfunctions تلقائياً." },
      { q: "ما هو الفرق بين Pick وOmit عند التعامل مع Unions؟", a: "Pick وOmit لا يعملان بشكل متوقع مع union types—يطبقان على كل member بشكل منفصل. DistributivePick: type DistributivePick<T, K extends keyof T> = T extends any ? Pick<T, K> : never. بدون distributive: Pick<A|B, 'x'> لا يعمل إذا كان 'x' في A فقط. مشكلة شائعة—تذكر أن Utility Types distributive بشكل محدود.", senior: "افهم distributive behavior للـutility types مع unions—مصدر كثير من الـtype errors الغامضة." },
      { q: "اشرح TypeScript Performance Best Practices.", a: "1) قلّل union size—split كبيرة لأصغر. 2) تجنب deeply nested conditional types. 3) استخدم interface بدل type للـobjects المدموجة. 4) قلّل barrel imports. 5) فعّل incremental builds. 6) skipLibCheck: true للـCI الأسرع. 7) Project references للـmonorepos. 8) استخدم --diagnostics لقياس. 9) تجنب recursive types العميقة.", senior: "أهم تحسين: قلّل barrel imports وفعّل incremental—يُحسّن type-check time بـ50-80% في مشاريع كبيرة." },
      { q: "ما هو الفرق بين Array.isArray وTypeScript Narrowing؟", a: "Array.isArray(x): runtime check، TypeScript يُضيّق النوع لـx is any[] (لا T[]). لـtype-safe narrowing: function isArrayOf<T>(arr: unknown, guard: (x: unknown) => x is T): arr is T[] { return Array.isArray(arr) && arr.every(guard) }. isArray مع union types: يُضيّق بشكل صحيح—Array<T>|T يتحقق منها. Tuple type غير مميزة عن array بـisArray.", senior: "اكتب typed array guards للـAPI responses—Array.isArray وحده لا يكفي للـtype safety الكاملة." },
      { q: "اشرح كيفية استخدام TypeScript Playground لتعلم الأنواع.", a: "TypeScript Playground: بيئة تفاعلية في المتصفح. يُظهر JS المُنتج وtypes وأخطاء. يمكن مشاركة links. يدعم كل إصدارات TS. .d.ts tab يُظهر declaration file المُنتج. مفيد لـexperiment مع generic types وchecking compatibility. استخدمه مع type-challenges للتعلم. بدائل: ts-fest، type-fest playground.", senior: "الـPlayground الأفضل لإثبات نقطة حول behavior معين—استخدمه للتوثيق وتبادل المعرفة في PRs." },
      { q: "ما هي أبرز مميزات TypeScript 5.x؟", a: "TS5.0: decorators جديدة (TC39)، const type parameters. TS5.1: unrelated types للـgetters/setters، return type undefined إلزامية. TS5.2: using declaration (explicit resource management)، decorator metadata. TS5.3: import attributes، resolution-mode في triple-slash. TS5.4: NoInfer، Object.groupBy types، Array grouping. TS5.5: inferred type predicates. كل إصدار يُحسّن الـinference.", senior: "تابع TypeScript releases—كل إصدار يحل مشاكل type inference حقيقية. الـchangelog يُعلّمك limitations الحالية." },
      { q: "اشرح Type-safe Routing في React مع TypeScript.", a: "React Router v6 مع TypeScript: useParams<{id: string}>. TanStack Router: type-safe من الأساس—route params وsearch params كلها typed. next-safe-navigation وhooks typed لـNext.js. defineRoute مع type inference. Problem: strings في paths لا type safety حقيقية بدون code generation. Solution: ts-morph أو codegen لـroute types.", senior: "TanStack Router أفضل حل حالياً لـtype-safe routing—كل params وsearch وloader data مكتوبة بشكل آمن." },
      { q: "ما هو مفهوم Phantom Types في TypeScript؟", a: "Phantom Types: type parameters تُستخدم للتتبع النوعي فقط دون أن تُمثّل بيانات فعلية. مثال: type Tagged<T, Tag> = T & { readonly _tag?: Tag }. type Dollars = Tagged<number, 'Dollars'>. type Euros = Tagged<number, 'Euros'>. يمنع خلط Dollars وEuros رغم أنهما number. لا overhead وقت runtime—الـtag لا يوجد فعلياً.", senior: "Phantom types للـunits، currencies، permissions—type safety قوية بثمن runtime صفري." },
      { q: "اشرح TypeScript مع GraphQL.", a: "Code generation من GraphQL schema: graphql-codegen. يُنشئ types لكل operation. Apollo Client 3+ مع generated types. urql أيضاً يدعم codegen. gql.tada: type-safe queries بدون codegen—infer types من query string مباشرة. TypeGraphQL: بناء schema من TypeScript classes. Pothos: schema builder type-safe بدون decorators.", senior: "graphql-codegen الطريقة الأكثر نضجاً—اجعله جزءاً من CI وcommit الـgenerated types للـrepository." },
      { q: "ما هو الفرق بين interface extends وtype intersection عملياً؟", a: "interface B extends A: دمج مع فحص توافق—TypeScript يُبلّغ عن خطأ إذا كان لديك خصائص متعارضة. type C = A & B: intersection تصنع never للخصائص المتعارضة بدون خطأ واضح—المشكلة تظهر عند الاستخدام فقط. extends أوضح للـhierarchies وأفضل للـerror messages. intersection أمرن للـmixins والـcomposition.", senior: "اختر extends للـhierarchies الواضحة—الـerror messages أفضل. احتفظ بـintersection للـad-hoc composition." },
      { q: "اشرح كيف يعمل TS مع Web Workers.", a: "Web Workers في TypeScript: ملف worker منفصل بـlib: ['WebWorker']. للـmessages: postMessage مع typed data. SharedWorker وServiceWorker لهم libs مختلفة. Comlink: يوفر RPC type-safe فوق Workers—Proxy<WorkerClass>. تعريف message protocol كـdiscriminated union shared بين main thread والـworker. moduleResolution يؤثر على الـimport في workers.", senior: "Comlink مع TypeScript أنظف API للـWeb Workers—تتعامل مع الـworker كـclass عادي مع async methods." }
    ]
  },
  {
    id: "nextjs", label: "Next.js", icon: "ti-brand-nextjs", color: "#ffffff",
    questions: [
      { q: "اشرح الفرق بين App Router وPages Router في Next.js.", a: "Pages Router (legacy): ملفات في /pages، getStaticProps/getServerSideProps، _app.tsx وسيط. App Router (Next.js 13+): ملفات في /app، React Server Components افتراضياً، layout.tsx، loading.tsx، error.tsx، route.ts. App Router أكثر قوة: server/client boundary، streaming SSR، nested layouts، parallel routes، intercepting routes.", senior: "انتقل لـApp Router في المشاريع الجديدة—الـPages Router سيظل مدعوماً لكن الـfeatures الجديدة في App Router فقط." },
      { q: "ما هي React Server Components وكيف تختلف عن Client Components؟", a: "Server Components (RSC): تُنفَّذ على السيرفر فقط، بدون JS على العميل، يمكنها قراءة قواعد البيانات مباشرة، لا state ولا effects. Client Components ('use client'): تُنفَّذ على العميل، تدعم useState وuseEffect والـevent handlers. RSC تُمرّر props للـClient Components. RSC تُقلل bundle size كثيراً—لا imports للـlibraries على العميل.", senior: "ابدأ بـServer Component لكل شيء وأضف 'use client' فقط عند الحاجة—يُقلل JS bundle ويُحسّن performance." },
      { q: "اشرح طبقات Caching في Next.js App Router.", a: "4 طبقات: 1) Request Memoization: خلال render واحد، تلقائية لـfetch. 2) Data Cache: بين requests، استمرار بين deploys، revalidate بـtime أو on-demand. 3) Full Route Cache: HTML وRSC payload على الديسك، يتجدد بـrevalidation. 4) Router Cache: على العميل، يحتفظ بـRSC payload زيارات الـpages. كل طبقة مستقلة وقابلة للتخصيص.", senior: "افهم الـ4 طبقات جيداً—نسيان إبطال الـData Cache مصدر أكثر caching bugs في Next.js." },
      { q: "اشرح كيف يعمل Streaming في Next.js.", a: "Streaming: إرسال HTML للمتصفح تدريجياً بدل انتظار render الكامل. Suspense boundaries تُحدد ما يُبثّ بشكل مستقل. loading.tsx: skeleton تلقائي للـroute. use() hook في RSC لـdata fetching مع Suspense. العميل يرى محتوى أسرع—TTFB أقل. Error boundaries مع error.tsx. Parallel data fetching داخل RSC.", senior: "ضع Suspense boundaries بذكاء—حول الـslow data fetchers لا حول الصفحة كلها." },
      { q: "ما هي Server Actions وكيف تعمل؟", a: "Server Actions (Next.js 14+): دوال async على السيرفر تُستدعى من Client Components. 'use server' directive. تُستخدم في forms (action prop) وevent handlers. تعيد data أو تُعيد توجيه. لا API endpoint صريح—Next.js ينشئ endpoint تلقائياً. revalidatePath وrevalidateTag لتحديث الـcache. تدعم Progressive Enhancement.", senior: "Server Actions تُبسّط CRUD كثيراً—لا تحتاج API route لكل mutation. استخدمها مع useFormState للـpending state." },
      { q: "اشرح Parallel Routes وIntercepting Routes.", a: "Parallel Routes (@folder): عرض أكثر من صفحة في نفس الـlayout في آنٍ واحد. مثال: @modal وbody في نفس الوقت. Intercepting Routes ((.)folder): اعتراض navigation داخلي مع عرض محتوى مختلف. مثال: فتح صورة في modal أثناء التصفح مع الاحتفاظ بـURL، وعرض الصورة كاملة على URL المباشر.", senior: "Parallel + Intercepting routes تُنشئ Instagram-like photo modals—قوية لكن تعقّد الـrouting؛ استخدمها بحذر." },
      { q: "ما هو الفرق بين generateStaticParams وgetStaticPaths؟", a: "getStaticPaths (Pages Router): يُعيد paths array مع fallback option. generateStaticParams (App Router): يُعيد array of params objects. أبسط—لا fallback prop منفصل. fallback يُعالَج بـnotFound() وloading.tsx. يعمل مع nested dynamic segments. يدعم partial prerendering في المستقبل. يعمل وقت build لـstatic generation.", senior: "generateStaticParams مع dynamicParams = false لموقع static كامل، مع true لـISR-like behavior." },
      { q: "اشرح Data Fetching Patterns في App Router.", a: "fetch() في RSC مع cache options: {cache: 'force-cache'} للـstatic، {cache: 'no-store'} للـdynamic، {next: {revalidate: 60}} للـISR. use() hook مع Suspense. Server Actions للـmutations. Route Handlers (route.ts) للـAPI endpoints. Parallel fetching: await Promise.all([fetch(url1), fetch(url2)]). waterfall fetching تجنّبه.", senior: "افتح parallel fetches بدل sequential—كل await منفصل يُضيف latency. استخدم Promise.all بحرية في RSC." },
      { q: "ما هو Partial Prerendering في Next.js؟", a: "Partial Prerendering (PPR، تجريبي): يجمع Static وDynamic في نفس الـroute. Shell الـpage يُنشأ statically وقت build. Dynamic parts (داخل Suspense) تُملأ dynamically. أفضل من الاختيار بين static كامل أو dynamic كامل. يتطلب experimental.ppr: true في next.config. سيكون الـdefault في المستقبل.", senior: "PPR المستقبل لـNext.js—ابدأ بتصميم apps بـSuspense boundaries صحيحة الآن لتكون جاهزاً." },
      { q: "اشرح كيف يعمل Next.js Image Optimization.", a: "next/image: تحسين تلقائي. Lazy loading افتراضي. srcset لكل الأحجام تلقائياً. WebP/AVIF تحويل تلقائي. Blur placeholder. priority prop للـLCP images. sizes prop للـresponsive images. يحتاج width وheight أو fill. Remote images تحتاج domains في next.config. يمنع Cumulative Layout Shift تلقائياً.", senior: "أضف priority لأول صورة فوق الـfold—تُحسّن LCP كثيراً. استخدم sizes prop لتوفير bandwidth." },
      { q: "ما هو الفرق بين redirect() وreplace() في App Router؟", a: "redirect(url): Server-side redirect، يُلقي NEXT_REDIRECT error—لا يُعيد. للاستخدام في Server Components وServer Actions وRoute Handlers. permanentRedirect(url): 308 بدل 307. useRouter().push(url): Client-side navigation بدون full page reload. useRouter().replace(url): تستبدل الـhistory entry بدل إضافة. router.refresh(): يُعيد fetch لـRSC data.", senior: "استخدم redirect() في Server Actions بعد mutation ناجح. useRouter().push() للـclient navigation البرمجي." },
      { q: "اشرح Middleware في Next.js.", a: "middleware.ts في root: يُنفَّذ قبل كل request. يعمل على Edge Runtime (لا Node.js APIs). NextResponse.redirect()، rewrite()، next(). قابل للتكوين بـmatcher config. مفيد لـauth، i18n، A/B testing، headers modification. لا يعمل مع static assets بشكل مباشر. أبطأ من Route Handlers للـheavy logic.", senior: "اجعل middleware بسيطاً وسريعاً—Edge Runtime محدود. للـheavy auth logic استخدم Route Handlers." },
      { q: "ما هي Route Handlers وكيف تختلف عن API Routes؟", a: "Route Handlers (route.ts في app/): تدعم كل HTTP methods كـexports named. يعملان مع Web Request/Response APIs (ليس Node.js req/res). يدعمان Streaming. يمكن export dynamic وrevalidate. GET handlers يُخزَّن في cache افتراضياً مع fetch. يدعمان cookies() وheaders(). API Routes (pages/api/): Pages Router، Node.js req/res.", senior: "Route Handlers أقوى وأحدث—استخدمها للـAPI endpoints الجديدة وهاجر من API Routes تدريجياً." },
      { q: "اشرح كيفية Revalidation في Next.js.", a: "Time-based: fetch({next: {revalidate: 60}}) أو export const revalidate = 60. On-demand: revalidatePath('/blog') وrevalidateTag('posts'). استخدم fetch({next: {tags: ['posts']}}) لتتبع الـtags. revalidatePath يُبطل Full Route Cache. revalidateTag يُبطل Data Cache بالـtag. من Server Actions أو Route Handlers. Webhooks مثال شائع لـon-demand revalidation.", senior: "On-demand revalidation أفضل من time-based في معظم الحالات—استخدم webhooks من CMS للـcontent updates." },
      { q: "ما هو next.config.js وأهم خياراته؟", a: "next.config.js أو mjs: reactStrictMode، swcMinify، images (domains, formats)، headers، redirects، rewrites، experimental، env، webpack config override، output ('standalone' للـDocker)، basePath، trailingSlash، pageExtensions، compress، productionBrowserSourceMaps، transpilePackages للـmonorepo packages.", senior: "استخدم headers() في next.config لـsecurity headers (CSP، HSTS)—أسهل من middleware لـheaders ثابتة." },
      { q: "اشرح TypeScript Integration في Next.js.", a: "Next.js يدعم TypeScript out-of-the-box. next.config تعريف: NextConfig type. Server Component params/searchParams: Promise<Params> في Next.js 15. generateMetadata: MetadataRoute.Manifest. Page props: { params, searchParams }. الـ15+ صارمة بـasync params. next/headers: cookies() وheaders() مع types. TypeScript plugin للـVS Code يُحسّن experience.", senior: "فعّل TypeScript plugin في VS Code (tsconfig.json editor settings)—يُعطي diagnostics للـApp Router بشكل مُحسَّن." },
      { q: "ما هو الفرق بين static وdynamic rendering في Next.js؟", a: "Static: يُنشأ HTML وقت build، يُخدَّم من CDN، أسرع. Dynamic: يُنشأ HTML لكل request. يُصبح الـroute dynamic تلقائياً عند: استخدام cookies()، headers()، searchParams، noStore()، أو fetch({cache: 'no-store'}). يمكن force بـexport const dynamic = 'force-dynamic'. PPR يجمعهما في نفس الـroute.", senior: "افحص ما يجعل الـroute dynamic بـ--debug flag أو build output—أحياناً dynamic بشكل غير متوقع." },
      { q: "اشرح Metadata API في Next.js App Router.", a: "Static metadata: export const metadata: Metadata = { title, description, openGraph, twitter }. Dynamic: export async function generateMetadata({params}). title template: { default, template, absolute }. يعمل في layout.tsx وpage.tsx. Metadata من layouts تُدمج مع Pages. يدعم icons، robots، canonical URL، viewport. Structured data بـjson-ld في لـSEO.", senior: "استخدم title template في root layout وoverride بـabsolute حسب الحاجة—يُبسّط إدارة titles لموقع كبير." },
      { q: "ما هو Edge Runtime مقارنة بـNode.js Runtime في Next.js؟", a: "Edge Runtime: يعمل على Vercel Edge Network، أسرع cold start، محدود (لا Node.js APIs، لا fs، لا Buffer كامل). Node.js Runtime: كامل الميزات، بطيء أكثر في cold start. تعريف: export const runtime = 'edge' | 'nodejs'. Middleware يعمل على Edge فقط. Route Handlers تختار. Edge أفضل لـauth وgeolocation وA/B testing.", senior: "استخدم Edge للـroutes التي تحتاج low latency بدون Node.js APIs. Node.js للـheavy server logic وقواعد البيانات." },
      { q: "اشرح كيف تعمل Layouts في App Router.", a: "layout.tsx: مشترك بين child routes، لا يُعاد render عند navigation. RootLayout إلزامي ويحتوي html وbody. Nested layouts تتراكم. Template.tsx: مشابه لكن يُعاد render عند كل navigation. Group layouts ((group)/layout.tsx) بدون تأثير على الـURL. Parallel routes لديها layouts مستقلة. الـlayout يتلقى children prop.", senior: "تجنب heavy data fetching في layouts—يُؤثر على كل child route. فضّل fetch في page.tsx نفسه." },
      { q: "ما هو output: 'standalone' في Next.js وفائدته؟", a: "output: 'standalone' في next.config: يُنشئ مجلداً مكتفياً ذاتياً للـproduction. يشمل فقط الـfiles المطلوبة (لا node_modules كاملاً). مثالي لـDocker images صغيرة. يُنشئ server.js للتشغيل. يجب نسخ public/ وstatic/ يدوياً للـDocker image. يُقلل image size من 1GB+ لـ~100MB. مطلوب لـKubernetes deployments.", senior: "standalone output + multi-stage Docker build = أصغر image ممكن. أضف health check endpoint لـKubernetes readiness." },
      { q: "اشرح next/font وفوائده.", a: "next/font: تحميل fonts محلياً مع zero layout shift. Google Fonts بدون طلبات خارجية. variable fonts مدعومة. CSS variables للاستخدام في Tailwind. تحجيم font تلقائي لمنع CLS. self-hosted: font-display: swap تلقائياً. variable font للـperformance: يحل محل خطوط متعددة. يعمل مع Inter, Geist, وأي Google Font.", senior: "استخدم next/font بدل @import CSS أو link tag—يضمن zero layout shift ويُحسّن LCP." },
      { q: "ما هو Turbopack وكيف يختلف عن Webpack؟", a: "Turbopack (Rust-based): بديل Webpack الجديد من Vercel. أسرع بكثير في dev server (10x-700x حسب ادعاءات Vercel). يدعم معظم Webpack features الشائعة. لا يزال في تطور—بعض plugins غير مدعومة. مستقر للـdev في Next.js 15. للـproduction build: Webpack لا يزال الافتراضي. الاستخدام: next dev --turbo.", senior: "جرّب Turbopack في dev—يُحسّن DX كثيراً. احتفظ بـWebpack للـproduction حتى يستقر Turbopack كاملاً." },
      { q: "اشرح كيفية التعامل مع Environment Variables في Next.js.", a: "NEXT_PUBLIC_VAR: متاح على العميل والسيرفر. VAR بدون prefix: سيرفر فقط. .env.local: لا يُرفع لـgit. .env.development و.env.production: بيئة محددة. .env: default. runtime env مقابل build-time env. في App Router: Server Components ترى الـserver env variables مباشرة بدون NEXT_PUBLIC.", senior: "لا تضع secrets في NEXT_PUBLIC—تظهر في الـJS bundle. استخدمها فقط للـpublic keys (analytics IDs)." },
      { q: "ما هي أفضل ممارسات Performance في Next.js؟", a: "1) Server Components افتراضياً—قلل 'use client'. 2) parallel data fetching في RSC. 3) next/image مع priority للـLCP. 4) next/font لمنع CLS. 5) route-based code splitting تلقائي. 6) bundle analyzer لفحص الـbundle. 7) الـDynamic import لـheavy components. 8) Partial Prerendering للـroutes الـhybrid. 9) CDN caching headers صحيحة. 10) Core Web Vitals monitoring.", senior: "قس أولاً بـLighthouse وCore Web Vitals—حسّن بترتيب impact: LCP، CLS، FID/INP." },
      { q: "اشرح كيف يعمل App Router مع Authentication.", a: "middleware.ts للـroute protection—يتحقق من token ويُعيد توجيه. Session في cookies (httpOnly). Server Actions للـlogin/logout. NextAuth.js (Auth.js): يدعم App Router، يوفر session في RSC. cookies() في Server Components للـsession. الـprotection طبقات: middleware (سريع)، layout (لـUI)، server action/route handler (حد أخير). CSRF protection تلقائية في Server Actions.", senior: "Auth.js مع middleware + server-side session check أفضل نموذج—لا تعتمد على client-only auth checks." },
      { q: "ما هو الفرق بين useRouter في App Router وPages Router؟", a: "Pages Router useRouter: من next/router. يحتوي: pathname، query، asPath، locale. push، replace، back، refresh. App Router useRouter: من next/navigation. يحتوي: push، replace، refresh، back، forward. لا pathname—استخدم usePathname(). لا query—استخدم useSearchParams(). المكتبتان غير متبادلتان.", senior: "انتبه للـimport—next/router للـPages، next/navigation للـApp Router. خلطهما سبب شائع للـbugs في migration." },
      { q: "اشرح كيف تعمل error.tsx وglobal-error.tsx.", a: "error.tsx: Client Component، يعترض أخطاء الـRoute segment وما دونها. يستقبل error وreset props. reset() يُعيد محاولة render الـsegment. لا يعترض أخطاء الـlayout.tsx في نفس الـsegment. global-error.tsx: في root، يعترض أخطاء layout.tsx الأساسي. يجب أن يحتوي html وbody. not-found.tsx: لـnotFound() throws.", senior: "ضع error.tsx على مستوى كل feature لا على المستوى الجذر فقط—تُقلل impact الـerrors وتُحسّن UX." },
      { q: "ما هو Bundle Analyzer في Next.js وكيف يُستخدم؟", a: "@next/bundle-analyzer: يُحلل حجم الـJS bundles. إضافته لـnext.config.js. ANALYZE=true npm run build لتشغيله. يُظهر ما داخل كل chunk. يكشف large dependencies، duplicate code، missing tree-shaking. نتائج شائعة: moment.js ضخم (استخدم date-fns)، full lodash (استخدم lodash-es + tree shaking)، unoptimized icon libraries.", senior: "شغّل bundle analyzer قبل كل release—اصنع budget للـbundle size وافحصه في CI." },
      { q: "اشرح Internationalization في Next.js App Router.", a: "App Router: لا built-in i18n. الطرق: middleware مع locale detection، dynamic segment [lang]، دالة getDictionary(lang). مكتبات: next-intl (الأفضل)، next-i18next (Pages Router)، rosetta. next-intl: messages في JSON files، useTranslations hook، Server Components support، type-safe translations بـcodegen. RTL: dir={locale === 'ar' ? 'rtl' : 'ltr'} في root layout.", senior: "next-intl مع App Router الخيار الأفضل حالياً—يدعم RSC وServer Actions بشكل ممتاز." },
      { q: "ما هو Vercel و Deployment Strategies لـNext.js؟", a: "Vercel: المنصة الأصلية لـNext.js—صفر config، Edge Network، preview deployments، analytics. بدائل: self-hosted مع Node.js (output: standalone)، Docker، AWS Lambda@Edge (OpenNext)، Cloudflare Pages (محدود). دائماً الـproduction build أولاً (npm run build) ثم npm start. env variables في منصة الـdeployment. Database connection pooling مع Serverless (PgBouncer).", senior: "لا تقيس performance في dev mode—دائماً test بـproduction build. الـdev mode أبطأ بـ10x." },
      { q: "اشرح كيف يعمل next/link.", a: "next/link: Client-side navigation بدون full reload. يُحسّن تلقائياً: prefetch عند hover (production)، scroll restoration، focus management. prefetch={false} لتعطيل. scroll={false} للتحكم. يستقبل href كـstring أو object. في App Router: يُمرر href مباشرة للـa tag الداخلي. يدعم replace وshallow (بـuseRouter في بعض الحالات).", senior: "لا تضع onClick للـnavigation—استخدم Link. احتفظ بـonClick للـside effects إضافية فقط." },
      { q: "ما هو ISR في Next.js وكيف تطور مع App Router؟", a: "ISR (Incremental Static Regeneration): Pages Router—revalidate في getStaticProps. يُعيد build الصفحة background بعد الوقت المحدد. App Router: fetch({next: {revalidate: seconds}}) أو export const revalidate = seconds. On-demand ISR: Pages Router—res.revalidate(path). App Router: revalidatePath() وrevalidateTag() في Server Actions/Route Handlers. Stale-while-revalidate semantics.", senior: "فضّل on-demand revalidation عبر webhooks على time-based—محتوى أحدث وأقل compute." },
      { q: "اشرح أهمية Server Component Composition.", a: "Server Components يمكن أن تحتوي Client Components. Client Components لا يمكنها import Server Components مباشرة—لكن يمكن تمريرها كـchildren أو props. نمط 'children as server component': Client Component تستقبل Server Component كـchildren دون أن تعرف نوعه. يُبقي الـserver rendering للأجزاء التي لا تحتاج state. يُقلل JS bundle كثيراً.", senior: "هذا النمط يحل مشكلة 'أريد context لكن لا أريد client component'—تعلّمه جيداً لـcomposition صحيح." },
      { q: "ما هو loading.tsx وكيف يختلف عن Suspense؟", a: "loading.tsx: shorthand لـSuspense مع fallback. يُعيد Suspense تلقائياً حول page.tsx وchildren في نفس الـsegment. يُظهر فوراً عند navigation قبل تحميل الـpage. لا يتطلب Suspense wrapper يدوي. Suspense يدوياً: للتحكم الدقيق على الـfallback على مستوى component. يمكن دمجهما: loading.tsx كـouter fallback وSuspense للـinner loading states.", senior: "استخدم loading.tsx للـroute-level loading وSuspense للـcomponent-level—طبقات مختلفة من تجربة المستخدم." },
      { q: "اشرح كيف يعمل Next.js مع Databases.", a: "Server Components تقرأ DB مباشرة بدون API. ORMs: Prisma (الأكثر شيوعاً)، Drizzle (أحدث، أخف)، Kysely. Serverless considerations: connection pooling مع PgBouncer أو Neon، Supabase، PlanetScale. لا تُخزّن connection في global مع Serverless. Prisma مع Next.js: singleton pattern بدون hot reload issues في dev. EDGE runtime لا يدعم TCP connections.", senior: "استخدم Drizzle مع Neon أو Supabase للـserverless—أخف من Prisma وأسرع cold start." },
      { q: "ما هو next-safe-action وفائدته؟", a: "next-safe-action: type-safe Server Actions. يضيف schema validation بـzod، metadata، middleware. createSafeActionClient: يُنشئ client مع middleware لـauth وlogging. .schema(zodSchema): يُعيد action مع typed input. useAction hook: يتتبع pending وdata وerror. يُوحّد error handling وvalidation. أفضل من Server Actions الخام للـapps الكبيرة.", senior: "next-safe-action يُبسّط Server Actions كثيراً—validation وauth وerror handling في مكان واحد." },
      { q: "اشرح أنماط State Management في Next.js App Router.", a: "Server state: RSC + Data Cache كافٍ. URL state: searchParams (مشترك بين server وclient). Form state: useFormState (React) أو useActionState (React 19). Local component state: useState كالمعتاد. Global client state: Zustand أو Jotai (أخف من Redux). تجنب hydration mismatches: لا Date.now() وlanguage-specific في RSC.", senior: "فكّر بـURL كأول مخزن للـstate—searchParams تُشارك، تُحفظ، وتدعم back/forward. أفضل من useState للـfilters." },
      { q: "ما هو الفرق بين pages/api وapp/api/route.ts؟", a: "pages/api: Handler function بـ(req, res) Node.js style. لا دعم لـStreaming. الـreq/res من Node.js. تعمل في Node.js runtime فقط. app/api/route.ts: Web Standard Request/Response. تدعم Streaming. تعمل في Edge أو Node.js runtime. HTTP methods كـexports منفصلة (GET, POST...). يدعم الـcache والـrevalidation. الـbody parsing تلقائي.", senior: "انتقل لـRoute Handlers في المشاريع الجديدة—Web Standard APIs محمولة وستبقى طويلاً." },
      { q: "اشرح كيفية Testing في Next.js.", a: "Jest + React Testing Library: للـcomponents وServer Components. Playwright/Cypress: E2E tests. @testing-library/react renderهـServer Components محدود—فضّل E2E. next/jest: config تلقائي. msw: لـAPI mocking. مشاكل: testing RSC معقد (يحتاج server environment)، useRouter mocking، cookies()/ headers() mocking بـjest.mock().", senior: "ركّز E2E tests على user journeys الحقيقية لـNext.js—unit tests للـlogic المعزولة فقط." },
      { q: "ما هي أبرز مميزات Next.js 15؟", a: "Next.js 15 (2024): React 19 support. params وsearchParams أصبحا Promises (async). Turbopack مستقر للـdev. unstable_cache API تحسّن. Form component جديد. next/after API لـpost-response tasks. الـCaching behavior تغيّر: fetch no longer cached by default. الـGET Route Handlers لم تعد مُخزّنة افتراضياً. cookies() وheaders() أصبحا async.", senior: "هاجر بحذر لـNext.js 15—params async يتطلب await في كل مكان. الـcaching changes قد تُغيّر سلوك apps موجودة." },
      { q: "اشرح Optimistic Updates في Next.js مع Server Actions.", a: "useOptimistic hook (React 19): يُضيف state مؤقت optimistically. Server Action تُرسل للسيرفر. إذا نجح: الـreal state يُحدَّث. إذا فشل: يرجع للحالة الأصلية. مثال: إضافة comment يظهر فوراً ثم يُحدَّث. مع useActionState: pending state للـbutton. يُحسّن UX كثيراً للـmutations البطيئة.", senior: "useOptimistic غيّر كيف نُفكّر في mutations—UI أولاً ثم server يلحق. سيصبح standard pattern." },
      { q: "ما هو next/headers وmتى يُستخدم؟", a: "next/headers: يُوفر cookies() وheaders() في Server Components وServer Actions وRoute Handlers. يجعل الـroute dynamic تلقائياً. cookies().get(name)، cookies().set(name, value) (في Server Actions وRoute Handlers فقط). headers().get(name) للقراءة. draftMode() لـpreview mode. في Next.js 15: أصبحا async—await cookies().", senior: "تجنب cookies() في layouts إذا كان المحتوى يمكن أن يكون static—يُحوّل الـroute لـdynamic غير ضروري." },
      { q: "اشرح كيف يعمل Font Optimization في Next.js.", a: "next/font/google: يُحمّل Google Fonts locally. لا طلبات خارجية. يُنشئ CSS variable. subset آلي. preloading للـcritical fonts. next/font/local: للـcustom fonts. variable prop لـcss variable name. يتكامل مع Tailwind. font-display: swap تلقائياً. يمنع FOUT تماماً. يُحسّن CLS والـLighthouse score.", senior: "استخدم CSS variable مع Tailwind fontFamily config بدل className مباشرة—أكثر مرونة وisolation." },
      { q: "ما هو الفرق بين Server-side Rendering وStatic Generation في Next.js؟", a: "SSG: يُنشأ وقت build، يُخدَّم من CDN، أسرع. SSR: يُنشأ لكل request، أحدث بيانات، أبطأ. App Router يوحّدهما: fetch cache option تُحدد السلوك. {cache: 'force-cache'}: static (مثل SSG). {cache: 'no-store'}: dynamic per request (مثل SSR). ISR: وسط—static مع periodic revalidation. PPR: يجمعهما في نفس الـroute.", senior: "فكّر بـdata freshness requirements لا بـSSR/SSG—اختر caching strategy بناءً على كم يجوز أن تكون البيانات قديمة." },
      { q: "اشرح كيف يعمل App Router مع SEO.", a: "Metadata API: title، description، OG، Twitter Card. generateMetadata للـdynamic pages. Canonical URL بـmetadata.alternates.canonical. Structured data بـjson-ld في page.tsx. sitemap.ts وrobots.ts لـاستهداف الـcrawlers. opengraph-image.tsx لـدينامية OG images. Server rendering تلقائي—Googlebot يرى HTML الكامل. اللغة: hreflang في metadata.alternates.languages.", senior: "استخدم generateMetadata بشكل صحيح—البيانات الوصفية الخاطئة تُضيع الـSEO. اختبر بـTwitter Card Validator وFacebook Debugger." },
      { q: "ما هو next/og وكيف يُنشئ Open Graph Images؟", a: "next/og (@vercel/og): يُنشئ OG images ديناميكية بـJSX في Edge Runtime. Route Handler في opengraph-image.tsx. يستخدم Satori لتحويل JSX لـSVG ثم PNG. يدعم: custom fonts، nested flexbox، images. سريع جداً—Edge Runtime مع caching. أفضل من sharp في Serverless. حجم max 1MB للـfont files.", senior: "og images ديناميكية تُحسّن sharing كثيراً—اصنع template يتضمن عنوان المقالة والـbrand لكل page تلقائياً." },
      { q: "اشرح كيفية Error Handling في Server Actions.", a: "try/catch في Server Action: يُعيد error كـdata لا يُلقيه. useFormState/useActionState: يستقبل الـresponse. لا تُلقِ Error من Server Action إلى Client—استخدم Result pattern. للـvalidation: zod parse والإعادة errors بنية محددة. redirect() يُلقي internally (NEXT_REDIRECT)—اتصل به خارج try/catch. يمكن إعادة typed errors بـdiscriminated union.", senior: "اجعل Server Actions تُعيد {success: true, data} أو {success: false, error}—لا تعتمد على throws للـbusiness logic." },
      { q: "ما هو Suspense في Next.js وما الفرق عن React Suspense؟", a: "Next.js يبني فوق React Suspense. يضيف: streaming من server، integration مع الـData Cache، loading.tsx shorthand. React Suspense الأساسية للـlazy loading. Next.js Suspense للـdata fetching على السيرفر. use() hook يُوقف component حتى Promise resolves (RSC). Suspense boundaries تُفعّل streaming للـsegment. الـfallback يُرسَل فوراً ثم يُستبدل بالـcontent.", senior: "صمّم Suspense boundaries أولاً ثم data fetching—تُحسّن UX بشكل جذري لـpages ذات data متعددة." },
      { q: "اشرح كيف يتعامل Next.js مع Static Assets.", a: "مجلد public/: الملفات متاحة بـURL مباشر /file.png. لا hashing—تغيير الملف يتطلب تغيير الاسم للـcache busting. next/image: هاشٌ تلقائي، WebP تحويل، sizing. Static imports للصور: import img from './photo.png'—يُعطيك object مع src وwidth وheight. SVGs: كـcomponents بـsvgr أو img tag. Fonts: في public/ أو عبر next/font.", senior: "استخدم static import للصور المعروفة—تحصل على TypeScript types وwidth/height تلقائياً بدون JSX errors." },
      { q: "ما هو Draft Mode في Next.js؟", a: "Draft Mode: يُعطّل Static Generation ويُجبر الـroute على render حياً. للـpreview content من CMS قبل publish. draftMode().enable() وdraftMode().disable() في Route Handler. draftMode().isEnabled في Server Components. يُخزَّن في cookie. يُعيد الصفحة dynamic لحاملي الـdraft cookie فقط. باقي الزوار يرون الـcached static version.", senior: "Draft Mode ضروري لكل موقع محتوى مع CMS—يُتيح للـeditors مشاهدة التغييرات قبل النشر." },
      { q: "اشرح next/after API في Next.js 15.", a: "next/after (Next.js 15): ينفّذ كود بعد إرسال الـresponse للعميل. مفيد لـanalytics، logging، cleanup بدون تأخير الـresponse. after(() => { logToDb(event) }). لا يُحتسب في response time. يعمل في Server Components، Route Handlers، Server Actions، Middleware. تحتاج دعم platform للـexecution بعد response (Vercel يدعمه).", senior: "after() يُحل مشكلة fire-and-forget analytics بدون تأخير response—لكن تأكد أن deployment platform يدعمه." },
      { q: "ما هو الفرق بين cookies في Server vs Client في Next.js؟", a: "Server: cookies() من next/headers (async في Next.js 15). قراءة وكتابة في Server Actions وRoute Handlers. قراءة فقط في Server Components. Client: document.cookie (محدود وليس httpOnly). JS-cookie library. useCookies hook. HTTP-only cookies: فقط من السيرفر. مثال: session token في httpOnly cookie لا يمكن قراءته من JS.", senior: "ضع auth tokens في httpOnly cookies لا localStorage—يحمي من XSS. اقرأها فقط من Server Components." },
      { q: "اشرح App Router Navigation وpreloading.", a: "Link component: يُفعّل prefetch تلقائياً عند viewport intersection (production). prefetch={false}: لتعطيل. useRouter().prefetch(href): برمجي. Prefetch يُحمّل RSC payload والـdata. لا full page HTML. الـRouter Cache يحتفظ بالـprefetched pages. staleTime للـRouter Cache: 30s static، 0s dynamic. router.refresh() لتحديث الـRSC payload.", senior: "prefetch يُحسّن navigation كثيراً—تجنب تعطيله إلا لـlinks بـdata ثقيلة جداً أو محمية بـauth." },
      { q: "ما هي patterns التعامل مع Authentication في Next.js 15؟", a: "Auth.js v5 (NextAuth): يدعم App Router بالكامل. Session في JWT أو Database. middleware.ts للـprotection. getServerSession() في RSC. Server Actions لـlogin/logout. OAuth providers سهل الإضافة. JWT: ioSession في cookie. Database session: أثقل لكن revocable. Clerk: managed auth service، أسرع للـprototyping.", senior: "Auth.js v5 + middleware هو الـstack الأكثر نضجاً. Clerk لـprototypes وstartups تريد auth بدون تعقيد." },
      { q: "اشرح كيف تعمل Container Queries مع Next.js وTailwind.", a: "Tailwind v4 يدعم container queries أصلاً. CSS: @container (min-width: 400px) { ... }. Next.js: مدعومة بشكل كامل مع Tailwind. الفائدة: components تستجيب لحجمها لا لـviewport. مثال: Card يتكيف سواء كان في sidebar ضيق أو main content واسع. مع Tailwind: @container class على parent، @md: prefix على children.", senior: "Container queries أقوى من media queries للـreusable components—component-driven responsive بدل page-driven." },
      { q: "ما هو unstable_cache في Next.js وكيف يختلف عن fetch cache؟", a: "unstable_cache: يُخزّن نتيجة دالة أي (لا فقط fetch). يدعم tags وrevalidate. استخدمه مع ORM queries (Prisma, Drizzle). مثال: const getUser = unstable_cache(async (id) => db.user.findUnique({where:{id}}), ['user'], {tags: ['users'], revalidate: 60}). revalidateTag('users') يُبطله. أسرع من API roundtrip. يعمل مع Data Cache طبقة.", senior: "unstable_cache مع Drizzle/Prisma هو ISR للـdatabase queries—الـpattern الأكثر قوة لـperformance." },
      { q: "اشرح أنماط Testing لـServer Components.", a: "Server Components تحتاج server environment للـtest. خيارات: 1) E2E tests مع Playwright—الأبسط. 2) Storybook مع MSW لـmocking. 3) jest-environment-node بتهيئة خاصة. 4) اختبار الـlogic المعزول (utility functions بدون RSC). 5) @testing-library/react لـClient Components فقط. التحدي: RSC يعتمد على headers()، cookies()، redirect() التي تحتاج mocking دقيق.", senior: "الاستراتيجية الأفضل: unit test logic، E2E test user flows، تجنب unit test للـRSC نفسها." }
    ]
  },
  {
    id: "system", label: "System Design", icon: "ti-sitemap", color: "#f59e0b",
    questions: [
      { q: "ما هي خطوات الإجابة على سؤال System Design في المقابلة؟", a: "1) توضيح المتطلبات (Functional + Non-Functional). 2) تقدير الحجم (DAU، RPS، storage). 3) الـAPI design على مستوى عالٍ. 4) تصميم البيانات (schema، database choice). 5) الـHigh-Level Design (components diagram). 6) Deep Dive على مكون حرج. 7) التعامل مع bottlenecks والـscaling. 8) مناقشة trade-offs.", senior: "ابدأ دائماً بتوضيح المتطلبات—المقابل يريد رؤية عملية التفكير لا الإجابة الصحيحة فقط." },
      { q: "اشرح كيف تُصمّم URL Shortener مثل bit.ly.", a: "المتطلبات: اختصار URLs، redirect، analytics اختياري. تقدير: 100M URLs/day writes، 10:1 read:write ratio = 1B reads/day. Schema: id (base62، 7 chars)، original_url، created_at، user_id. DB: SQL للبيانات الأساسية. Cache: Redis لأكثر URLs شيوعاً (80/20 rule). CDN لـredirects. Hashing: counter + base62 encoding. 301 vs 302 redirect.", senior: "الـcounter approach أفضل من الـhashing لتجنب collisions—ولكن يحتاج distributed counter أو single ID generator." },
      { q: "كيف تُصمّم News Feed مثل Twitter/Facebook؟", a: "نموذجان: Push (fanout on write) وPull (fanout on read). Push: عند النشر، اكتب في feed كل followers—سريع للقراءة لكن ثقيل للـcelebrities. Pull: اجمع posts من الـfollowees وقت القراءة—أبطأ لكن أخف للكتابة. Hybrid: Push للـregular users، Pull للـcelebrities (>مليون follower). Cache الـfeed المُجمَّع. Redis sorted set بـtimestamp كـscore.", senior: "Hybrid approach هو ما تستخدمه Twitter وFacebook—الحد بين push وpull يُضبط تجريبياً حسب الـload." },
      { q: "اشرح تصميم Rate Limiter.", a: "Algorithms: Fixed Window (بسيط، edge case عند الحدود)، Sliding Window Log (دقيق، ثقيل)، Sliding Window Counter (hybrid)، Token Bucket (bursty traffic)، Leaky Bucket (uniform rate). Storage: Redis لـdistributed. Keys: IP أو user_id أو API key. Headers: X-RateLimit-Limit، X-RateLimit-Remaining، Retry-After. Placement: API Gateway أو middleware.", senior: "Token Bucket الأكثر استخداماً للـAPIs—يسمح بـbursts ضمن حدود. Redis INCR + EXPIRE للـfixed window implementation." },
      { q: "كيف تُصمّم Distributed Cache مثل Redis Cluster؟", a: "Sharding: Consistent Hashing لتوزيع البيانات. Replication: Master-Slave لـhigh availability. Eviction: LRU، LFU، TTL. Cache patterns: Cache-aside، Write-through، Write-back، Read-through. Cache invalidation: TTL، event-based، explicit delete. Thundering herd problem: jitter في TTL، mutex locks. Cache stampede: probabilistic early expiration.", senior: "Cache invalidation أصعب مشكلة في caching—استخدم event-driven invalidation بدل pure TTL للبيانات الحرجة." },
      { q: "اشرح تصميم نظام Notification مثل إشعارات WhatsApp.", a: "مكونات: Notification Service، Message Queue، Device Registry، Delivery Service. Protocols: APNS (iOS)، FCM (Android)، WebSocket (web)، Email/SMS (fallback). Queue: Kafka للـhigh throughput. Fan-out: لكل user بـmultiple devices. Retry mechanism للـfailed deliveries. Deduplication بـidempotency key. Storage: MongoDB للـnotification history. Rate limiting للـspam prevention.", senior: "فكّر في at-least-once delivery—الـduplication أفضل من الضياع. الـidempotency key يمنع الإشعارات المكررة." },
      { q: "كيف تُصمّم Search مثل Elasticsearch؟", a: "Indexing: Inverted Index—كلمة → [doc_ids]. Tokenization وStemming. Index Sharding للـscale. Query types: Full-text، Fuzzy، Prefix، Range، Geo. Ranking: TF-IDF، BM25، custom scoring. Real-time updates: write-ahead log. Caching frequent queries. Primary DB وElasticsearch مزامنة عبر CDC. Autocomplete: Trie أو Redis Sorted Set.", senior: "Elasticsearch مع CDC (Debezium) لمزامنة DB هي الـarchitecture القياسية—لا تكتب للـES مباشرة من التطبيق." },
      { q: "اشرح تصميم Ride-sharing مثل Uber.", a: "مكونات: Location Service، Matching Service، Trip Service، Pricing Service. Location: drivers يُرسلون location كل 5 ثواني → Kafka → Redis Geo (GEOADD/GEORADIUS). Matching: K-Nearest drivers بناءً على location. Supply/Demand: Surge pricing algorithm. Real-time communication: WebSocket أو SSE. DB: drivers location في memory، trips في PostgreSQL. الـETA من routing engine.", senior: "Redis GEORADIUS لـnearby driver search—O(N+log(M)) أسرع بكثير من SQL geospatial queries للـreal-time location." },
      { q: "كيف تُصمّم Distributed Message Queue مثل Kafka؟", a: "مكونات: Producers، Brokers، Consumers، Zookeeper. Topics: مقسمة لـPartitions. Partition key: لضمان الترتيب. Consumer Groups: لـhorizontal scaling. Offsets: كل consumer يتتبع موضعه. Retention: based on time أو size. At-least-once delivery. Replication factor لـdurability. Leader election per partition. Log compaction للـstate topics.", senior: "Kafka الخيار الأفضل للـhigh throughput event streaming—RabbitMQ أفضل للـcomplex routing والـlow latency." },
      { q: "اشرح CAP Theorem وتطبيقه في اختيار قواعد البيانات.", a: "CAP: يمكن ضمان اثنتين فقط من ثلاث: Consistency، Availability، Partition Tolerance. الأنظمة الموزّعة دائماً تواجه network partitions—الاختيار الحقيقي بين CP وAP. CP: ZooKeeper، HBase—يوقف الخدمة بدل بيانات غير متسقة. AP: Cassandra، DynamoDB—متاح لكن قد يُعيد بيانات stale. PACELC يُوسّع النموذج: Latency vs Consistency بدون partitions.", senior: "أغلب التطبيقات تحتاج AP مع eventual consistency—فكّر في ما يعنيه 'stale data' لمنتجك بشكل ملموس." },
      { q: "كيف تُصمّم Object Storage مثل S3؟", a: "مكونات: Metadata Service، Data Nodes، Load Balancer، API Service. Chunking: ملفات كبيرة تُقسّم لـchunks (5MB-100MB). Erasure Coding بدل simple replication لتوفير storage. Consistent Hashing لتوزيع الـchunks. Metadata في DB منفصل (PostgreSQL أو DynamoDB). Multipart Upload للملفات الكبيرة. Versioning و lifecycle policies. CDN أمام الـread requests.", senior: "Erasure Coding (10+4 مثلاً) يحتاج storage أقل من 3x replication مع نفس الـdurability—الفارق ضخم بالـPetabytes." },
      { q: "اشرح تصميم Video Streaming مثل YouTube.", a: "Upload: المستخدم يُرفع لـStorage Service → Queue → Encoding Service (multiple resolutions/formats). CDN لتوزيع الـvideo globally. Adaptive Bitrate Streaming: DASH أو HLS—يُغيّر الجودة تلقائياً. Metadata: PostgreSQL. View counts: Redis counter batch-written لـDB. Comments: مُقسَّمة بـvideo_id. Recommendations: ML pipeline منفصل. Thumbnails: مُخزَّنة بشكل منفصل.", senior: "الـtranscoding pipeline الأكثر تكلفةً في الموارد—استخدم GPU instances وبرمجة مُتوازية للـencoding." },
      { q: "كيف تُصمّم Distributed Transaction بدون 2PC؟", a: "SAGA Pattern: سلسلة من local transactions مع compensating transactions عند الفشل. Choreography: كل service تُطلق event عند الانتهاء. Orchestration: SAGA orchestrator يُدير التسلسل. Outbox Pattern: كتابة message وDB في transaction واحد. Event Sourcing: سجل أحداث بدل state مباشرة. TCC (Try-Confirm-Cancel): مرحلة reserve ثم confirm أو cancel.", senior: "SAGA مع Outbox Pattern أقل تعقيداً من 2PC وأكثر مرونة—استخدمه للـmicroservices transactions." },
      { q: "اشرح كيف تُصمّم API Gateway.", a: "وظائف: Routing، Authentication، Rate Limiting، Load Balancing، SSL Termination، Request/Response Transformation، Caching، Circuit Breaker. مكونات: Load Balancer، Auth Middleware، Rate Limiter، Service Registry. Protocols: REST، gRPC، WebSocket. الـauthentication: JWT validation على الـgateway. Service discovery: Consul أو Kubernetes DNS.", senior: "API Gateway يُبسّط الـclients ويُوحّد الـcross-cutting concerns—لكن لا تضع business logic فيه." },
      { q: "كيف تُصمّم نظام Payments مثل Stripe؟", a: "أولويات: Correctness، Idempotency، Auditability. Idempotency Key: كل request بـunique key—نفس الـkey تُعيد نفس النتيجة. Double-entry Bookkeeping: كل transaction تؤثر على حسابين. Reconciliation: مطابقة يومية مع البنوك. ACID transactions للـDB. Outbox Pattern للـasync events. PCI DSS compliance: بيانات البطاقة في vault منفصل. Retry مع exponential backoff.", senior: "Idempotency أهم مبدأ في payments—المستخدم قد يُعيد المحاولة، شبكة قد تنقطع، يجب ألا يُدفع مرتين." },
      { q: "اشرح تصميم Real-time Collaborative Editor مثل Google Docs.", a: "Approaches: Operational Transformation (OT)—قديم ومعقد. CRDT (Conflict-free Replicated Data Types)—حديث وأبسط. بالتفصيل: CRDT يُمثّل المستند كهيكل بيانات يدمج التغييرات تلقائياً. WebSocket للـreal-time updates. Presence: من يُعدّل الآن وأين cursor كل شخص. Persistence: كل عملية مُخزَّنة. Version history من الـapplied operations.", senior: "CRDT (Yjs، Automerge) أسهل تطبيقاً من OT وأكثر correctness—يستخدمها Notion، Linear، وغيرها." },
      { q: "كيف تُصمّم نظام Monitoring مثل Datadog؟", a: "مكونات: Metrics Collection (Agents)، Time-series DB (InfluxDB/Prometheus)، Visualization (Grafana)، Alerting، Log Aggregation. Metrics: Counter، Gauge، Histogram، Summary. Collection: pull (Prometheus) أو push (StatsD). Retention: high-res للـrecent، downsampled للـhistorical. Alerting rules بـPromQL. Correlation: metrics + logs + traces = observability pillars.", senior: "الثلاثة pillars: metrics (ماذا يحدث)، logs (لماذا)، traces (كيف)—لا تبنِ monitoring كامل بأحدها فقط." },
      { q: "اشرح الفرق بين Horizontal وVertical Scaling.", a: "Vertical Scaling (Scale Up): زيادة موارد الـserver الواحد (CPU، RAM). بسيط لكن محدود بالـhardware. لا تغيير في الكود. Horizontal Scaling (Scale Out): إضافة servers أكثر. يتطلب: stateless design، load balancer، distributed data. الـapplication يجب أن تكون stateless—الـstate في DB أو Cache خارجي. Auto Scaling: تلقائي بناءً على metrics.", senior: "صمّم stateless من اليوم الأول—أسهل من migration لاحقاً. الـsession في Redis لا في memory." },
      { q: "كيف تُصمّم نظام Chat مثل WhatsApp؟", a: "آلية الإرسال: Client → Server بـHTTP. التوصيل: WebSocket connection مستمر. Message storage: Cassandra (high write throughput، time-ordered). Routing: كل server يتتبع WebSocket connections. Distribution: Redis لمعرفة أي server يحمل connection المستخدم. Offline messages: مُخزَّنة حتى reconnect. End-to-end encryption: Signal Protocol. Group chats: fan-out من السيرفر.", senior: "WebSocket connections ثمينة—كل server يحمل 50K-100K connections. الـrouting بين servers عبر Redis pub/sub أو consistent hashing." },
      { q: "اشرح مفهوم Consistent Hashing وأين يُستخدم.", a: "Consistent Hashing: خوارزمية لتوزيع البيانات مع تأثير minimal عند إضافة أو حذف nodes. كل node وkey يُوضع على ring دائري. الـkey يذهب للـnode التالي في اتجاه عقارب الساعة. إضافة node: يأخذ بعض الـkeys من الـneighbor فقط. Virtual nodes: للتوزيع المتوازن. يُستخدم في: Memcached، Cassandra، Riak، CDNs، Load Balancers.", senior: "Virtual nodes (عادة 100-200 لكل node) تضمن التوزيع المتوازن حتى مع nodes بسعات مختلفة." },
      { q: "كيف تُصمّم نظام Booking مثل Airbnb؟", a: "التحدي الرئيسي: منع Double Booking. Approaches: 1) Pessimistic Locking—SELECT FOR UPDATE (بطيء للـhigh concurrency). 2) Optimistic Locking—version field. 3) Status machine: available → reserved → confirmed. Search: Elasticsearch لـavailability + filters. Calendar: بيانات الإتاحة بكفاءة. Distributed lock: لفترة Hold قصيرة. Saga: Booking → Payment → Confirmation.", senior: "Optimistic locking أفضل للـbooking—أغلب المستخدمين لا يواجهون conflicts. Pessimistic فقط للـhigh contention resources." },
      { q: "اشرح Service Mesh وفائدته.", a: "Service Mesh: طبقة infra تتولى: Traffic Management، Service Discovery، Load Balancing، Mutual TLS (mTLS)، Circuit Breaking، Observability. Sidecar proxy (Envoy) بجانب كل pod. Control Plane (Istio/Linkerd): يُوزّع الـconfiguration. فوائد: الـapplication code لا تهتم بـnetworking. Canary deployments سهلة. الـobservability تلقائية. Trade-off: تعقيد أكبر وlatency إضافي.", senior: "Service mesh قوي لكن ثقيل—لا تُضيفه قبل أن تحتاجه فعلاً (>10 microservices). ابدأ بـmutual TLS بالـAPI gateway." },
      { q: "كيف تُصمّم Content Delivery Network (CDN)؟", a: "مكونات: Origin Server، Edge Servers (PoPs)، DNS-based routing. كيف يعمل: المستخدم يُحاول الـEdge الأقرب جغرافياً. إذا cache miss: Edge يُحضر من Origin ويُخزّن. Cache invalidation: TTL أو purge API. Push vs Pull CDN: Push تُحمّل الملفات مسبقاً، Pull تُحضرها عند الطلب. Dynamic content: Edge computing (Cloudflare Workers). SSL termination على الـEdge.", senior: "CDN لا فقط للـstatic assets—استخدمها لـAPI responses مع cache-control headers الصحيحة." },
      { q: "اشرح Circuit Breaker Pattern.", a: "Circuit Breaker: يمنع cascade failures. States: Closed (طبيعي)، Open (يرفض requests مباشرة)، Half-Open (يجرب requests محدودة). Metrics: failure rate > threshold → Open. بعد timeout → Half-Open → اختبار. إذا نجح → Closed. إذا فشل → Open مجدداً. Fallback: قيمة cached، default value، graceful degradation. Libraries: Resilience4j، Hystrix (deprecated).", senior: "Circuit Breaker + Bulkhead + Retry مع exponential backoff = resilience pattern كامل لأي microservice." },
      { q: "كيف تُصمّم نظام Event Sourcing؟", a: "Event Sourcing: تُخزّن sequence من events بدل الـcurrent state. الـstate يُعاد بناؤه بتطبيق كل events. مزايا: audit log كامل، time travel، بناء read models متعددة. Snapshots: لتجنب replay طويل. CQRS: منفصل عادةً—Command Side يكتب Events، Query Side يقرأ Projections. Event store: EventStoreDB، Kafka، DynamoDB. إعادة بناء projections عند الحاجة.", senior: "Event Sourcing يُضيف تعقيداً كبيراً—ناسب للـdomains التي تحتاج audit trail حقيقي (banking، medical)." },
      { q: "اشرح كيف يعمل Two-Phase Commit وعيوبه.", a: "2PC: Phase 1 (Prepare)—Coordinator يسأل كل participant هل تستطيع commit؟ Phase 2 (Commit/Rollback)—إذا كلهم وافقوا يُرسل commit، وإلا rollback. المشاكل: Coordinator failure أثناء Phase 2 → participants ينتظرون. Blocking protocol. Single point of failure. Low performance لكثرة round trips. البديل: SAGA pattern أو Outbox pattern للـmicroservices.", senior: "2PC نادراً الحل الصحيح في microservices—SAGA أو eventual consistency أفضل في معظم الحالات." },
      { q: "كيف تُصمّم نظام لـمعالجة Time-Series Data؟", a: "Use cases: IoT sensors، financial data، monitoring metrics. Databases: InfluxDB، TimescaleDB (PostgreSQL extension)، Apache Druid، ClickHouse. Techniques: Data partitioning بـtime ranges. Compression (delta encoding، run-length). Downsampling: roll-up أقدم البيانات لـlower resolution. Retention policies تلقائية. Write patterns: high throughput، monotonically increasing timestamps.", senior: "TimescaleDB للبساطة (PostgreSQL-compatible)، ClickHouse للـanalytic queries السريعة جداً على البيانات الكبيرة." },
      { q: "اشرح Database Sharding Strategies.", a: "Horizontal Sharding: توزيع rows بين databases. Strategies: Hash Sharding (توزيع متوازن لكن صعب resharding)، Range Sharding (قابل للـrange queries لكن hot spots)، Directory-based (مرن لكن lookup overhead). Cross-shard queries: تجنّبها في التصميم. Resharding: consistent hashing يُقلل البيانات المُنقلة. Shard key: اختيار حرج يُحدد التوزيع.", senior: "اختر shard key الذي يُوزّع load بالتساوي ويسمح بـlocal queries—سهل التغيير لاحقاً مستحيل تقريباً." },
      { q: "كيف تُصمّم نظام Recommendation Engine؟", a: "Approaches: Collaborative Filtering (ما أعجب مستخدمين مشابهين)، Content-Based (ما يشبه ما أعجبك)، Hybrid. Collaborative: Matrix Factorization (SVD، ALS). Offline training: Spark MLlib. Online serving: precomputed recommendations + personalization. Cold Start: Content-based للمستخدمين الجدد. A/B testing للمقارنة. Feature store: precomputed features.", senior: "Two-stage pipeline (Recall + Ranking) الأكثر استخداماً—Recall يُقلص من M candidates لـK، Ranking يُرتّبهم." },
      { q: "اشرح مفهوم Bulkhead Pattern.", a: "Bulkhead: عزل موارد لمنع failure في جزء من تدمير الكل. مُستوحى من أقسام السفن المانعة للغرق. في البرمجيات: thread pools منفصلة لكل dependency. Connection pools منفصلة. Services يُعزَل استهلاكها للـresources. إذا خرّب service واحد thread pool—البقية تستمر. تطبيق: Hystrix Bulkhead، Resilience4j Bulkhead.", senior: "Bulkhead + Circuit Breaker معاً—Bulkhead يحدود الضرر، Circuit Breaker يمنع الاستمرار في المحاولة." },
      { q: "كيف تُصمّم نظام لـReal-time Analytics؟", a: "Lambda Architecture: Batch Layer (ثقيل ودقيق) + Speed Layer (سريع وتقريبي) + Serving Layer. Kappa Architecture: stream processing فقط (Kafka + Flink). Event-driven: events → Kafka → Flink/Spark Streaming → OLAP DB. ClickHouse أو Druid للـAPDR queries. Pre-aggregation للـcommon queries. Materialized views. Approximation algorithms: HyperLogLog للـunique counts.", senior: "Kappa أبسط من Lambda وكافٍ لمعظم الحالات—Lambda عندما تحتاج reprocessing historical data بشكل منتظم." },
      { q: "اشرح Leader Election في Distributed Systems.", a: "Algorithms: Bully Algorithm، Ring Algorithm. ZooKeeper: ephemeral nodes + watches. Raft: built-in leader election مع consensus. etcd: يستخدم Raft. Lease-based: leader يُجدّد lease دورياً. Split-brain problem: اثنان يعتقدان أنهما leaders. Fencing tokens: لمنع stale leader من الكتابة. Quorum: أغلبية يجب أن تتفق.", senior: "استخدم etcd أو ZooKeeper لـleader election بدل تطبيقها من الصفر—المشاكل الحافة دقيقة جداً." },
      { q: "كيف تُصمّم نظام Distributed Locking؟", a: "Redis Distributed Lock (Redlock): SETNX مع TTL. Redlock Algorithm: الكتابة على majority of Redis nodes. Lease-based: lock بـexpiry. Fencing token: رقم monotonically increasing مع كل lock. ZooKeeper لـstrong consistency. المشكلة: GC pause قد تُسبب lock expiry والـclient لا يزال يُنفّذ. Fencing يحل هذا.", senior: "Distributed locks صعبة صحتها—استخدمها بحذر. Optimistic concurrency (version fields) أفضل حين ممكن." },
      { q: "اشرح كيف تُصمّم نظام Logging في Scale.", a: "مكونات: Log Agents (Filebeat، Fluentd)، Message Queue (Kafka)، Log Aggregator (Logstash)، Storage (Elasticsearch، S3)، Visualization (Kibana). Structured logging: JSON بدل plain text. Correlation ID: لتتبع request خلال services. Log levels: DEBUG/INFO/WARN/ERROR. Sampling: logs 100% للـERROR، sample للـDEBUG. Cost management: tiered storage.", senior: "Structured logging من اليوم الأول—يُسهّل querying والـalerting. أضف correlation ID في كل خدمة." },
      { q: "كيف تُصمّم نظام يدعم Multi-tenancy؟", a: "Approaches: 1) Separate DB per tenant: أكثر isolation، أكثر تكلفة. 2) Separate Schema per tenant: توسط. 3) Shared Schema بـtenant_id column: أقل تكلفة، أصعب isolation. Row-level security (PostgreSQL) للأمان. Tenant routing: subdomain أو header. Data partitioning بـtenant_id. Configuration per tenant. Resource quotas. Data residency requirements.", senior: "ابدأ بـshared schema مع row-level security—سهل وكافٍ. ارتقِ لـseparate DB فقط للـenterprise clients الكبار." },
      { q: "اشرح CQRS Pattern وفائدته.", a: "CQRS (Command Query Responsibility Segregation): فصل Read وWrite models. Write Side: Commands تُغيّر State. Read Side: Queries تُعيد Views/Projections. يُتيح: تحسين كل جانب بشكل مستقل، DistReadModels مُحسَّنة للاستعلامات. Eventual Consistency بين Write وRead sides. مع Event Sourcing: Write side يكتب Events، Read side يقرأ Projections مبنية منها.", senior: "CQRS يُضيف تعقيداً—لا تستخدمه بدون EventSourcing إلا إذا كان لديك فعلياً performance problem مختلف للـread والـwrite." },
      { q: "كيف تُصمّم نظام File Synchronization مثل Dropbox؟", a: "Components: Client App، Sync Engine، Block Storage، Metadata Server. Block-level sync: الملف يُقسَّم لـchunks بـcontent hashing. Deduplication: نفس الـchunk يُخزَّن مرة. Delta sync: يُرسل فقط الـchunks المتغيّرة. Conflict resolution: last-write-wins أو copy مع suffix. Long polling أو WebSocket للـchange notifications. Client-side encryption اختيارياً.", senior: "Chunking بـcontent-based (SHA256) بدل fixed-size يُعطي deduplication أفضل عند تحريك بيانات داخل الملف." },
      { q: "اشرح Back of Envelope Estimation في System Design.", a: "أرقام مهمة: Disk seek: 10ms. SSD read: 0.1ms. RAM: 0.0001ms. Network: 150ms cross-continent. TCP: 10μs. تقديرات عامة: 1M users → ~100 RPS (1% active في نفس الوقت). 100M users → 1000 RPS. 1KB per request × 1000 RPS = 1MB/s. 86400 ثانية/يوم. 1TB = 10^12 bytes. قدّر ثم تحقق من جدوى الـdesign.", senior: "Back-of-envelope سريع يُجنّبك مشاريع ليست مجدية تقنياً. دائماً اسأل عن scale قبل الـdesign." },
      { q: "كيف تُصمّم نظام Typeahead/Autocomplete؟", a: "Data structure: Trie (بسيط، memory-intensive) أو Inverted Index. Precomputation: أكثر الـqueries بحثاً مُسبقاً. Ranking: popularity، personalization، recency. Update pipeline: batch أو real-time. Redis Sorted Set: query string كـmember، score كـpopularity. Caching: top suggestions لأكثر prefixes شيوعاً. Locality: مختلف حسب region.", senior: "بالنسبة للـscale: Redis sorted set للـcaching، بدل Trie في memory—أبسط وأسهل للـdistribution." },
      { q: "اشرح كيف تُصمّم نظام Proximity Service (Find Nearby).", a: "بيانات Location: latitude وlongitude. Algorithms: Geohash (يُحوّل 2D لـstring، hierarchical)، Quadtree (hierarchical spatial index)، H3 (hexagonal، Uber). Redis: GEOADD وGEOSEARCH. SQL: PostGIS extension. Query: دائرة → bounding box أولاً → تصفية الدائرة. Caching بـgeohash prefix. Update frequency: static (restaurants) vs dynamic (drivers).", senior: "Geohash مثالي للـstatic data (restaurants)—Redis GEOAPI مع search بدل Quadtree للـsimplicity." },
      { q: "ما هي أنماط Database Replication الشائعة؟", a: "Single-Leader: الكتابة على leader فقط، القراءة من followers. Async vs Sync replication. Multi-Leader: كتابة على أكثر من leader، conflict resolution. Leaderless (Dynamo-style): كتابة على quorum، قراءة من quorum. Replication lag: eventual consistency. Use cases: read replicas لـscale reads، standby للـfailover، geographic replication للـlow latency.", senior: "Async replication مع read replicas أكثر شيوعاً—قبول lag قليل لـread scalability كبير." },
      { q: "كيف تُصمّم نظام لـصور مثل Instagram؟", a: "Upload: Client → CDN Upload URL (presigned) → Object Storage. Processing pipeline: Queue → Resize/Format conversion → Multiple sizes. Metadata: PostgreSQL. Feed: fanout on write للـregular users. Discovery: Explore page بـrecommendation engine. Like/Comment: Cassandra للـhigh write throughput. Story: TTL-based deletion. CDN لكل الصور. Search: Elasticsearch.", senior: "Presigned upload URLs مباشرة لـS3/Storage بدل مرورها بـAPI server—يُوفر bandwidth ويُقلل latency." },
      { q: "اشرح مفهوم Idempotency وكيف تُطبّقه.", a: "Idempotency: نفس الـrequest مرات متعددة = نفس النتيجة. Idempotency Key: client يُولّد UUID لكل operation. Server يُخزّن (key, result) في DB. قبل المعالجة: تحقق من الـkey. إذا موجود: أعد الـresult. إذا جديد: نفّذ واحفظ. TTL على الـkeys. اختر storage مناسب: Redis للـshort-lived، DB للـlong-lived.", senior: "Idempotency ضروري لكل API يُعدّل بيانات—client يُعيد المحاولة عند timeout بدون خوف من duplication." },
      { q: "كيف تُصمّم نظام Ticketing مثل Ticketmaster؟", a: "تحدي: flash sales مع ملايين يتنافسون على مقاعد محدودة. الحل: 1) Waiting Queue قبل دخول الـsale. 2) Ticket Reservation بـshort TTL (10 دقائق). 3) Seat locking أثناء checkout. 4) Redis للـin-memory seat availability. 5) Virtual Waiting Room لإدارة الـload. 6) Atomic operations: SETNX في Redis للـclaiming seats. 7) Rollback seats عند timeout.", senior: "Virtual waiting room أهم piece—يُحوّل spike إلى تدفق خاضع للسيطرة ويمنع server crashes." },
      { q: "اشرح High Availability Patterns.", a: "Active-Active: كل instances تستقبل traffic. Active-Passive: standby يأخذ over عند failure. Geographic redundancy: multiple regions. Load balancing: توزيع traffic. Health checks: فحص دوري، failover تلقائي. Chaos Engineering: اختبار الـfailure proactively. SLA calculations: 99.9% = 8.7 hrs/year downtime. 99.99% = 52 mins/year. Dependency on external services يُخفّض SLA.", senior: "99.99% availability تحتاج: no single point of failure، automated failover، regular DR drills. حسب SLA من كل layer." },
      { q: "كيف تُصمّم نظام Analytics Pipeline؟", a: "مكونات: Event Collection (SDK)، Stream Processing (Kafka + Flink)، Batch Processing (Spark)، Data Warehouse (BigQuery، Snowflake)، Visualization (Looker، Tableau). Event schema: JSON مع versioning. Schema Registry: Avro + Confluent Registry. Data quality: validation pipeline. Partitioning في DW بـdate للـquery performance. Materialized views للـdashboards.", senior: "Schema Registry منع مشاكل الـbreaking changes في events—أضفه من البداية قبل أن تعاني من schema drift." },
      { q: "اشرح مفهوم Write-Ahead Log (WAL).", a: "WAL: كل تغيير يُكتب في log أولاً قبل الـactual data write. يضمن: Atomicity وDurability حتى مع crash. Database Recovery: يُعيد تطبيق الـWAL operations. Change Data Capture (CDC): قراءة الـWAL لـreplication. PostgreSQL WAL يُستخدم مع Debezium لـCDC. Kafka ورا الكواليس هو log أيضاً. Log-Structured storage: LSM trees تُبني على فكرة مشابهة.", senior: "CDC من WAL أفضل من dual-writes للـsync بين Primary DB وElasticsearch/Cache—eventual consistency بدون code changes." },
      { q: "كيف تُصمّم نظام Leaderboard في Real-time؟", a: "Redis Sorted Set: ZADD لإضافة/تحديث، ZREVRANK للترتيب، ZREVRANGE للـtop-N. ثوانٍ لكل query. Windowed leaderboards: daily/weekly/monthly بـsorted set منفصل مع timestamp. Global vs Regional: sorted sets منفصلة. Persistence: backup Redis لـDisk دورياً. Cross-region: replication مع eventual consistency. Anti-cheat: server-side score validation.", senior: "Redis Sorted Set هو الأداة المثالية للـleaderboards—O(log N) لكل operation. لا تحاول تطبيقها بـSQL." },
      { q: "اشرح Database Index Types وcحالات استخدامها.", a: "B-Tree Index: مناسب للـrange queries وequality. Hash Index: equality فقط، أسرع من B-Tree. GiST/GIN (PostgreSQL): للـfull-text، geometric، array types. Partial Index: يُقلّص حجم الـindex بـWHERE clause. Composite Index: يُقدم الأعمدة الأكثر selective أولاً. Covering Index: يشمل كل الأعمدة المطلوبة. Functional Index: على نتيجة دالة.", senior: "أضف EXPLAIN ANALYZE قبل كل index—الـplanner قد يختار غيره. Index overhead على الكتابة حقيقي." },
      { q: "كيف تُصمّم نظام لـText Search?", a: "Inverted Index: كلمة → قائمة docs. Building: Tokenization، Stemming، Stop words، Normalization. Scoring: TF-IDF أو BM25. Elasticsearch architecture: Lucene underneath، sharding، replication. Alternatives: PostgreSQL Full-Text Search (للـsmaller scale)، Typesense، Meilisearch (simpler). Synonyms dictionary. Fuzzy matching للأخطاء الإملائية. Highlighting.", senior: "Elasticsearch الأقوى لكن المعقد—جرب Typesense أو Meilisearch للـsmall-medium scale قبل Elasticsearch." },
      { q: "اشرح Zero-Downtime Deployment Strategies.", a: "Blue-Green: بيئتان متطابقتان، تبديل فوري في الـload balancer. Canary: إطلاق تدريجي لـ% من الـtraffic. Rolling Update: تحديث instance واحد في كل مرة. Feature Flags: تحكم في الـfeatures بدون deploy جديد. DB migrations forward-compatible: additive فقط في الـdeploy. Smoke tests بعد deploy. Rollback plan واضح.", senior: "Blue-Green أبسط وأسرع للـrollback. Canary للـfeatures الخطرة مع monitoring دقيق للـerror rate." },
      { q: "كيف تُصمّم نظام Queue للـBackground Jobs؟", a: "Job Queue: Redis (BullMQ، Sidekiq)، RabbitMQ، Amazon SQS. Worker pools: horizontal scaling. Job retries مع exponential backoff. Dead Letter Queue للـfailed jobs. Idempotency: كل job قابل للتكرار. Job scheduling: Cron-like. Priority queues للـurgent jobs. Visibility timeout: SQS model. Monitoring: jobs pending، processing time، failure rate.", senior: "BullMQ (Redis-based) للـNode.js الأفضل للـfeature set والـperformance. اعتمد على DLQ ومراقبه باستمرار." },
      { q: "اشرح مفهوم CRDT وتطبيقاته.", a: "CRDT (Conflict-free Replicated Data Type): هياكل بيانات تدمج تلقائياً بدون conflicts. Types: State-based (CvRDT)—تُرسل كل الـstate. Operation-based (CmRDT)—تُرسل operations فقط. Examples: G-Counter (only increment)، PN-Counter، LWW-Register، OR-Set. Yjs وAutomerge: CRDTs للـCollaborative Editing. تستخدم في: Figma، Notion، Linear.", senior: "CRDT تضمن eventual consistency بدون conflict resolution code—مثالية للـoffline-first وcollaborative apps." },
      { q: "كيف تختار قاعدة البيانات المناسبة لـuse case معين؟", a: "SQL (PostgreSQL): ACID، relations، complex queries، strong consistency. MongoDB: flexible schema، document model، horizontal sharding. Cassandra: high write throughput، wide column، no joins. Redis: in-memory، speed، data structures. Elasticsearch: full-text search، analytics. ClickHouse: OLAP، analytical queries. Neo4j: graph relationships. S3: object storage.", senior: "لا توجد قاعدة بيانات 'أفضل'—PostgreSQL مع Extensions (PostGIS، pg_vector) يُغطي 80% من الحالات." },
      { q: "اشرح مفهوم Chaos Engineering.", a: "Chaos Engineering: اختبار صمود النظام بإدخال failures متعمدة في production أو pre-prod. Chaos Monkey: يقتل random instances. Chaos Gorilla: يُعطّل كامل availability zone. GameDays: محاكاة outages. Principles: ابنِ hypothesis، تحقق في production، ابدأ صغيراً. Netflix SRE pioneer هذا. Gremlin وChaos Toolkit أدوات شائعة. Pre-conditions: observability كامل أولاً.", senior: "Chaos Engineering بدون observability تخريب—ابنِ monitoring وalerting كاملاً قبل أي chaos experiment." },
      { q: "كيف تُصمّم نظام API Versioning؟", a: "Strategies: URL Versioning (/v1/، /v2/)—الأوضح. Header Versioning (API-Version: 2)—أنظف URLs. Query Parameter (?version=2). Content Negotiation (Accept: application/vnd.api.v2+json). Deprecation: sunset header، warning logs، migration guide. Semver للـchanges: breaking changes → major version. Backward compatibility: إضافة fields مقبولة، حذف field breaking.", senior: "URL versioning الأبسط والأوضح للـpublic APIs—الـdiscoverability والـcaching أسهل. Header versioning للـinternal APIs." },
      { q: "اشرح Security Considerations في System Design.", a: "Authentication: JWT أو Session + Cookie (httpOnly، secure، SameSite). Authorization: RBAC أو ABAC. Encryption: TLS في الـtransit، AES-256 للـat-rest. Secrets: Vault أو KMS، لا في environment variables مباشرة. Input validation: كل input من خارج النظام. Rate Limiting لمنع abuse. SQL Injection: parameterized queries. CORS: strict origin list.", senior: "Security by design—أضف auth وencryption في الـarchitecture phase. إضافتها لاحقاً أصعب وأغلى." },
      { q: "كيف تُصمّم نظام لـGlobal Scale؟", a: "Multi-Region Deployment: نُسَخ كاملة في regions متعددة. Data Residency: بيانات معينة تبقى في region بعينها. Active-Active: كل region تخدم وتكتب. Active-Passive: region واحدة primary. Latency: route المستخدم للـregion الأقرب. Data replication: async بين regions. Conflict resolution للـactive-active writes. Global Load Balancing: Anycast، GeoDNS.", senior: "ابدأ بـsingle region مُتاحة (multi-AZ). انتقل لـmulti-region فقط عند الحاجة الفعلية للـlatency أو compliance." }
    ]
  },
  {
    id: "arch", label: "Architecture", icon: "ti-building-arch", color: "#10b981",
    questions: [
      { q: "ما الفرق بين Microservices وMonolith وكيف تختار؟", a: "Monolith: كل الكود في تطبيق واحد—بسيط في البداية، صعب التوسع عند الكبر. Microservices: services صغيرة مستقلة—تعقيد عملياتي أكبر، مرونة أكثر. Modular Monolith: أفضل بداية—حدود واضحة داخل monolith. SOA: services أكبر من microservices. اختر Microservices حين: teams متعددة مستقلة، scale مختلف لأجزاء مختلفة، tech stack متعدد.", senior: "ابدأ بـmonolith جيد التصميم. هاجر لـmicroservices حين تعرف حدود الـdomains بيقين—لا قبل ذلك." },
      { q: "اشرح Domain-Driven Design وأهم مفاهيمه.", a: "DDD: نمذجة البرنامج بناءً على domain knowledge. Ubiquitous Language: مصطلحات مشتركة بين developers والخبراء. Bounded Context: حدود واضحة لـmodel. Aggregate: cluster من entities يُعامَل كوحدة واحدة. Aggregate Root: نقطة الدخول الوحيدة للـaggregate. Domain Events: أحداث مهمة في الـdomain. Repository: abstraction للـdata access. Value Objects: بلا هوية، تُعرَّف بقيمتها.", senior: "ابدأ بـEvent Storming session مع domain experts لرسم الـdomains وتحديد الـbounded contexts قبل الكود." },
      { q: "اشرح Clean Architecture وطبقاتها.", a: "Clean Architecture (Uncle Bob): Entities (business rules)، Use Cases (application rules)، Interface Adapters (controllers, presenters)، Frameworks & Drivers (DB, UI). Dependency Rule: الاعتماديات تتجه للداخل دائماً. الـEntities لا تعرف الـDB. الـUse Cases لا تعرف الـWeb framework. Dependency Inversion: interfaces تُمرَّر للداخل. Infrastructure تُنفّذ الـinterfaces.", senior: "Clean Architecture مفيد للـcomplexity الحقيقية—في apps بسيطة يُضيف تعقيداً غير مبرر. حكم على complexity المشروع أولاً." },
      { q: "ما هو الفرق بين Orchestration وChoreography في Microservices؟", a: "Orchestration: service مركزي يُدير الـworkflow ويستدعي services الأخرى (مثل SAGA orchestrator). Choreography: كل service تُطلق events وتستجيب للـevents من services أخرى—لا مركز. Orchestration: أوضح للـflow، أسهل في debugging، SPOF محتمل. Choreography: مرن، كل service مستقلة، أصعب في تتبع الـflow.", senior: "ابدأ بـChoreography للـsimple workflows. استخدم Orchestration عندما يصبح الـflow معقداً وتحتاج visibility كاملة." },
      { q: "اشرح SOLID Principles مع أمثلة عملية.", a: "Single Responsibility: كل class/module مسؤولية واحدة. Open/Closed: مفتوح للتوسع، مغلق للتعديل. Liskov Substitution: subtype قابل للاستبدال بـparent بدون تغيير. Interface Segregation: interfaces صغيرة محددة بدل كبيرة عامة. Dependency Inversion: depend on abstractions لا على implementations. SOLID تُقلل coupling وتزيد cohesion وتُسهّل testing.", senior: "SOLID ليست قواعد صارمة—هي guidelines. طبّقها حين تُضيف قيمة. Over-engineering بـSOLD أسوأ من عدم تطبيقها." },
      { q: "ما هي أنماط الـHexagonal Architecture؟", a: "Hexagonal (Ports & Adapters): تعزل business logic عن الـinfrastructure. Ports: interfaces يُعرّفها الـdomain (inbound وoutbound). Adapters: implementations خارجية (REST، DB، Queue). تبديل الـDB لا يؤثر على الـbusiness logic. Testing: مُوصِّلات وهمية للـports. Primary Ports: يُستدعى من خارج (use cases). Secondary Ports: يُستدعى من الـdomain (للـDB مثلاً).", senior: "Ports & Adapters تجعل الـbusiness logic مستقلة تماماً—كل adapter قابل للاستبدال والـtest بشكل منفصل." },
      { q: "اشرح Event-Driven Architecture وفوائدها.", a: "EDA: components تتواصل عبر events بدل direct calls. Components: Event Producer، Event Bus (Kafka/EventBridge)، Event Consumer. Decoupling: Producer لا يعرف الـConsumers. Scalability: Consumers مستقلون في الـscaling. Audit Trail: كل event مُخزَّن. Replay: إعادة معالجة events. Patterns: Pub/Sub، Event Streaming، Event Sourcing. Trade-off: eventual consistency وصعوبة debugging.", senior: "EDA تُبدع في الـintegration بين teams—لكن احذر من الـevent spaghetti حيث لا أحد يعرف من يُطلق ماذا." },
      { q: "كيف تُطبّق Repository Pattern بشكل صحيح؟", a: "Repository: يُخفي تفاصيل الـdata access خلف interface. Interface: يُعرَّف في الـdomain layer. Implementation: في الـinfrastructure layer. يُتيح: تبديل الـDB، testing بـfake repos. لا تُعيد query builders—أعد domain objects. Specification Pattern: encapsulate query criteria. Unit of Work: يُدير transactions عبر repositories متعددة.", senior: "Repository يجب أن يتحدث بـdomain language لا SQL—findActiveUsersByCity() لا where('status', 'active')." },
      { q: "اشرح Strangler Fig Pattern للـMigration.", a: "Strangler Fig: هجرة تدريجية من Monolith لـMicroservices. خطوات: 1) حدد feature للهجرة. 2) بنِ microservice جديد. 3) Routing: وجّه traffic الـfeature للـmicroservice الجديد. 4) أزل الكود القديم. 5) كرّر. Façade في الأمام: يُوزّع بين القديم والجديد. لا قطع كامل. Feature Flags للتحكم. الـDB آخر ما يُهاجر.", senior: "Strangler Fig الأسلم للـmigration—يُتيح rollback سريع وvalidation فعلي في production." },
      { q: "ما هي أنماط الـAPI Design الجيدة؟", a: "REST: resources كـnouns، HTTP verbs، stateless، versioning. Naming: plural nouns، lowercase، hyphens. Error responses: HTTP codes صحيحة + body مُفصَّل. Pagination: cursor-based أفضل من offset للـlarge datasets. Filtering/Sorting في query params. HATEOAS: links في responses. Rate limiting headers. Idempotency. gRPC: للـinternal services للـperformance.", senior: "اتفق على API conventions أولاً واكتبها في CONTRIBUTING.md—inconsistency في الـAPI أكثر ما يُقلق الـconsumers." },
      { q: "اشرح Twelve-Factor App Methodology.", a: "1) Codebase: repo واحد. 2) Dependencies: عزلها. 3) Config: في البيئة لا الكود. 4) Backing services: تعامل كـattached resources. 5) Build/Release/Run: مراحل منفصلة. 6) Processes: stateless. 7) Port binding: self-contained. 8) Concurrency: scale بالـprocesses. 9) Disposability: بدء سريع، shutdown graceful. 10) Dev/Prod parity. 11) Logs كـevent streams. 12) Admin tasks كـone-off processes.", senior: "12-factor مبادئ أساسية للـcloud-native—الـconfig في البيئة ليس في الكود مبدأ لا يُكسر." },
      { q: "كيف تُصمّم نظام لـGraceful Degradation؟", a: "Graceful Degradation: النظام يستمر بوظائف مُقلّصة عند failure. Strategies: Feature Flags (تعطيل features ثقيلة). Fallback responses (cached أو default). Circuit Breaker (تجاوز dependency معطوبة). Read-only mode عند DB write failure. Static content عند backend failure. Priority queuing: critical requests أولاً. Bulkhead: عزل failures.", senior: "حدد مسبقاً: ما الـfeatures التي يمكن تعطيلها وما الـcore التي يجب أن تعمل دائماً. Design for degradation." },
      { q: "اشرح API Gateway vs Service Mesh.", a: "API Gateway: للـexternal traffic—authentication، rate limiting، SSL termination، request routing. Service Mesh: للـinternal service-to-service traffic—mTLS، load balancing، observability، circuit breaking. يتكاملان: API Gateway للـingress، Service Mesh للـinternal. API Gateway (Kong، AWS API GW). Service Mesh (Istio، Linkerd). API Gateway لا يُغني عن Service Mesh في microservices كبيرة.", senior: "ابدأ بـAPI Gateway وحده—أضف Service Mesh فقط حين يصبح الـinternal service security وobservability مشكلة فعلية." },
      { q: "ما هي أنماط Data Management في Microservices؟", a: "Database per Service: كل service DB منفصلة—الأقوى للـautonomy. Shared Database: أبسط لكن coupling. API Composition: اجمع البيانات في service أو BFF. CQRS: read model منفصل. Saga: distributed transactions. Event Sourcing: single source of truth كـevents. Data replication عبر events. الـconsistency دائماً eventual في microservices.", senior: "Database per service يعني: لا foreign keys بين services، لا JOIN بين DBs. تحتاج API composition أو event-driven sync." },
      { q: "اشرح مفهوم Bounded Context في DDD.", a: "Bounded Context: حدود صريحة تُعرِّف أين model معين صالح. داخل context واحد: Ubiquitous Language محددة. بين contexts: Context Mapping (translation). Patterns: Shared Kernel، Customer/Supplier، Conformist، Anti-Corruption Layer، Open Host Service، Published Language. كل Microservice يجب أن يتوافق مع Bounded Context.", senior: "Anti-Corruption Layer يحمي domain model من concepts الـlegacy system أو الـexternal service—لا تُدخل مفاهيمها مباشرة." },
      { q: "كيف تُطبّق Observability في Microservices؟", a: "ثلاثة أعمدة: Metrics (Prometheus/Grafana)، Logs (ELK stack، structured JSON)، Traces (Jaeger، Zipkin، OpenTelemetry). Correlation ID: يتتبع request خلال services. Distributed Tracing: رسم خريطة الـrequest journey. SLIs (Indicators) وSLOs (Objectives) وSLAs (Agreements). Error Budget: وقت الـacceptable downtime. Alerting: على SLO burn rate لا raw metrics.", senior: "OpenTelemetry الأساس الحديث—instrumentation مرة واحدة، تُرسل لأي backend. أضفه من البداية." },
      { q: "اشرح Feature Flags Architecture.", a: "Feature Flags: تحكم في الـfeatures وقت runtime بدون deploy. Types: Release Flags، Experiment Flags، Ops Flags، Permission Flags. Storage: DB أو config service. Evaluation: server-side (آمن) أو client-side (أسرع). Targeting: by user، cohort، region. Kill Switch: تعطيل فوري لـfeature معطوبة. Services: LaunchDarkly، Unleash، Flagsmith. Clean up flags بعد completion.", senior: "Flag debt أخطر من technical debt—لكل flag عمر محدد ومالك مسؤول. امسح الـflags القديمة بجدية." },
      { q: "ما هو Anti-Corruption Layer وكيف يُطبّق؟", a: "ACL: طبقة ترجمة تحمي الـdomain model من مفاهيم النظام الخارجي أو الـlegacy. يُحوّل: مفاهيم الـexternal system لـdomain model الداخلي. يمنع: تسرب concepts خارجية للـdomain. Facade: يُخفي API الخارجي. Translator: يُحوّل الـdata structures. Adapter: يُكيّف الـinterface. مفيد جداً عند التكامل مع legacy systems أو third-party APIs.", senior: "ACL يكلّف وقتاً في البداية لكن يُنقذك من الـcoupling العميق بالخارج—يُسهّل التغيير لاحقاً." },
      { q: "اشرح Sidecar Pattern في Architecture.", a: "Sidecar: container مرافق يُضيف وظائف للـmain container. وظائف شائعة: logging، monitoring، proxy، config، security. فوائد: separation of concerns، يمكن reuse عبر services مختلفة بـtech stacks مختلفة. Service Mesh يستخدم Sidecar (Envoy proxy). مثال: Envoy يتولى الـmTLS والـtracing بينما الـapp لا تعلم شيئاً.", senior: "Sidecar pattern أساس Service Mesh—الـapp تبقى بسيطة بينما الـinfrastructure concerns تُدار خارجها." },
      { q: "كيف تُصمّم نظام للـBlue-Green Deployment؟", a: "Blue-Green: بيئتان متطابقتان—Blue (live)، Green (idle). Deploy على Green، اختبر، حوّل الـtraffic بـLoad Balancer. Rollback: حوّل الـtraffic للـBlue فوراً. DB migrations: forward-compatible لأن كلا الـversions تتشارك الـDB. Canary: تدريجي—يُمرر % صغير لـGreen أولاً. Feature Flags مع Blue-Green. DNS TTL: اخفضه قبل الـswitch.", senior: "DB schema changes هي الـchallenge—استخدم expand-contract pattern: add column أولاً، migrate data، remove old column." },
      { q: "ما هي أنماط Resilience في Architecture؟", a: "Retry مع exponential backoff وjitter. Circuit Breaker: توقف عن المحاولة مؤقتاً. Bulkhead: عزل resources. Timeout: لا تنتظر إلى الأبد. Fallback: قيمة بديلة عند الفشل. Rate Limiting: حماية الـdownstream. Idempotency: retry آمن. Deadline Propagation: timeout يُوزَّع عبر services. Health Checks: فحص دوري للـdependencies.", senior: "Resilience مجموعة patterns متكاملة—Circuit Breaker + Retry + Timeout + Fallback معاً تُعطي نظاماً متيناً فعلاً." },
      { q: "اشرح Configuration Management في Microservices.", a: "Config Sources: Environment Variables (12-factor)، Config Files، Config Service (Consul، Nacos، AWS AppConfig). Secrets Management: Vault، AWS Secrets Manager، Azure Key Vault. Hot Reload: تحديث config بدون restart. Environment-specific config: dev/staging/prod. Feature Flags: نوع من الـconfig. Schema validation للـconfig. Audit log للـconfig changes.", senior: "لا secrets في environment variables مباشرة—استخدم Vault أو Secrets Manager مع automatic rotation." },
      { q: "كيف تُطبّق Domain Events في Microservices؟", a: "Domain Events: أحداث مهمة في الـbusiness domain (OrderPlaced, PaymentFailed). تُطلق من الـdomain model بعد state change. Outbox Pattern: تُكتب في نفس الـDB transaction مع الـstate change ثم تُرسل async. Event Schema: versioning وbackward compatibility. Consumer: Idempotent دائماً. Dead Letter Queue للـfailed events. Schema Registry لـvalidation.", senior: "Domain events اسمها بـpast tense (Placed لا Place)—حدث فعلاً، الآخرون يُخطَرون لا يُسألون." },
      { q: "اشرح مفهوم Conway's Law وتأثيره.", a: "Conway's Law: هيكل النظام يعكس هيكل الـcommunication بين الفرق التي بنته. إذا team واحدة بنت الـsystem—سيكون monolith. إذا teams متعددة—سيكون مُقسَّماً على حدود الـteams. Inverse Conway Maneuver: صمّم الـteams لتُنتج الـarchitecture المطلوبة. Microservices team independence: كل team تمتلك service كاملة من DB لـdeployment.", senior: "هيكل فرقك قبل architecture—اجعل team boundaries تتوافق مع domain boundaries وستحصل على architecture صحيح تلقائياً." },
      { q: "ما هي أنماط Messaging في Distributed Systems؟", a: "Point-to-Point: queue، consumer واحد يُعالج. Publish-Subscribe: topic، consumers متعددون. Request-Reply: async RPC. Competing Consumers: صراع على queue لـscaling. Message Routing: بناءً على content. Dead Letter Queue. Retry Policies. Idempotent Consumers. Saga عبر messaging. دوام الـmessage: at-least-once، at-most-once، exactly-once (نادر).", senior: "Exactly-once delivery مستحيل في الواقع بدون overhead ضخم—صمّم consumers ليكونوا idempotent بدلاً." },
      { q: "اشرح GraphQL Federation Architecture.", a: "GraphQL Federation: Supergraph يجمع Subgraphs. كل service تمتلك subgraph لـdomain محددة. Apollo Gateway يُوحّد الـgraph. @key directive لـentity references عبر subgraphs. @external وrequires للـcross-service fields. الـfrontend يرى schema موحد. Schema composition تلقائية. يُحل مشكلة BFF proliferation. مفيد للـteams مستقلة.", senior: "Federation تُعقّد infrastructure—ابدأ بـsingle graph وانتقل للـfederation حين يصبح الـcoordination على schema عائقاً." },
      { q: "كيف تُطبّق Testability في Architecture؟", a: "Testable Architecture: الـdomain logic مُعزولة، لا dependencies مباشرة على الـinfrastructure. Hexagonal Architecture تُتيح ذلك. Test Pyramid: unit (كثير، سريع)، integration (أقل)، E2E (قليل، بطيء). Fakes بدل mocks للـcomplex dependencies. Dependency Injection للـtestability. Test fixtures عبر factories. Test-driven domain logic.", senior: "إذا كان الكود صعب الاختبار—هذا مؤشر architectural smell. Testability ودائماً تعني clean boundaries." },
      { q: "اشرح Backend for Frontend (BFF) Pattern.", a: "BFF: backend مُخصَّص لكل frontend client. مثال: BFF للـmobile يُعيد data مُضغوطة، BFF للـweb يُعيد أكثر. يُحل: over-fetching وunder-fetching. يُخفي: تعقيد الـbackend services عن الـfrontend. Teams: frontend team تمتلك BFF الخاص بها. Trade-off: duplication بين BFFs. GraphQL كبديل موحّد.", senior: "BFF مثالي حين الـmobile وweb clients مختلفان جداً—لكن مع GraphQL يمكن تجنبه بـfield selection." },
      { q: "ما هي أنماط الـSecurity في Architecture؟", a: "Zero Trust: لا ثقة ضمنية بأي request. mTLS: authentication mutual بين services. Defense in Depth: طبقات أمان متعددة. Principle of Least Privilege: أقل صلاحيات ضرورية. RBAC/ABAC: authorization. API Security: authentication، rate limiting، input validation. Secret Rotation: تلقائية. Audit Logging: كل action مُسجَّل. Security Scanning: في CI/CD.", senior: "Security بالـdesign أرخص بكثير من security بعد الحادثة—أضفها كـrequirement وظيفي لا فكرة لاحقة." },
      { q: "اشرح Event-Driven Microservices وأنماط الـChoreography.", a: "Choreography: كل service تُعرِّف events تُطلقها وتستجيب لـevents من services أخرى. مثال: OrderService يُطلق OrderPlaced. InventoryService يستمع ويُطلق InventoryReserved. PaymentService يستمع ويُطلق PaymentProcessed. ShippingService يستمع ويُشحن. كل service مستقلة تماماً. Challenge: صعوبة تتبع الـflow الكامل. Saga Choreography لـdistributed transactions.", senior: "وثّق choreography flows مرئياً (event storming map)—بدون documentation يصبح noodleware غير مفهوم." },
      { q: "كيف تُصمّم Architecture لـHigh Write Throughput؟", a: "Techniques: Write-ahead log. LSM Tree (LevelDB، RocksDB، Cassandra). Batch writes. Async writes مع queue. Partitioning للـwrite distribution. In-memory writes (Redis) + async persistence. CQRS للفصل بين write path وread path. Kafka كـwrite buffer. Sharding بـwrite-optimized key. Pre-aggregation بدل real-time aggregation.", senior: "Kafka كـwrite buffer ثم processing بـFlink أو Spark الـpattern الأكثر شيوعاً لـhigh throughput write pipelines." },
      { q: "اشرح موازنة بين Latency وThroughput وConsistency.", a: "CAP والـtriangle الحقيقي: Latency-Consistency-Availability. تحسين Latency: caching، pre-computation، edge deployment. تحسين Throughput: batching، parallelism، async processing. Consistency: قيد يُقلل الـthroughput والـavailability. Strong consistency: linearizability—أبطأ وأقل توفراً. Eventual consistency: أسرع وأعلى availability. اختر بناءً على business requirements لكل operation.", senior: "لا تقبل 'نريد الثلاثة كاملة'—ساعد الـstakeholders على فهم trade-offs بأمثلة ملموسة من منتجهم." },
      { q: "ما هي أنماط Error Handling في Distributed Systems؟", a: "Fail Fast: اكشف وأبلغ عن الخطأ بسرعة. Let It Crash: restart آمن بدل error recovery معقد. Dead Letter Queue: للـmessages التي فشلت مراراً. Compensating Transactions: تراجع عن عمليات في Saga فاشلة. Error Classification: transient (retry) vs permanent (DLQ). Structured Error Responses: error code، message، correlation ID، timestamp.", senior: "Compensating transactions يجب أن تكون idempotent أيضاً—قد تُطلَق أكثر من مرة في حالات معقدة." },
      { q: "اشرح Versioning Strategies للـEvent Schemas.", a: "Backward Compatible Changes: إضافة fields اختيارية. Breaking Changes: تجنّبها أو version جديد. Strategies: Schema Registry (Confluent) مع Avro/Protobuf. Versioning field في الـevent. Multiple consumers: القديم والجديد يعملان معاً. Consumer-Driven Contract Testing (Pact) للتحقق من توافق الـschemas. Sunset old versions بعد migration.", senior: "Schema Registry مع compatibility checks في CI منع breaking changes وصلت لـproduction—لا تعمل بدونه في الأنظمة الكبيرة." },
      { q: "كيف تُطبّق Caching Strategy في Architecture؟", a: "Strategies: Cache-Aside (application تُدير الـcache)، Write-Through (كتابة للـcache والـDB معاً)، Write-Back (كتابة للـcache ثم async للـDB)، Read-Through (cache كـproxy). Cache Levels: L1 (in-process)، L2 (shared: Redis)، L3 (CDN). Cache Invalidation: TTL، event-based، explicit. Cache Stampede: jitter، mutex، probabilistic expiration.", senior: "Cache-Aside الأبسط والأكثر شيوعاً—لكن تحتاج الـapplication لإدارة الـinvalidation بعناية." },
      { q: "اشرح مفهوم Technical Debt وكيف تُديره.", a: "Technical Debt: تكلفة مستقبلية للقرارات السريعة اليوم. أنواع: Deliberate (مع وعي)، Inadvertent (بدون وعي). قياسه: code complexity، test coverage، duplication. إدارته: Tech Debt Backlog صريح. 20% من sprint للـdebt. Boy Scout Rule: اترك الكود أنظف مما وجدته. Refactoring فقط مع tests. ADR (Architecture Decision Records) لتوثيق القرارات.", senior: "Tech Debt طبيعي وأحياناً صحيح—المشكلة حين يتراكم بصمت. اجعله مرئياً وادرجه في الـplanning." },
      { q: "ما هو Command Pattern وكيف يرتبط بـCQRS؟", a: "Command Pattern: encapsulate request كـobject—يُمكّن قائمة انتظار، undo/redo، logging. CQRS يُطبّق هذا على مستوى الـarchitecture: Commands (write) وQueries (read) في handlers منفصلة. Command Handler: يُنفّذ business logic ويُرسل domain events. Query Handler: يقرأ من read model مُحسَّن. Mediator pattern (MediatR) يُوحّد الـdispatching.", senior: "CQRS بدون Event Sourcing أبسط—فقط write model وread model منفصلان. لا تُكرّه الاثنين معاً دائماً." },
      { q: "اشرح أهمية Architecture Decision Records (ADR).", a: "ADR: وثيقة قصيرة تسجّل قرار architectural. العناصر: Title، Context، Decision، Rationale، Consequences. يُجيب على 'لماذا' قُرر هذا وليس فقط 'ماذا'. يمنع إعادة نفس النقاشات. يُساعد الأعضاء الجدد. مُخزَّن في الـrepo مع الكود. Tools: adr-tools، MADR format. Review قديم ADRs دورياً—قد يتغير الـcontext.", senior: "ADRs من أفضل الاستثمارات للـteams الكبيرة—'لماذا' أهم من 'ماذا'، والذاكرة المؤسسية تضيع بدون توثيق." },
      { q: "كيف تُقيم Architecture Quality؟", a: "Quality Attributes: Scalability، Availability، Maintainability، Security، Performance، Testability، Deployability. ATAM (Architecture Tradeoff Analysis Method): تحليل منهجي للـtradeoffs. Fitness Functions: automated checks لـarchitecture compliance (ArchUnit). Module coupling وcohesion metrics. Dependency analysis. Test coverage. Change failure rate وlead time للـdeployment.", senior: "Fitness Functions في CI تحكم الـarchitecture باستمرار—تمنع drift تدريجي نحو Big Ball of Mud." },
      { q: "اشرح كيف تتعامل مع Legacy Systems في Architecture.", a: "Strategies: Big Bang Rewrite (خطر)، Strangler Fig (آمن تدريجي)، Modular Modernization (تقسيم الـmonolith)، Wrap & Extend (API layer فوق legacy). Anti-Corruption Layer للعزل. Understand before change: document الـbehavior الحالي بـcharacterization tests. Feature Parity: لا تُطلق حتى تُوازي Legacy. Data Migration: الأصعب—migrate بـdual write ثم cut-over.", senior: "لا تعِد بـrewrite كامل في sprint واحد—Strangler Fig بجدول زمني واقعي أفضل من Big Bang يفشل." },
      { q: "ما هو الفرق بين High Cohesion وLow Coupling؟", a: "High Cohesion: عناصر الـmodule مترابطة وظيفياً—module يعمل شيئاً واحداً بشكل كامل. Low Coupling: الـmodules مستقلة—تغيير واحد لا يؤثر على الآخر. العلاقة: High Cohesion تُؤدي عادةً لـLow Coupling. Signs of Low Cohesion: class/module تعمل أشياء كثيرة غير مترابطة. Signs of High Coupling: تغيير صغير يكسر أشياء كثيرة.", senior: "Cohesion وCoupling وجهان لعملة واحدة—رتّب الكود حول business concepts لتحصل على كليهما تلقائياً." },
      { q: "كيف تُصمّم نظام لـDisaster Recovery؟", a: "RPO (Recovery Point Objective): كم بيانات يمكن فقدانها. RTO (Recovery Time Objective): كم يستغرق الاسترداد. Strategies: Backup & Restore (RPO/RTO: ساعات)، Pilot Light (RPO/RTO: عشرات الدقائق)، Warm Standby (RPO/RTO: دقائق)، Multi-Site Active/Active (RPO/RTO: ثوانٍ). Data replication عبر Regions. Regular DR Drills.", senior: "DR plan بدون اختبار منتظم ورقة بدون قيمة—جدوّل DR drills كل ربع سنة على الأقل." },
      { q: "اشرح مفهوم Data Mesh Architecture.", a: "Data Mesh: توزيع ملكية البيانات على الـdomain teams. Principles: Domain-Oriented Ownership، Data as a Product، Self-Serve Data Platform، Federated Computational Governance. كل domain تمتلك Data Product خاصها. Data Catalog للاكتشاف. Contrast مع Data Lake/Warehouse المركزي. مفيد للـlarge orgs بـmany domains.", senior: "Data Mesh تعني تحويل teams لـdata product owners—تحدي تنظيمي أكبر من التقني. ابدأ بـpilot domain." },
      { q: "ما هي أنماط Scalability في Architecture؟", a: "Horizontal Scaling: إضافة instances. Vertical Scaling: زيادة الـresources. Read Replicas: للـread-heavy workloads. Caching: لتقليل DB load. Sharding: توزيع الـdata. Async Processing: queue لـheavy operations. CDN: للـstatic content. Stateless Design: إلزامي للـhorizontal scaling. Auto Scaling: تلقائي بناءً على metrics.", senior: "Scalability ليست هدفاً بذاتها—صمّم للـload الحالي مع مسار واضح للتوسع. Over-scaling مُكلف." },
      { q: "اشرح كيف تُطبّق مبدأ Separation of Concerns.", a: "SoC: كل module تهتم بمسؤولية واحدة. في Web: Routing، Middleware، Controller، Service، Repository طبقات منفصلة. في Frontend: UI Components، Business Logic، Data Fetching، State Management. في microservices: services منفصلة حسب domain. مزايا: تغيير في طبقة لا يؤثر على الأخرى. Testing كل طبقة بشكل مستقل.", senior: "SoC على مستوى الـarchitecture أهم من مستوى الـfunction—boundaries واضحة بين layers وdomains." },
      { q: "كيف تُصمّم نظام لـCompliance وAuditability؟", a: "Audit Log: كل action مُسجَّل مع: who، what، when، from where. Immutable Audit Trail: لا delete للـlogs. Event Sourcing: يُوفر audit trail تلقائياً. GDPR Compliance: right to erasure، data minimization. Encryption at rest وin transit. Data Residency: بيانات في region محددة. Access Control Logs. Regular Compliance Audits. Data Retention Policies.", senior: "Audit logging يجب أن يكون إلزامياً في الـarchitecture لا optional—الامتثال متطلب قانوني في معظم القطاعات." },
      { q: "ما هو الفرق بين REST وgRPC وGraphQL وmتى تستخدم كلاً منها؟", a: "REST: simple، widely understood، cacheable، يعمل مع browsers مباشرة. gRPC: binary protocol، سريع جداً، bi-directional streaming، مثالي لـinternal services. GraphQL: flexible queries، client يحدد الـdata، مثالي لـcomplex data graphs وmobile (bandwidth-sensitive). gRPC للـinternal microservices communication. REST أو GraphQL للـexternal APIs.", senior: "الـdefault: REST للـexternal، gRPC للـinternal. أضف GraphQL فقط حين تعاني فعلاً من over/under-fetching." },
      { q: "اشرح Microservices Testing Strategies.", a: "Consumer-Driven Contract Testing (Pact): يتحقق من توافق الـAPI بين services. Component Testing: اختبار service كاملة بـin-memory dependencies. Integration Testing: test مع DB والـinfrastructure الحقيقية. E2E Testing: أقل عدداً، أكثر تكلفةً. Test Doubles: Stubs وFakes وMocks. Service Virtualization: محاكاة external services. Test Data Management.", senior: "Contract Testing يُحل مشكلة integration testing في microservices—اكتشف الـbreaking changes قبل deploy." }
    ]
  },
  {
    id: "perf", label: "Performance", icon: "ti-rocket", color: "#f43f5e",
    questions: [
      { q: "ما هي Core Web Vitals وكيف تُحسّنها؟", a: "LCP (Largest Contentful Paint): يجب أن يكون < 2.5s. FID/INP (Interaction to Next Paint): < 200ms. CLS (Cumulative Layout Shift): < 0.1. لتحسين LCP: تحسين الصورة الرئيسية (WebP، preload، CDN)، Server Response Time تحته < 600ms. لتحسين INP: تقليل long tasks، code splitting، Web Workers. لتحسين CLS: reserve space للصور والـads مسبقاً.", senior: "INP يستبدل FID في 2024—يقيس responsiveness الفعلي طوال الجلسة لا فقط الأول click. ابدأ القياس الآن." },
      { q: "اشرح JavaScript Performance Optimization Techniques.", a: "تقليل Main Thread: Web Workers للـheavy computation. Code Splitting: dynamic import لـlazy loading. Tree Shaking: إزالة الكود غير المستخدم. Bundle Analysis: @next/bundle-analyzer، webpack-bundle-analyzer. مشاكل شائعة: forced synchronous layouts (layout thrashing)، long tasks (>50ms)، memory leaks. requestAnimationFrame لـanimations. قياس: Chrome DevTools Performance tab.", senior: "Long Tasks (>50ms) أكبر عدو لـINP—قسّمها بـscheduler.yield() أو setTimeout(0) لتجنب blocking الـmain thread." },
      { q: "كيف تُحسّن Web Performance بـCritical Rendering Path؟", a: "Critical Rendering Path: HTML Parsing → DOM → CSSOM → Render Tree → Layout → Paint. تسريعه: Inline Critical CSS. تأجيل non-critical CSS بـmedia queries. defer/async للـJS. Preload للـcritical assets. Resource Hints: preconnect للـorigins الخارجية. HTTP/2 multiplexing. Server Push للـcritical resources. تقليل render-blocking resources.", senior: "أهم تحسين: preconnect لـ3rd party origins وpreload للـLCP image—يُقلل TTFB وLCP بشكل كبير." },
      { q: "اشرح Memory Management في JavaScript وطرق كشف Leaks.", a: "GC في JS: Mark-and-Sweep. Memory Leaks أسباب: closures تمسك references غير ضرورية، event listeners غير مُزالة، global variables تتراكم، detached DOM nodes، setInterval بدون clearInterval. الكشف: Chrome DevTools Memory tab → Heap Snapshot → مقارنة snapshots. Performance Monitor لـlive memory. WeakMap/WeakRef للـcaching بدون leaks.", senior: "أكثر leak شيوعاً في React: event listeners في useEffect بدون cleanup. دائماً return cleanup function." },
      { q: "ما هي تقنيات Image Optimization في Web؟", a: "Formats: WebP (30% أصغر من JPEG)، AVIF (50% أصغر)، SVG للـicons. Responsive images: srcset وsizes attributes. Lazy Loading: loading='lazy'. Priority hint: fetchpriority='high' للـLCP. Compression: lossy vs lossless. CDN مع automatic format negotiation. Blur placeholder أثناء التحميل. Skeleton screens. next/image يُتيح كل هذا تلقائياً.", senior: "AVIF الأحدث والأصغر لكن أبطأ في التحميل على بعض الأجهزة—WebP أكثر أماناً للـcompatibility الآن." },
      { q: "اشرح HTTP Caching وCache-Control Headers.", a: "Cache-Control: max-age (وقت التخزين بالثواني)، no-cache (يجب التحقق من السيرفر)، no-store (لا تخزين)، immutable (لا يتغير)، public/private. ETag: fingerprint للـresponse للتحقق من التغيير. Last-Modified. استراتيجية: static assets (JS/CSS/images) بـhash في الاسم → max-age=31536000,immutable. HTML → no-cache. API responses → max-age حسب الحاجة.", senior: "Content-hashed assets مع long cache + no-cache للـHTML هي الاستراتيجية المثلى—zero stale content مع caching أقصى." },
      { q: "كيف تُحسّن Database Query Performance؟", a: "Indexes: على columns في WHERE، ORDER BY، JOIN. EXPLAIN ANALYZE: لفهم الـquery plan. N+1 Problem: حلّه بـJOIN أو eager loading أو DataLoader. Pagination: cursor-based بدل offset للـlarge datasets. Connection Pooling. Read Replicas لـread-heavy workloads. Query Result Caching. Partial Indexes للـfiltered queries. Composite Indexes: ترتيب الأعمدة مهم.", senior: "N+1 problem أكثر performance bug شيوعاً في ORMs—فعّل slow query logging واكتشفها في staging." },
      { q: "اشرح Web Worker وService Worker والفرق بينهما.", a: "Web Worker: thread منفصل للـJS. للـheavy computation بدون blocking الـUI. تواصل بـpostMessage. لا DOM access. Shared Worker: يُشارك بين tabs متعددة. Service Worker: proxy بين الـapp والـnetwork. للـoffline، caching، push notifications، background sync. يعمل حتى بعد إغلاق الـpage. Workbox library تُبسّط Service Worker.", senior: "Service Worker يُتيح تجربة offline-first حقيقية—استخدم Workbox مع precaching للـapp shell وruntime caching للـAPI." },
      { q: "ما هي أهم Lighthouse Metrics وكيف تُحسّنها؟", a: "Performance (LCP, FID/INP, CLS, FCP, TTI, TBT). Accessibility: ARIA، contrast، focus. Best Practices: HTTPS، no errors، modern APIs. SEO: meta tags، robots.txt، links. PWA: service worker، manifest. تحسين TTI: تقليل JS parsing وexecution. تحسين TBT: code splitting، defer JS. FCP: تحسين TTFB والـcritical rendering path.", senior: "Lighthouse score ليس هدفاً—تحسين Core Web Vitals من Real User Monitoring (RUM) الهدف الفعلي." },
      { q: "اشرح Lazy Loading Strategies للـWeb.", a: "Images: loading='lazy' (native)، IntersectionObserver (للتحكم). JavaScript: dynamic import()، React.lazy()، Next.js dynamic(). Routes: code splitting تلقائي في Next.js/Vite. Components: lazy load below-fold components. Video: preload='none' أو 'metadata'. Data: infinite scroll أو load more. Fonts: font-display: optional للـnon-critical.", senior: "المبالغة في lazy loading ضارة—LCP image يجب أن تُحمَّل بـpriority، لا lazy. حدّد ما هو critical وما هو deferred." },
      { q: "كيف تُقيس Web Performance بشكل صحيح؟", a: "Lab Data: Lighthouse، WebPageTest، Chrome DevTools. Field Data (RUM): Google Analytics، web-vitals library، Datadog RUM. CrUX (Chrome User Experience Report): بيانات حقيقية من المستخدمين. PageSpeed Insights: يجمع Lab + Field. Web Vitals library: `onLCP`, `onINP`, `onCLS` callbacks. الأدوات: SpeedCurve، Calibre للـmonitoring المستمر.", senior: "Field data أهم من lab data—lab يقيس في ظروف مثالية بينما field يعكس تجربة المستخدمين الفعلية." },
      { q: "اشرح Resource Hints وPreloading Strategies.", a: "preload: الـresource مطلوب قريباً في نفس الـpage. prefetch: الـresource للـnavigation القادمة. preconnect: فتح TCP+TLS connection لـorigin مسبقاً. dns-prefetch: DNS lookup فقط (أخف). modulepreload: للـES modules. as attribute: يُحدد نوع الـresource للـpriority. لا تُسرف في preload—كل resource يُضاف لـbandwidth budget.", senior: "preconnect لكل 3rd party origin (fonts.googleapis.com، cdn.example.com)—يُوفر 100-300ms من الـconnection time." },
      { q: "ما هو التأثير الأداري لـReact Re-renders وكيف تُحسّنه؟", a: "Re-renders تحدث: state أو props تتغير. React.memo للـcomponents التي تتلقى نفس الـprops. useMemo للـexpensive computations. useCallback للـfunctions المُمرَّرة كـprops. Context: تقسيم الـcontext لمنع re-renders غير ضرورية. قياس: React DevTools Profiler. Virtualization للـlong lists (react-virtual). Key prop صحيح في lists.", senior: "لا تُطبّق optimizations قبل القياس—premature optimization مُضيعة للوقت. قس بـProfiler أولاً." },
      { q: "اشرح Rendering Strategies وSSR/SSG/CSR Performance.", a: "CSR: TTFB سريع، FCP/LCP بطيء (JS يُنفَّذ أولاً). SSR: FCP/LCP أسرع، TTFB أبطأ. SSG: أسرع كل شيء، محتوى static. ISR: توازن بين freshness والـperformance. Hydration Cost: SSR يتطلب hydration على client. Partial Hydration/Islands Architecture: Astro، Qwik تُقلل JS الكلي. Streaming SSR يُحسّن TTFB.", senior: "SSG للمحتوى الثابت، SSR مع Streaming للـdynamic. Islands Architecture مستقبل أداء الـWeb." },
      { q: "كيف تُحسّن CSS Performance؟", a: "Avoid: @import في CSS (blocking)، universal selectors كـ*، complex selectors بعمق كبير. Use: CSS containment (contain property). content-visibility: auto للـoffscreen content. will-change للـanimated elements (بحذر). CSS animations بدل JS animations (يعمل على GPU). Avoid layout thrashing: لا تقرأ وتكتب DOM في نفس الـframe. CSSStyleDeclaration batch updates.", senior: "content-visibility: auto أكبر CSS performance gain للـlong pages—يُخفّض rendering time بـ50%+ للـoffscreen content." },
      { q: "اشرح Performance Budget وكيف تُطبّقه.", a: "Performance Budget: حدود للـmetrics (bundle size، LCP، etc.). أمثلة: JS < 150KB، LCP < 2.5s، CLS < 0.1. أدوات: Lighthouse CI، bundlesize، size-limit. تطبيق في CI: يفشل الـbuild عند تجاوز البودجت. Webpack Performance Hints. اتفاق الفريق على الـbudget قبل البناء. مراقبة مستمرة، لا فحص مرة واحدة فقط.", senior: "Performance budget في CI يمنع regression تلقائياً—مفيد خصوصاً للـteams الكبيرة حيث يُضيف كل شخص مكتبة." },
      { q: "ما هو requestAnimationFrame وmتى يُستخدم؟", a: "rAF: يُنفّذ callback قبل browser paint—مُزامَن مع refresh rate (عادة 60fps = 16.7ms). استخدامه: animations بـJS، scroll-based effects. بدلاً من setTimeout للـanimations. يُلغى تلقائياً عند الـtab يصبح hidden. cancelAnimationFrame للإلغاء. لـthrottling أحداث scroll/resize: رسّمها بـrAF. CSS animations أفضل لـgpu-accelerated animations.", senior: "استخدم rAF للـanimations التي تحتاج JS logic، وCSS transitions/animations لكل ما يمكن عبر CSS—GPU acceleration تلقائية." },
      { q: "اشرح Virtual Scrolling وList Virtualization.", a: "Virtualization: تُعرض فقط الـitems المرئية في الـviewport. بدلاً من 10,000 DOM nodes → 50 فقط. Libraries: react-virtual، react-window، TanStack Virtual. آلية العمل: تتبع scrollTop، حساب أول وآخر item مرئي، render هذه الـitems فقط مع offset محسوب. مناسب: tables كبيرة، feeds لا نهاية لها. تحدي: autofocus، keyboard nav.", senior: "10K items بدون virtualization → browser hang مؤكد. الحد: > 100-200 items مع complex content—ابدأ virtualization." },
      { q: "كيف تُحسّن Server Response Time (TTFB)؟", a: "TTFB يشمل: DNS resolution، TCP connection، SSL handshake، Server processing، First byte. تحسين: CDN للـstatic وSSR. Edge Computing للـserver-side processing أقرب للمستخدم. DB query optimization. Connection pooling. Caching responses. HTTP/2 أو HTTP/3. Server infrastructure upgrade. طهارة DNS TTL. Keep-alive connections.", senior: "TTFB > 800ms مشكلة حرجة—ابحث في server logs عن slow endpoints وDB queries. CDN يُحل جزء الـnetwork." },
      { q: "اشرح Compression Techniques للـWeb.", a: "Gzip: ضغط قديم، واسع الدعم. Brotli: أحدث، أفضل بـ15-25%، يدعمه معظم browsers الحديثة. Static assets: ضغط وقت build. Dynamic content: ضغط على السيرفر. تفعيل: Nginx (gzip on; brotli on)، Cloudflare تلقائياً. Images: WebP/AVIF ضغطها الخاص. JSON API: gzip يُقلص بـ70-90%. لا تضغط images مضغوطة أصلاً.", senior: "Brotli على nginx أو Cloudflare تلقائياً—خطوة واحدة تُقلل transfer size بـ20-30% للـtext assets." },
      { q: "ما هو الفرق بين Performance وScalability؟", a: "Performance: كيف يتصرف النظام مع load حالي—latency، throughput، resource usage. Scalability: قدرة النظام على التعامل مع load متزايد—horizontal وvertical. يمكن أن يكون النظام: سريع (performant) لكن غير قابل للتوسع. بطيء لكن قابل للتوسع. كلاهما مهم: performance للـuser experience، scalability للـbusiness growth. قسهما بشكل منفصل.", senior: "حسّن الـperformance أولاً—النظام البطيء على server واحد سيكون بطيئاً على 100. Scale لاحقاً." },
      { q: "اشرح Profiling وPerformance Analysis في Node.js.", a: "Node.js Profiling: --prof flag (V8 profiler)، clinic.js (flame graphs)، 0x. حالات: CPU-bound (profiler)، Memory leaks (heap snapshots)، I/O waits (async profiling). Chrome DevTools: يتصل بـNode.js بـ--inspect. Event loop lag: perf_hooks. Express middleware timing. p95/p99 latency الأهم من الـaverage. APM tools: Datadog، New Relic.", senior: "p99 latency يكشف الـtail latency التي تؤثر على نسبة الـusers—الـaverage يُخفي المشكلات الخفية." },
      { q: "كيف تُحسّن React application Performance عملياً؟", a: "1) قِس بـProfiler أولاً. 2) Code splitting بـReact.lazy للـroutes والـheavy components. 3) Virtualize long lists. 4) تجنّب anonymous function في render. 5) قسّم الـContext لتجنب re-renders. 6) Images محسّنة. 7) الـdev tools Profiler لتحديد expensive renders. 8) Suspense للـdata loading. 9) useDeferredValue للـnon-critical updates.", senior: "ابدأ بـbundle analysis (bundle-analyzer)—المكتبات الضخمة غير المستخدمة أو المُكرَّرة أكبر مشكلة في معظم التطبيقات." },
      { q: "اشرح HTTP/2 وHTTP/3 وتأثيرهما على Performance.", a: "HTTP/2: Multiplexing (طلبات متعددة على connection واحد)، Header Compression (HPACK)، Server Push. يُلغي حاجة domain sharding وsprite sheets. HTTP/3: يبني فوق QUIC (UDP-based)، يُقلل connection setup time، يتجاوز packet loss بشكل أفضل. وقت Handshake: HTTP/3 = 0-RTT. يدعمه معظم CDNs تلقائياً. HTTPS مطلوب لكليهما.", senior: "HTTP/2 مُفعَّل تلقائياً بـCloudflare/CDNs. HTTP/3 يستحق التفعيل في Edge—يُحسّن الـmobile performance على شبكات غير مستقرة." },
      { q: "ما هو مفهوم Tree Shaking وكيف يعمل؟", a: "Tree Shaking: إزالة الكود غير المستخدم (dead code) من الـbundle. يعمل فقط مع ES Modules (import/export). Rollup وWebpack و Vite يدعمونه. شروط: 1) ES Modules. 2) Package يضع sideEffects: false في package.json. 3) لا dynamic imports بـvariables. مشاكل: barrel files تكسر tree shaking. Named imports من lodash-es آمنة.", senior: "Barrel files (index.ts تُعيد كل شيء) تكسر tree shaking—استبدلها بـdirect imports أو ضمن strict exports." },
      { q: "اشرح Cumulative Layout Shift وكيف تمنعه.", a: "CLS: مجموع تغييرات layout غير متوقعة × نسبة الـviewport المتأثرة. أسباب: صور بدون أبعاد، محتوى dynamic يُحمَّل بعد render، fonts تسبب FOUT، ads مُحجوزة بحجم أصغر. حلول: width وheight على كل img. aspect-ratio CSS. font-display: optional. Reserve space للـad slots. skeleton loaders بنفس الحجم. CSS contain.", senior: "أسهل fix: أضف width وheight لكل صورة في HTML—browser يحجز المساحة قبل تحميل الصورة." },
      { q: "كيف تُحسّن Font Loading Performance؟", a: "font-display: swap (يعرض fallback font فوراً، يُبدّل عند التحميل). font-display: optional (يُلغي الـfont إذا لم يُحمَّل في 100ms). Preload الـcritical fonts: <link rel='preload' as='font'>. استخدم system fonts للـperformance الأقصى. Subset الـfont لـcharacters المستخدمة فعلاً. Variable fonts: ملف واحد بدل ملفات متعددة. Self-host بدل Google Fonts.", senior: "font-display: optional مع preload يُعطي LCP ممتاز—لا layout shift ولا invisible text. المثالي لـbody fonts." },
      { q: "اشرح مفهوم Prerendering وStatic Site Generation Performance.", a: "SSG يُولِّد HTML وقت build—يُخدَّم من CDN بدون server processing وقت runtime. أسرع TTFB ممكن. مثالي: مدونات، docs، marketing pages. ISR: يُجمع بين SSG السرعة وSSR الـfreshness. Edge rendering: HTML قريب من المستخدم. Jamstack: architecture مبنية على prerendering. أداء Lighthouse ممتاز تلقائياً مع SSG.", senior: "SSG الأسرع—كل ثانية من الـbuild تُوفّر milliseconds لملايين المستخدمين. استثمر في build optimization." },
      { q: "ما هو Interaction to Next Paint وكيف تُحسّنه؟", a: "INP: يقيس تأخير الاستجابة لكل interaction خلال الجلسة. الهدف < 200ms. مكونات: Input Delay + Processing Time + Presentation Delay. أسباب ضعف INP: Long Tasks على Main Thread، Event handlers ثقيلة، Rendering بطيء. حلول: Code Splitting، Web Workers، scheduler.postTask، تأجيل non-critical work. قياس: real user data بـweb-vitals library.", senior: "INP يقيس worst interaction لا أول—المشاكل تظهر بعد تفاعل المستخدم مع الـapp. قس مع real users." },
      { q: "اشرح SQL Query Optimization Techniques.", a: "EXPLAIN ANALYZE: قرأ الـquery plan. Index Scans بدل Sequential Scans. Covering Indexes تتضمن SELECT columns. Avoid SELECT * في production. Avoid functions في WHERE clause على indexed columns. Use CTEs للقابلية للقراءة لا الـperformance. Avoid N+1. Batch operations بدل queries متكررة. Partition pruning مع الـindexes الصحيحة.", senior: "أهم: فهم الـquery plan—Seq Scan على table كبير = missing index. EXPLAIN ANALYZE يُريك بالضبط أين الوقت يُضيَّع." },
      { q: "ما هي تقنيات Preloading وPrefetching الصحيحة؟", a: "Preload: لـresources مطلوبة في الـpage الحالية (LCP image، critical font، CSS). Prefetch: لـresources للـnavigation القادمة المحتملة. Preconnect: لـorigins ستتصل بها (fonts.googleapis.com). ModulePreload: للـES Modules. لا تُفرِط: كل preload يُنافس الـcritical path. استخدم Lighthouse لاكتشاف الـopportunities.", senior: "Rule of thumb: preload LCP image + preconnect critical 3rd parties = أسرع شيء يمكنك فعله بدقيقتين." }
    ]
  },
  {
    id: "dsa", label: "DSA & Algorithms", icon: "ti-binary-tree", color: "#a78bfa",
    questions: [
      { q: "ما هو Big O Notation وكيف تُحسب Complexity؟", a: "Big O: وصف أسوأ حالة لـcomplexity خوارزمية. O(1): ثابت. O(log n): logarithmic. O(n): linear. O(n log n): linearithmic. O(n²): quadratic. O(2^n): exponential. O(n!): factorial. التحسيب: تجاهل الثوابت والـterms الأصغر. المثال: O(3n + 5) = O(n). للمسائل المعقدة: انظر للـloop nesting والـrecursion depth.", senior: "في المقابلة: اذكر Time AND Space complexity. الـspace complexity مهمة جداً وكثيراً ما تُنسى." },
      { q: "اشرح Binary Search وتطبيقاته.", a: "Binary Search: O(log n) على sorted array. template: low=0, high=n-1. while(low<=high): mid=low+(high-low)/2. إذا arr[mid]==target: return mid. إذا arr[mid]<target: low=mid+1. إذا arr[mid]>target: high=mid-1. تطبيقات: بحث في sorted array، First/Last position، بحث في answer space (binary search على القيمة).", senior: "binary search on answer space pattern قوي جداً: 'أقل x يُحقق شرطاً' = binary search على x وفحص الشرط." },
      { q: "اشرح Linked List وعملياتها الأساسية.", a: "Linked List: nodes مترابطة بـpointers. Singly: next pointer فقط. Doubly: next وprev. Circular: tail يشير للـhead. العمليات: Insert/Delete O(1) بمعرفة الـnode. Search O(n). أنماط مهمة: Two Pointers (Floyd's Cycle Detection)، Reverse List، Find Middle (slow/fast pointers). Dummy Head Node يبسّط edge cases كثيراً.", senior: "Two pointers pattern يحل معظم linked list problems: cycle detection, find middle, kth from end. تعلّمه جيداً." },
      { q: "كيف تعمل Stack وQueue وأين تُستخدمان؟", a: "Stack: LIFO. Push وpop وpeek. O(1) للكل. استخدامات: function call stack، undo/redo، parentheses matching، DFS. Queue: FIFO. Enqueue وdequeue. O(1) مع linked list. استخدامات: BFS، task scheduling، print queue. Deque: doubly-ended. Priority Queue (Heap): الأعلى أولوية يُعالَج أولاً.", senior: "Monotonic Stack pattern (أكبر/أصغر element التالي) يحل مجموعة كبيرة من problems بشكل elegant." },
      { q: "اشرح Binary Tree والـTraversal Algorithms.", a: "Binary Tree: كل node لها أقصى 2 children. Traversals: Pre-order (Root, Left, Right)، In-order (Left, Root, Right)—يُعطي sorted order في BST، Post-order (Left, Right, Root). Level-order (BFS) بـQueue. Recursive وIterative implementations. Height: O(n). BST: O(log n) للـbalanced، O(n) للـskewed.", senior: "Iterative in-order بـstack مهم جداً في المقابلات—يُظهر فهمك للـcall stack الضمني." },
      { q: "اشرح Graph Traversal: BFS وDFS.", a: "BFS: Queue. Explores level by level. أسرع لـshortest path (unweighted). O(V+E). DFS: Stack (recursive أو explicit). Explores depth-first. أسرع لـcycle detection وtopological sort. BFS للـshortest path بعدد العقبات. DFS للـall paths، components، backedge detection. Visited set لمنع infinite loops. Adjacency list أفضل من matrix للـsparse graphs.", senior: "BFS للأسئلة 'أقصر مسار' أو 'أقل خطوات'—DFS لكل شيء آخر كـcomponents وcycles وpaths." },
      { q: "ما هو Dynamic Programming وكيف تُطبّقه؟", a: "DP: تقسيم المشكلة لـsubproblems مع حفظ النتائج. شرطان: Optimal Substructure + Overlapping Subproblems. Top-Down (Memoization): recursive مع cache. Bottom-Up (Tabulation): iterative من الأصغر للأكبر. خطوات: 1) حدد الـstate. 2) اكتب الـrecurrence relation. 3) حدد base cases. 4) طبّق top-down أو bottom-up. 5) حسّن Space complexity.", senior: "ابدأ بـrecursive solution وحوّلها لـmemo—أسهل للتفكير. البداية بـbottom-up مباشرة أصعب." },
      { q: "اشرح Sorting Algorithms وComplexities.", a: "Bubble Sort: O(n²)—للتعليم فقط. Selection Sort: O(n²). Insertion Sort: O(n²) worst، O(n) best—للـsmall/nearly sorted. Merge Sort: O(n log n) always—stable، extra space. Quick Sort: O(n log n) average، O(n²) worst—in-place، cache friendly. Heap Sort: O(n log n)—in-place. Counting Sort: O(n+k)—للـintegers في range محدود.", senior: "في المقابلة: Merge Sort الأكثر طلباً لفهمه. Quick Sort في الواقع بسبب cache performance. لا تنسَ Stability كـproperty." },
      { q: "ما هو Binary Search Tree وعمليات الـBalancing؟", a: "BST: left < root < right. O(log n) لـinsert/delete/search في balanced. O(n) في skewed. Self-balancing: AVL Tree (height difference ≤1)، Red-Black Tree (used in std::map, Java TreeMap). Rotations: Left وRight لإعادة التوازن. B-Tree: للـdatabases (أكثر children). الـrotation operations في المقابلة نادرة لكن مفهوم الـbalancing مهم.", senior: "BST problems كثيرة في المقابلات—validation، LCA، kth smallest. تعلّمها كلها وممارسة in-order traversal." },
      { q: "اشرح Hash Table وحل الـCollisions.", a: "Hash Table: O(1) average للـinsert/delete/lookup. Hash function: key → index. Collisions: Chaining (linked list في كل bucket) أو Open Addressing (Linear/Quadratic Probing). Load Factor: عدد elements / عدد buckets. Resizing: عادة عند 0.7. Worst case: O(n) مع كثير collisions. JS object وMap مبنيان عليه.", senior: "Hash Map لكل problem تحتاج O(1) lookup—تُسرّع كثير من solutions من O(n²) إلى O(n)." },
      { q: "كيف تحل Two Pointers Problems؟", a: "Two Pointers: مؤشران يُحسّنان nested loops. Opposite Ends: (0 وn-1) للـsorted arrays—Two Sum، Container with Most Water. Same Direction: slow/fast—Remove Duplicates، Find Middle. Sliding Window: نافذة متحركة للـsubarray problems. مثال: Two Sum in sorted array → إذا sum < target: right++، إذا sum > target: left--. O(n) بدل O(n²).", senior: "Sliding Window و Two Pointers حلا 80% من string وarray problems في المقابلات. أتقنهما جيداً." },
      { q: "اشرح Heap وPriority Queue.", a: "Heap: Complete Binary Tree. Max-Heap: parent > children. Min-Heap: parent < children. heapify: O(n). insert: O(log n). extractMax/Min: O(log n). peek: O(1). استخدامات: Priority Queue، Heap Sort، Top-K elements، Merge K sorted lists. Python: heapq (min-heap). Java: PriorityQueue. الـTop-K pattern: heap بحجم K.", senior: "Top-K elements بـheap: O(n log k) أفضل من sort O(n log n) حين k صغيرة. pattern شائع جداً في المقابلات." },
      { q: "ما هو Sliding Window Pattern وأنواعه؟", a: "Fixed Window: نافذة بحجم ثابت k—تحرّك right وأزل left كل خطوة. Variable Window: نافذة تتوسع أو تضيق بناءً على شرط. الأكثر استخداماً: Longest Substring Without Repeating Characters، Minimum Window Substring، Maximum Sum Subarray. أداء: O(n) بدل O(n²) لـnested loops. يستخدم عادةً HashMap أو set للتتبع.", senior: "Variable sliding window: expand right حين الشرط غير مُحقَّق، shrink left حين مُحقَّق—أو العكس حسب المسألة." },
      { q: "اشرح Depth-First Search على Graphs.", a: "DFS Graph: visited set لتجنب الحلقات. Recursive أو Stack iterative. Applications: Connected Components، Cycle Detection، Topological Sort، SCC (Tarjan's)، Path finding. Topological Sort بـDFS: أضف للـresult بعد visit كل neighbors (post-order). Detect Cycle: back edge في DFS = cycle. Colors: WHITE/GRAY/BLACK للـdetailed state.", senior: "DFS post-order = Topological Sort. اعكس النتيجة. Cycle إذا وصلت لـGRAY node أثناء DFS على directed graph." },
      { q: "ما هو Greedy Algorithm وكيف تتحقق من صحته؟", a: "Greedy: يختار الخيار الأفضل محلياً في كل خطوة. يعمل عندما: Greedy Choice Property (الخيار المحلي يُوصل للـoptimal) + Optimal Substructure. أمثلة: Activity Selection، Huffman Coding، Dijkstra، Kruskal. التحقق: Exchange Argument (أثبت أن تبديل الخيار الـgreedy بأي خيار آخر لا يُحسّن النتيجة). إذا فشل: DP.", senior: "تحقق Greedy بـproof أو counter-example—أمثلة بسيطة كثيراً ما تكسر الـgreedy وتُثبت الحاجة لـDP." },
      { q: "اشرح Trie (Prefix Tree) وتطبيقاته.", a: "Trie: شجرة للـstrings. كل edge = character. Root = فارغ. isEnd بالـleaf. عمليات: Insert O(m)، Search O(m)، StartsWith O(m) حيث m = طول الكلمة. تطبيقات: Autocomplete، Spell Checker، IP Routing، Word Search. Space: O(ALPHABET_SIZE * N * M). Compressed Trie للـoptimization.", senior: "Trie أفضل من HashMap للـprefix queries—يُبقيك O(m) بينما HashMap يحتاج قائمة كل prefixes." },
      { q: "كيف تحل Graph Shortest Path Problems؟", a: "Unweighted: BFS → O(V+E). Weighted Non-negative: Dijkstra → O((V+E) log V) بـheap. Weighted با negative edges: Bellman-Ford → O(VE). All pairs: Floyd-Warshall → O(V³). DAG: Topological Sort + relaxation → O(V+E). APSP مع negative: Johnson's algorithm. A*: للـheuristic-guided search.", senior: "Dijkstra خطأ مع negative edges—استخدم Bellman-Ford. Negative cycles: Bellman-Ford يكشفها في pass الـVth." },
      { q: "اشرح Backtracking والفرق بينه وبين DFS.", a: "Backtracking: DFS مع pruning—يُلغي الـpath إذا لم يُوصل للـsolution. أكثر كفاءة من Brute Force. Template: Choose، Explore، Unchoose. تطبيقات: Permutations، Combinations، N-Queens، Sudoku Solver، Word Search. DFS يكمل حتى النهاية. Backtracking يُلغي مبكراً. Complexity: يُقلل من O(n!) عملياً.", senior: "Pruning جودة الـbacktracking—كلما مبكراً تُقرر أن الـpath لا تُوصل للـsolution، كلما أسرع." },
      { q: "ما هو Union-Find وتطبيقاته؟", a: "Union-Find (Disjoint Set Union): هيكل بيانات لتتبع مجموعات منفصلة. find: يجد ممثل المجموعة. union: يدمج مجموعتين. مع Path Compression وUnion by Rank: quasilinear O(α(n)) ≈ O(1) عملياً. تطبيقات: Kruskal's MST، Detect Cycle في Undirected Graph، Connected Components، Dynamic Connectivity.", senior: "Union-Find للـdynamic connectivity مشكلات—Kruskal بدونه يُعقَّد. Path compression لازم للـefficiency." },
      { q: "اشرح Divide and Conquer Paradigm.", a: "Divide and Conquer: قسّم المشكلة → حل الأجزاء → ادمج النتائج. Recurrence: T(n) = aT(n/b) + f(n). Master Theorem لحل الـrecurrence. أمثلة: Merge Sort، Quick Sort، Binary Search، Karatsuba Multiplication، FFT. في المقابلة: Closest Pair of Points، Maximum Subarray (Kadane's أسرع لكن D&C يُعلّمك المبدأ).", senior: "Recurrence relation الخطوة الأصعب—تعلّم Master Theorem أو tree method لحلها سريعاً." },
      { q: "كيف تُصمّم LRU Cache؟", a: "LRU (Least Recently Used): O(1) لـget وput. Data Structures: HashMap + Doubly Linked List. HashMap: key → node في الـlist. List: most recent في الـhead، least recent في الـtail. get: move node للـhead. put: إضافة للـhead، احذف tail إذا امتلأ. Dummy head وdummy tail لتبسيط edge cases.", senior: "LRU Cache مسألة كلاسيكية تجمع HashMap وLinked List—ضع pseudo-code أولاً ثم اكتب الكود بعناية." },
      { q: "اشرح Minimum Spanning Tree وAlgorithms.", a: "MST: الشجرة التي تضم كل vertices بأقل وزن إجمالي للـedges. Kruskal's: sort edges بالوزن، أضف edge إذا لا تُنشئ cycle (Union-Find). O(E log E). Prim's: ابدأ من vertex، أضف أقل edge تُوصل للـunvisited. O(E log V) بـheap. استخدامات: Network Design، Clustering، Approximation Algorithms.", senior: "Kruskal أسرع للـsparse graphs، Prim أسرع للـdense graphs. استخدم Union-Find مع Kruskal للـefficiency." },
      { q: "ما هي أنماط Two Pointers الشائعة؟", a: "1) Converging Pointers (sorted array): Two Sum → O(n). 2) Fast/Slow: Floyd's Cycle Detection، Find Middle. 3) Merge Two Arrays: merge step في Merge Sort. 4) Remove Duplicates in-place: slow=0, fast=1. 5) Container With Most Water: max area. 6) Trapping Rain Water. 7) Three Sum: fix one pointer، binary search الآخرين. كل pattern يُحل O(n).", senior: "Three Sum = sort + two pointers على كل element. تُعطيك O(n²) بدل O(n³) البديهي—pattern قوي." },
      { q: "اشرح Graph Topological Sort.", a: "Topological Sort: ترتيب خطي للـvertices بحيث كل edge (u,v) تأتي u قبل v. مُطبَّق فقط على DAGs. Algorithms: Kahn's (BFS-based): أدخل vertices بـin-degree 0 في queue، أزل edges تدريجياً. DFS-based: أضف للـresult في post-order ثم اعكس. Cycle Detection: إذا بقيت vertices بـin-degree > 0 في Kahn's = cycle.", senior: "Kahn's أفضل للـcycle detection والـlevel-by-level processing. DFS للـimplicit topological ordering." },
      { q: "كيف تحل String Manipulation Problems؟", a: "أنماط شائعة: Sliding Window (Longest Substring). Two Pointers (Reverse، Palindrome). HashMap لتتبع الأحرف (Anagram، Permutation). String Builder بدل concatenation لـO(n). KMP Algorithm للـpattern matching O(n+m). Rabin-Karp بـhashing. Z Algorithm. Edit Distance = DP classic. Palindrome Expansion من المركز.", senior: "String problems في المقابلات = HashMap + Sliding Window 80% من الوقت. KMP مطلوب نادراً لكن احفظ مفهومه." },
      { q: "اشرح مفهوم Memoization وكيف تُطبّقه.", a: "Memoization: حفظ نتائج الـfunction calls لإعادة استخدامها. Top-down DP. في JS: Map كـcache بدل object (يدعم أي key). Python: @functools.lru_cache. Template: if(key in cache) return cache[key]; result = compute(key); cache[key] = result. Space: O(unique states). يُحوّل Exponential لـPolynomial complexity.", senior: "مفتاح Memoization: تحديد الـstate بدقة (ما الذي يُميز الـsubproblem uniquely). الـstate يُحدد الـcache key." },
      { q: "ما هو Monotonic Stack وتطبيقاته؟", a: "Monotonic Stack: stack تحافظ على ترتيب monotone (increasing أو decreasing). Increasing Stack: يُعطيك الـelement الأصغر التالي. Decreasing Stack: يُعطيك الـelement الأكبر التالي. تطبيقات: Next Greater Element، Daily Temperatures، Largest Rectangle in Histogram، Trapping Rain Water. O(n) بدل O(n²). كل element يُدخَل ويُخرَج مرة واحدة.", senior: "Monotonic Stack = O(n) حل elegant لمشاكل 'find next greater/smaller'—تعلّم pattern وتطبيقاته الأربعة الرئيسية." },
      { q: "اشرح Dynamic Programming على Subsequences.", a: "LCS (Longest Common Subsequence): dp[i][j] = أطول CS حتى s1[i] وs2[j]. LIS (Longest Increasing Subsequence): O(n²) DP أو O(n log n) بـbinary search. Edit Distance: dp[i][j] = min operations. مفتاح الـDP: جدول 2D عادةً. Recurrence: if(s1[i]==s2[j]): dp[i][j]=dp[i-1][j-1]+1. إلا: max(dp[i-1][j], dp[i][j-1]).", senior: "LIS بـbinary search (Patience Sorting) O(n log n)—ضروري معرفته. طريقة patience sorting فكرة جميلة." },
      { q: "كيف تحل Tree Path Problems؟", a: "أنماط: Max Path Sum (قد يمر بأي node). LCA (Lowest Common Ancestor): Recursive أو Binary Lifting. Path Sum يساوي k: prefix sum + HashMap. Diameter: أطول path. مسار بين node->node. Template عام: recursive تُعيد قيمة مفيدة، وتُحدّث global max. موقف: DFS بـpost-order—الـchildren أولاً ثم الـroot.", senior: "Binary Tree Maximum Path Sum = DFS، في كل node: max contribution = max(0, left, right) + node.val. اعكس التفكير." },
      { q: "ما هي Graph Coloring وتطبيقاتها؟", a: "Graph Coloring: تلوين vertices بحيث لا edge يربط vertex بنفس اللون. Chromatic Number: أقل عدد ألوان. Bipartite Check: هل يكفي لونان؟ (BFS/DFS). 2-Coloring = Bipartite. Application: Register Allocation في compilers، Map Coloring، Scheduling. Bipartite Detection بـBFS: color alternating، إذا تعارض الألوان = not bipartite.", senior: "Bipartite Check مهم جداً في المقابلات—BFS مع التلوين بـ0/1، إذا neighbor نفس اللون = not bipartite." },
      { q: "اشرح Matrix Traversal Problems.", a: "Number of Islands: BFS/DFS من كل '1' غير مزار. Flood Fill. Shortest Path في Matrix: BFS (BFS = shortest path دائماً). Unique Paths: DP. Search a 2D Matrix: Binary Search. Rotate Image: Transpose + Reverse. Spiral Order: حدود (top, bottom, left, right). Diagonal Traversal. Matrix Chain Multiplication: DP.", senior: "BFS على Matrix للـshortest path—أسرع وأبسط من Dijkstra لـunweighted grid. كل cell = node، neighbors = edges." },
      { q: "كيف تُطبّق DP على Intervals؟", a: "Interval DP: الحالة dp[i][j] = أفضل نتيجة للـsubproblem من i لـj. أمثلة: Matrix Chain Multiplication، Burst Balloons، Palindrome Partitioning، Minimum Cost to Merge Stones. Template: for length in range(2, n+1): for i in range(n-length+1): j=i+length-1. O(n³) عادةً. ابدأ بـlength=2، ابنِ للأكبر.", senior: "Interval DP الأصعب نمطاً في DP—الترتيب الصحيح للـloop مهم جداً (length أولاً ثم start)." },
      { q: "اشرح Number Theory Algorithms المهمة.", a: "GCD: Euclidean Algorithm O(log min(a,b)). LCM = a*b/GCD. Sieve of Eratosthenes: كل الأعداد الأولية حتى n بـO(n log log n). Modular Exponentiation: O(log n). Modular Inverse: Extended Euclidean أو Fermat's Little Theorem (n أولي). Chinese Remainder Theorem. في المقابلات: GCD وسيف الأعداد الأولية الأكثر شيوعاً.", senior: "GCD بـEuclidean Algorithm أسرع من المعروف لدى كثيرين—5-10 iterations فقط لأعداد ضخمة." },
      { q: "ما هو Segment Tree وBinary Indexed Tree؟", a: "Segment Tree: يُجيب على Range Queries (Sum، Min، Max) وPoint Updates بـO(log n). يبني في O(n). BIT (Fenwick Tree): أسهل تطبيقاً، يُجيب على prefix sum وpoint update بـO(log n). أبسط من Segment Tree لكن أقل مرونة. Lazy Propagation في Segment Tree للـrange updates أيضاً. استخدامات: range sum queries في competitive programming.", senior: "BIT أسهل تطبيقاً بـ10 سطور وكافٍ لـrange sum. Segment Tree للـcomplex range operations كـmin/max مع updates." },
      { q: "اشرح Fast & Slow Pointers Technique.", a: "Floyd's Cycle Detection: slow يتحرك 1 خطوة، fast يتحرك 2. إذا التقيا = cycle. إيجاد بداية الـcycle: reset slow للـhead، حرّك كليهما 1 خطوة→ يلتقيان عند البداية. Find Middle: slow يصل للـmiddle حين fast يصل للـend. Palindrome Linked List: find middle، reverse second half، compare. Remove Nth from End: fast يتقدم n خطوة أولاً.", senior: "Floyd's Cycle Detection الأكثر طلباً في المقابلات—افهم proofه الرياضي ليس فقط الـimplementation." },
      { q: "كيف تحل Bit Manipulation Problems؟", a: "أساسيات: AND (&)، OR (|)، XOR (^)، NOT (~)، Shift (<<، >>). XOR properties: a^a=0، a^0=a. Tricks: n & (n-1) يُزيل أقل bit. n & -n يُعطي أقل bit. Hamming Weight: count 1s. Single Number: XOR كل الأعداد. Missing Number: XOR الـarray مع 0 to n. Power of 2: n>0 && (n&(n-1))==0.", senior: "XOR trick للـSingle Number من أجمل الـbit manipulation problems—أرِ فهمك لـXOR properties في المقابلة." },
      { q: "اشرح مفهوم Amortized Analysis.", a: "Amortized Analysis: متوسط الـcomplexity لسلسلة من العمليات. Dynamic Array (ArrayList): resize مُكلف O(n) لكن نادر → amortized O(1) للـappend. حساب: Aggregate Method (مجموع / عدد)، Accounting Method (بنك تخيلي)، Potential Method (رياضي). Stack بـMultiPop: O(n) للـmultipop لكن amortized O(1). يُبرر استخدام Dynamic Arrays وHash Tables.", senior: "Amortized analysis ضروري لتبرير Dynamic Array وHash Table performance—المقابل قد يسأل 'لماذا O(1)؟'" },
      { q: "ما هو NP-Complete وكيف تتعامل معه؟", a: "P: مسائل تُحل في polynomial time. NP: يمكن التحقق من الحل في polynomial time. NP-Complete: أصعب مسائل NP (كل NP تُختزل لها). أمثلة: SAT، 3-SAT، Traveling Salesman، Knapsack (decision)، Graph Coloring. للتعامل: Approximation Algorithms، Heuristics، Branch & Bound، Backtracking، لا exact algorithm للـlarge instances. P=NP? سؤال مفتوح.", senior: "إذا صادفت NP-Complete في design: اعترف بذلك واقترح approximation أو heuristic—لا تُضيع وقت في exact solution." },
      { q: "اشرح Recursion وRecursion Tree Analysis.", a: "Recursion Tree: تصوّر الـrecursive calls كشجرة. كل level = تكلفة. Count الـlevels والـcost per level. Merge Sort: T(n) = 2T(n/2) + O(n) → O(n log n)—log n levels × O(n) per level. Fibonacci naive: T(n) = T(n-1) + T(n-2) → O(2^n). Base Cases ضرورية. Stack Overflow: recursion عميق → استخدم iteration أو explicit stack.", senior: "Recursion Tree يُوضح بصرياً الـcomplexity—ارسمه دائماً لـrecursion بـmultiple calls قبل تطبيق Master Theorem." },
      { q: "كيف تُطبّق BFS للـLevel-order Problems؟", a: "BFS يُعطيك nodes level by level. Template: Queue، pop current level كاملاً (بـcurrent size). في كل level: اجمع النتائج وأضف children للـqueue. تطبيقات: Level Order Traversal، Right Side View، Average of Levels، Zigzag Traversal، Minimum Depth of Binary Tree. تحقق من queue.size() قبل الـloop لاستخراج level كامل.", senior: "BFS Level-order trick: `n = queue.size()` ثم loop n مرات = استهلاك level كامل. أساس كثير من tree problems." },
      { q: "اشرح Knapsack Problem وVariants.", a: "0/1 Knapsack: كل item إما تأخذها أو لا. dp[i][w] = max value بـi items وcapacity w. O(n*W). Unbounded Knapsack: يمكن أخذ item عدة مرات. Fractional Knapsack: Greedy (أعلى value/weight أولاً). Subset Sum: هل يوجد subset يساوي target؟ Partition Equal Subset Sum. Coin Change: min coins لمبلغ (unbounded variant).", senior: "الـKnapsack بأنواعه أكثر pattern شيوعاً في DP interviews—اعرف الثلاثة ومتى تُطبق كل منها." },
      { q: "ما هي أهم Tips لمقابلات Algorithms وDSA؟", a: "1) فهم المشكلة قبل الكود—اطرح أسئلة. 2) أمثلة صغيرة أولاً. 3) Brute force أولاً ثم حسّن. 4) فكّر بصوت عالٍ. 5) اكتب pseudo-code قبل الكود الكامل. 6) اختبر edge cases: empty، single element، negative. 7) Time/Space complexity لكل solution. 8) أتقن: arrays، strings، linked lists، trees، graphs، DP، sorting. 9) LeetCode 150 للتدريب.", senior: "Brute force أولاً حتى لو بديهي—يُظهر أنك تفكر. ثم ناقش optimizations. المقابل يريد عملية التفكير لا الـsolution فقط." }
    ]
  }
]
